window.SDG4_GRADES = {"1": [{"ch": 0, "q": "De quoi parle l’Objectif 4 ?", "options": ["Une bonne école pour tous", "Des voitures rapides", "Les grandes villes", "Seulement le sport"], "answer": 0, "explain": "L’Objectif 4 s’appelle éducation de qualité. Il veut que chaque enfant apprenne dans une bonne école.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Combien d’objectifs le monde a-t-il ?", "options": ["5", "17", "10", "50"], "answer": 1, "explain": "Le monde a 17 objectifs de développement durable. L’Objectif 4 concerne l’éducation.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Qui a approuvé les objectifs ?", "options": ["Un seul professeur", "Seulement les enfants", "Les pays du monde, ensemble", "Une grande entreprise"], "answer": 2, "explain": "Tous les pays membres de l’ONU ont approuvé ensemble les objectifs. L’ONU est un groupe de pays.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Chaque enfant peut-il aller à l’école ?", "options": ["Oui, chaque enfant le peut", "Seulement dans les villes", "Seulement en été", "Non, des millions d’enfants ne le peuvent pas"], "answer": 3, "explain": "Des millions d’enfants et de jeunes ne peuvent pas aller à l’école. L’Objectif 4 veut que chaque enfant ait une place.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Pourquoi certains enfants ne peuvent-ils pas aller à l’école ?", "options": ["Ils vivent loin ou leur famille est pauvre", "Ils sont trop grands", "L’école est toujours fermée", "Ils n’aiment pas apprendre"], "answer": 0, "explain": "Les longs trajets, les coûts et la pauvreté empêchent certains enfants d’aller à l’école. L’Objectif 4 veut supprimer ces obstacles.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Que doit avoir chaque enfant ?", "options": ["Une voiture", "Une place dans une bonne école près de chez lui", "Un téléphone", "Une maison dans le ciel"], "answer": 1, "explain": "Chaque enfant doit avoir une place dans une bonne école, près de chez lui.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Que signifie finir l’école ?", "options": ["Partir le premier jour", "Sécher tous les cours", "Passer toutes les classes et apprendre", "Ne jamais revenir"], "answer": 2, "explain": "Finir l’école veut dire aller au bout de toutes les classes. Beaucoup d’enfants partent avant la fin.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "Pourquoi est-il bon que les enfants finissent l’école ?", "options": ["Cela les fatigue", "Ce n’est pas important", "Cela arrête leur apprentissage", "Cela les aide à apprendre et à trouver du travail plus tard"], "answer": 3, "explain": "Finir l’école donne aux enfants plus de compétences et plus de chances dans la vie.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "La plupart des enfants finissent-ils l’école dans tous les pays ?", "options": ["Non, beaucoup partent tôt", "Oui, tous la finissent", "Personne ne va à l’école", "Seules les filles finissent"], "answer": 0, "explain": "Beaucoup d’enfants ne finissent pas l’école, alors l’Objectif 4 veut que plus d’enfants restent jusqu’au bout.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Que apprennent les enfants à l’école ?", "options": ["Seulement dormir", "Lire, écrire et compter", "Seulement jouer", "Rien d’utile"], "answer": 1, "explain": "À l’école, les enfants apprennent à lire, à écrire et à compter. Ces compétences leur servent toute la vie.", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "Suffit-il que les enfants fréquentent l’école ?", "options": ["Oui, y aller suffit", "Seuls les professeurs doivent apprendre", "Non, ils doivent vraiment apprendre", "Cela n’a pas d’importance"], "answer": 2, "explain": "Être à l’école ne suffit pas. Les enfants doivent vraiment apprendre des choses utiles.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Qu’est-ce qui aide les enfants à apprendre à lire ?", "options": ["Seulement de la musique forte", "Regarder la télévision toute la journée", "Rester à la maison", "Des livres et un bon professeur"], "answer": 3, "explain": "Les livres, un bon professeur et la pratique aident les enfants à apprendre à lire.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Que sont les compétences ?", "options": ["Des choses que l’on sait bien faire, comme dessiner ou compter", "Des endroits où l’on va jouer avec ses amis après l’école", "Des règles que le professeur écrit au tableau chaque matin", "Des magasins qui vendent des bonbons et des jouets près de chez soi"], "answer": 0, "explain": "Les compétences sont des choses que nous apprenons à bien faire. L’Objectif 4 veut que les jeunes apprennent des compétences pour le travail et la vie.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Pourquoi les jeunes ont-ils besoin de compétences ?", "options": ["Pour arrêter d’aller à l’école", "Pour trouver du travail et aider leur communauté", "Pour s’ennuyer", "Ils n’en ont pas besoin"], "answer": 1, "explain": "Les compétences aident les jeunes à trouver du travail et à aider leur famille et leur communauté.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Laquelle de ces compétences est utile ?", "options": ["Casser des choses", "Se cacher de ses amis", "Utiliser un ordinateur en toute sécurité", "Ignorer les règles"], "answer": 2, "explain": "Apprendre l’informatique et d’autres compétences utiles aide les jeunes dans le travail et dans la vie.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Les filles et les garçons doivent-ils avoir la même chance d’aller à l’école ?", "options": ["Non, seulement les garçons", "Non, seulement les filles", "Seulement dans certains pays", "Oui, les deux doivent l’avoir"], "answer": 3, "explain": "Les filles et les garçons doivent avoir la même chance d’apprendre. L’Objectif 4 veut mettre fin aux inégalités injustes entre eux.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Que signifie « juste » pour les écoles ?", "options": ["Tout le monde a la chance d’apprendre", "Seuls les enfants riches apprennent", "Certains enfants ne reçoivent rien", "Seuls certains enfants sont bienvenus"], "answer": 0, "explain": "Juste signifie que chaque enfant a la chance d’apprendre, quelle que soit sa famille, son foyer ou son origine.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Qui doit pouvoir aller à l’école ?", "options": ["Seulement les enfants qui ont de l’argent", "Chaque enfant, quelle que soit la situation de sa famille", "Seulement les enfants qui vivent en ville", "Aucun enfant"], "answer": 1, "explain": "L’Objectif 4 dit que l’éducation de qualité doit être pour tous, y compris les enfants pauvres ou qui vivent loin.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "Qu’est-ce qui aide le plus une école ?", "options": ["Une grande piscine", "De belles voitures sur le parking", "De bons professeurs formés", "Des salles de classe vides"], "answer": 2, "explain": "De bons professeurs aident les enfants à apprendre. L’Objectif 4 veut davantage de professeurs formés.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "De quoi les professeurs ont-ils besoin pour aider les enfants à apprendre ?", "options": ["Aucune aide", "Travailler sans salaire", "Éviter la classe", "De formation et de soutien"], "answer": 3, "explain": "Les professeurs ont besoin d’une bonne formation et de soutien pour aider chaque enfant à apprendre.", "src": "UN 2030 Agenda (2015)"}, {"ch": 7, "q": "L’école primaire et secondaire doit-elle être gratuite ?", "options": ["Oui, l’Objectif 4 veut une école gratuite", "Non, l’école doit coûter cher", "Seulement pour les garçons", "Seulement dans les villes"], "answer": 0, "explain": "L’Objectif 4 veut que l’école primaire et secondaire soit gratuite pour tous.", "src": "UN 2030 Agenda (2015)"}, {"ch": 7, "q": "Qui permet à chaque enfant d’aller à l’école ?", "options": ["Seulement les parents riches", "Les gouvernements et les communautés", "Personne", "Seulement les enfants"], "answer": 1, "explain": "Les gouvernements et les communautés aident à construire des écoles et à payer les professeurs, pour que chaque enfant puisse y aller.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "Quand les pays ont-ils approuvé les objectifs ?", "options": ["1900", "1950", "2015", "2050"], "answer": 2, "explain": "Les pays ont approuvé les objectifs en 2015. Ils ont fixé 2030 comme année pour les atteindre.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "Pour quelle année les objectifs doivent-ils être atteints ?", "options": ["2010", "1990", "2100", "2030"], "answer": 3, "explain": "Les pays ont fixé 2030 comme année pour atteindre les objectifs.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "Pourquoi les jeunes enfants doivent-ils aller à la maternelle ?", "options": ["Pour se préparer à l’école primaire", "Parce que c’est les vacances", "Pour arrêter d’apprendre", "Ce n’est pas utile"], "answer": 0, "explain": "L’apprentissage précoce aide les jeunes enfants à se préparer à l’école primaire et à grandir.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "Quand a lieu l’apprentissage précoce ?", "options": ["Seulement à 15 ans", "Avant l’école primaire", "Seulement à 30 ans", "Jamais"], "answer": 1, "explain": "L’éducation de la petite enfance concerne les années avant l’école primaire.", "src": "UN 2030 Agenda (2015)"}, {"ch": 10, "q": "Qu’est-ce que l’alphabétisation ?", "options": ["Savoir nager", "Savoir dessiner", "Savoir lire et écrire", "Savoir courir vite"], "answer": 2, "explain": "L’alphabétisation signifie lire et écrire. L’Objectif 4 veut que tous les jeunes sachent lire et écrire.", "src": "UN 2030 Agenda (2015)"}, {"ch": 10, "q": "Qu’est-ce que la numératie ?", "options": ["Savoir chanter", "Savoir cuisiner", "Savoir peindre", "Savoir compter et faire des calculs"], "answer": 3, "explain": "La numératie signifie utiliser les nombres, comme compter et additionner.", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "Les enfants handicapés doivent-ils aller à l’école avec les autres enfants ?", "options": ["Oui, les écoles doivent les accueillir", "Non, ils doivent rester à la maison", "Seulement le week-end", "Seulement dans des lieux spéciaux"], "answer": 0, "explain": "L’Objectif 4 veut des écoles qui accueillent et incluent chaque enfant, y compris les enfants handicapés.", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "Qu’est-ce qui rend une école inclusive ?", "options": ["Seuls certains enfants sont autorisés", "Tout le monde est bienvenu et peut apprendre", "Les enfants sont tenus à l’écart", "Personne ne peut entrer"], "answer": 1, "explain": "Une école inclusive accueille chaque enfant, pour que tous puissent apprendre ensemble.", "src": "UN 2030 Agenda (2015)"}], "2": [{"ch": 0, "q": "Quel numéro correspond à l’éducation de qualité ?", "options": ["4", "2", "9", "12"], "answer": 0, "explain": "L’éducation de qualité est l’Objectif 4 parmi les 17 objectifs mondiaux.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "L’Objectif 4 concerne quelle chose ?", "options": ["Seulement le sport", "Un bon apprentissage pour tous", "Seulement les vacances", "Seulement les grandes villes"], "answer": 1, "explain": "L’Objectif 4 veut que chaque enfant et chaque adulte reçoive une bonne éducation.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "En quelle année les pays ont-ils approuvé les objectifs mondiaux ?", "options": ["1945", "2001", "2015", "2040"], "answer": 2, "explain": "En 2015, les dirigeants du monde ont approuvé 17 objectifs mondiaux à atteindre d’ici 2030.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Pourquoi les enfants devraient-ils aller à l’école ?", "options": ["Pour dormir", "Pour arriver en retard", "Pour être seuls", "Pour apprendre et grandir"], "answer": 3, "explain": "L’école aide les enfants à apprendre à lire, à compter et à se faire des amis.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 1, "q": "Chaque enfant doit-il avoir le droit d’aller à l’école ?", "options": ["Oui", "Non", "Seulement les garçons", "Seulement dans les villes"], "answer": 0, "explain": "Chaque enfant a droit à l’éducation.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 1, "q": "Un enfant ne peut pas atteindre l’école parce qu’elle est trop loin. C’est un problème de :", "options": ["Couleur", "Accès", "Sommeil", "Musique"], "answer": 1, "explain": "L’accès, c’est pouvoir atteindre une école et y entrer.", "src": "UNESCO"}, {"ch": 1, "q": "Quel lieu aide les enfants à apprendre ensemble ?", "options": ["Une boutique de chaussures", "Un parking", "Une école", "Un rayon d’épicerie"], "answer": 2, "explain": "Une école est un lieu où les enfants apprennent ensemble avec leurs professeurs.", "src": "UNESCO"}, {"ch": 2, "q": "Pourquoi les parents veulent-ils que leurs enfants terminent l’école ?", "options": ["Cela fait que les enfants n’aiment pas lire chez eux", "Cela signifie que les frais de scolarité ne sont plus jamais payés", "Cela supprime tout besoin d’apprendre après l’école", "Finir l’école améliore l’avenir professionnel et la santé de l’enfant"], "answer": 3, "explain": "Terminer l’école est lié à de meilleurs emplois, à de meilleurs revenus et à une meilleure santé plus tard.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "Pourquoi certains enfants quittent-ils l’école tôt ?", "options": ["L’argent, la distance ou la maladie peuvent les en empêcher", "Ils n’aiment pas apprendre", "L’école est trop courte", "Ils ont trop de livres"], "answer": 0, "explain": "Beaucoup d’enfants partent tôt à cause de l’argent, des trajets ou de la maladie.", "src": "UNESCO"}, {"ch": 2, "q": "Pourquoi est-il bon de rester à l’école ?", "options": ["Tu t’ennuies", "Tu apprends davantage chaque année", "Tu perds tes amis", "Tu arrêtes d’apprendre"], "answer": 1, "explain": "Chaque année d’école t’aide à mieux apprendre et à développer tes compétences.", "src": "UNESCO"}, {"ch": 2, "q": "Laquelle de ces choses aide les élèves à finir l’école ?", "options": ["Manquer chaque cours", "Sauter des repas", "Le soutien de la famille et des professeurs", "Ne jamais poser de questions"], "answer": 2, "explain": "Le soutien de la famille et des professeurs aide les élèves à persévérer.", "src": "UNESCO"}, {"ch": 3, "q": "Qu’est-ce que lire ?", "options": ["Manger des mots", "Seulement dessiner des images", "Courir vite", "Comprendre les mots d’une page"], "answer": 3, "explain": "Lire signifie comprendre les mots et ce qu’ils disent.", "src": "UNESCO"}, {"ch": 3, "q": "Quelle compétence te permet de faire 2 + 3 ?", "options": ["Compter", "Nager", "Seulement chanter", "Cuisiner"], "answer": 0, "explain": "Compter nous aide à savoir combien il y a de choses au total.", "src": "UNESCO"}, {"ch": 3, "q": "Quelle activité aide les jeunes enfants à développer leurs premières compétences en lecture ?", "options": ["Regarder la télévision pendant de nombreuses heures chaque jour", "Lire des histoires à voix haute et parler des images", "Recopier en silence de longues listes de mots au hasard", "Lire seulement des problèmes de maths et jamais d’histoires"], "answer": 1, "explain": "La lecture partagée et la conversation développent le vocabulaire et les premières compétences en lecture.", "src": "UNESCO"}, {"ch": 3, "q": "Qu’est-ce qu’une bibliothèque ?", "options": ["Un lieu pour vendre des voitures", "Un lieu avec seulement des jouets", "Un lieu avec beaucoup de livres", "Un lieu pour nager"], "answer": 2, "explain": "Une bibliothèque est un endroit où l’on peut lire et emprunter des livres.", "src": "UNESCO"}, {"ch": 4, "q": "Qu’est-ce que le travail d’équipe ?", "options": ["Toujours travailler seul", "Gagner chaque partie tout seul", "Se cacher de ses amis", "Travailler ensemble avec d’autres"], "answer": 3, "explain": "Le travail d’équipe signifie travailler ensemble pour atteindre un but.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Quelle compétence t’aide à dire ce que tu ressens ?", "options": ["La communication", "Sauter à cloche-pied", "Dormir", "Peindre des murs"], "answer": 0, "explain": "La communication, c’est dire ce que l’on pense et écouter les autres.", "src": "UNESCO"}, {"ch": 4, "q": "Qu’est-ce qu’être créatif ?", "options": ["Copier exactement", "Imaginer de nouvelles idées ou de nouvelles choses", "Ne jamais essayer", "Utiliser seulement de l’argent"], "answer": 1, "explain": "Être créatif, c’est créer quelque chose de nouveau, comme un dessin ou une histoire.", "src": "UNESCO"}, {"ch": 4, "q": "Quelle compétence t’aide à résoudre un problème ?", "options": ["Fermer les yeux", "S’enfuir", "Bien réfléchir", "L’ignorer"], "answer": 2, "explain": "Bien réfléchir nous aide à trouver des solutions aux problèmes.", "src": "UNESCO"}, {"ch": 5, "q": "Les filles et les garçons doivent-ils tous aller à l’école ?", "options": ["Seulement les garçons", "Seulement les filles", "Aucun des deux", "Oui, les deux doivent y aller"], "answer": 3, "explain": "Les filles et les garçons doivent avoir les mêmes chances d’aller à l’école.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Que signifie « égal » en éducation ?", "options": ["Chacun a une chance équitable", "Tout le monde porte les mêmes chaussures", "Certains enfants n’ont pas de professeurs", "Seuls les enfants riches apprennent"], "answer": 0, "explain": "L’éducation égale signifie que chacun a une chance équitable d’apprendre.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Quelle est une manière équitable de partager les livres à l’école ?", "options": ["Seul l’enfant le plus rapide en a un", "Chacun a son tour", "Seul le professeur les garde", "Seul l’enfant le plus grand"], "answer": 1, "explain": "Partager équitablement signifie que chaque enfant a la chance d’utiliser les livres.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Quels enfants ont le droit d’aller à l’école ?", "options": ["Seulement les enfants dont les parents paient les frais les plus élevés", "Seulement les garçons qui vivent dans la capitale", "Chaque enfant, quelle que soit sa famille ou son origine", "Seulement les enfants qui lisent déjà très bien"], "answer": 2, "explain": "Chaque enfant a droit à l’éducation, quelle que soit son origine.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 6, "q": "Que fait un professeur ?", "options": ["Il vend seulement de la nourriture", "Il conduit seulement des bus", "Il nettoie le ciel", "Il aide les enfants à apprendre"], "answer": 3, "explain": "Les professeurs aident les enfants à apprendre des choses nouvelles et à grandir.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Pourquoi les écoles ont-elles besoin de bons professeurs ?", "options": ["Les professeurs aident les enfants à bien apprendre", "Les professeurs arrêtent tout apprentissage", "Les professeurs donnent seulement des devoirs", "Les professeurs ne sont pas nécessaires"], "answer": 0, "explain": "De bons professeurs aident les enfants à apprendre et à se sentir en sécurité à l’école.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce qui aide les professeurs à mieux enseigner ?", "options": ["Un salaire plus bas pour tous", "La formation et le soutien", "Fermer toutes les écoles", "Ignorer les enfants"], "answer": 1, "explain": "La formation aide les professeurs à découvrir de nouvelles façons d’enseigner.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Que peut montrer un bon professeur aux enfants ?", "options": ["Comment être cruel", "Comment être paresseux", "Comment être gentil et curieux", "Comment se cacher"], "answer": 2, "explain": "De bons professeurs aident les enfants à être gentils, curieux et courageux.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "De quoi les écoles ont-elles besoin pour bien fonctionner ?", "options": ["Seulement des ordinateurs", "Seulement de la musique forte", "Seulement une piscine", "Des livres, des bureaux et des professeurs"], "answer": 3, "explain": "Les écoles ont besoin de nombreuses choses, notamment des livres, des bureaux et des professeurs.", "src": "UNESCO"}, {"ch": 7, "q": "Qu’est-ce qui aide à garder les enfants en sécurité et en bonne santé à l’école ?", "options": ["De l’eau propre et des toilettes", "De grosses voitures", "Pas de toit", "Seulement des haut-parleurs bruyants"], "answer": 0, "explain": "De l’eau propre et des toilettes aident les enfants à rester en bonne santé à l’école.", "src": "UN 2030 Agenda (2015)"}, {"ch": 7, "q": "Pourquoi certaines écoles n’ont-elles pas de livres ?", "options": ["Les livres ne sont pas nécessaires", "Elles n’ont pas assez d’argent", "Les enfants ne lisent pas", "Les livres sont trop lourds"], "answer": 1, "explain": "Il faut de l’argent pour acheter des livres et d’autres fournitures scolaires.", "src": "UNESCO"}, {"ch": 7, "q": "Pourquoi les écoles ont-elles besoin d’argent ?", "options": ["Seulement pour acheter des voitures", "Seulement pour payer des vacances", "Pour acheter des choses pour apprendre", "Les écoles n’ont pas besoin d’argent"], "answer": 2, "explain": "L’argent paie les livres, les professeurs, les bureaux et d’autres fournitures scolaires.", "src": "UNESCO"}, {"ch": 8, "q": "Quel document dit que chacun a le droit à l’éducation ?", "options": ["Un livre de cuisine avec des recettes pour les repas de famille", "Une carte des cratères et des mers de la Lune", "L’emploi du temps scolaire de tout le trimestre", "La Déclaration universelle des droits de l’homme"], "answer": 3, "explain": "La Déclaration universelle des droits de l’homme affirme que chacun a droit à l’éducation.", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "En quelle année la Déclaration universelle des droits de l’homme a-t-elle été adoptée ?", "options": ["1948", "1900", "1975", "2030"], "answer": 0, "explain": "Elle a été adoptée en 1948 par l’Assemblée générale des Nations unies.", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "Quelle organisation a été créée pour aider les pays à travailler ensemble pour la paix et l’éducation ?", "options": ["Le cirque", "Les Nations unies", "Le club de sport", "La compagnie automobile"], "answer": 1, "explain": "Les Nations unies ont été créées après la Seconde Guerre mondiale pour aider les pays à travailler ensemble.", "src": "United Nations"}, {"ch": 9, "q": "Quelle est une bonne façon pour les jeunes enfants d’apprendre ?", "options": ["En restant assis toute la journée", "En restant silencieux", "En jouant et en parlant", "En travaillant la nuit"], "answer": 2, "explain": "Les jeunes enfants apprennent beaucoup en jouant et en parlant avec les adultes.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Qu’est-ce qui aide les bébés à apprendre ?", "options": ["Les garder dans le noir", "Ne jamais les porter", "Leur donner seulement des bonbons", "Leur parler et leur chanter des chansons"], "answer": 3, "explain": "Parler, chanter et jouer avec les bébés les aide à apprendre le langage.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Qu’est-ce qui aide un enfant à bien grandir avant l’école ?", "options": ["L’amour et les soins des adultes", "Être laissé seul", "Trop de bonbons", "Ne pas dormir"], "answer": 0, "explain": "L’amour, les soins et le jeu pendant la petite enfance aident les enfants à grandir forts et prêts à apprendre.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "Que signifie l’alphabétisation ?", "options": ["Savoir danser", "Savoir lire et écrire", "Savoir nager", "Savoir seulement dessiner"], "answer": 1, "explain": "L’alphabétisation signifie savoir lire et écrire.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "Quelle lettre vient après A dans l’alphabet ?", "options": ["Z", "D", "B", "Q"], "answer": 2, "explain": "B vient après A dans l’alphabet.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "Laquelle de ces choses aide les gens à mieux lire ?", "options": ["Ne jamais ouvrir un livre", "Seulement regarder des vidéos", "Oublier les lettres", "Lire un peu chaque jour"], "answer": 3, "explain": "Lire un peu chaque jour aide les gens à mieux lire.", "src": "UNESCO, International Literacy Day"}, {"ch": 11, "q": "Que signifie l’inclusion à l’école ?", "options": ["Chacun est accueilli et peut apprendre", "Seuls certains enfants peuvent entrer", "Tous les enfants doivent être identiques", "Les enfants doivent rester à la maison"], "answer": 0, "explain": "L’inclusion signifie que chaque enfant peut apprendre à l’école, y compris les enfants handicapés.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Les enfants handicapés doivent-ils pouvoir aller à l’école ?", "options": ["Non", "Oui", "Seulement le dimanche", "Seulement s’ils n’ont pas d’amis"], "answer": 1, "explain": "Les enfants handicapés ont le droit d’aller à l’école avec les autres.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Qu’est-ce qui aide un enfant en fauteuil roulant à apprendre à l’école ?", "options": ["Une école sans portes", "Une école avec seulement des escaliers", "Une école avec des rampes", "Une école très éloignée"], "answer": 2, "explain": "Les rampes et les salles sans marches aident les enfants en fauteuil roulant à se déplacer dans l’école.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Quelle est une façon gentille de traiter un camarade différent ?", "options": ["Le laisser de côté", "Lui donner des surnoms", "L’ignorer", "L’inclure dans les jeux"], "answer": 3, "explain": "Inclure ses camarades aide chacun à se sentir bienvenu.", "src": "UN CRPD (2006), Article 24"}, {"ch": 0, "q": "Pour quelle année les objectifs mondiaux doivent-ils être atteints ?", "options": ["2030", "1990", "2000", "2060"], "answer": 0, "explain": "Les objectifs mondiaux doivent être atteints d’ici 2030.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Qu’est-ce qui aide les enfants à aller à l’école en toute sécurité ?", "options": ["Des routes fermées", "Des routes et des chemins sûrs", "Traverser seul les routes très fréquentées", "Rester à la maison"], "answer": 1, "explain": "Des routes et des chemins sûrs aident les enfants à rejoindre l’école en toute sécurité.", "src": "UNESCO"}, {"ch": 2, "q": "Quelle est une bonne raison de continuer quand l’école est difficile ?", "options": ["Personne ne le remarquera", "L’école n’aide jamais", "Tu peux apprendre et atteindre tes objectifs", "Apprendre ne sert à rien"], "answer": 2, "explain": "Continuer t’aide à atteindre tes objectifs et à apprendre de nouvelles choses.", "src": "UNESCO"}, {"ch": 8, "q": "Que signifie l’abréviation ONU ?", "options": ["Infirmières unies", "Notes uniques", "Nom sous", "Organisation des Nations unies"], "answer": 3, "explain": "ONU signifie Organisation des Nations unies.", "src": "United Nations"}, {"ch": 9, "q": "Pourquoi le jeu est-il bon pour les jeunes enfants ?", "options": ["Il les aide à apprendre et à grandir", "Il fait perdre du temps", "Il les fatigue seulement", "Ce n’est pas permis"], "answer": 0, "explain": "Le jeu développe la réflexion, le langage et les compétences sociales.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "Quelle est la première lettre de l’alphabet ?", "options": ["Z", "A", "M", "K"], "answer": 1, "explain": "A est la première lettre de l’alphabet français.", "src": "UNESCO, International Literacy Day"}], "3": [{"ch": 0, "q": "Que signifie ODD ?", "options": ["Objectifs de développement durable", "Super jeux pour chiens", "Guide de bureau simple", "Groupe de dîner doux"], "answer": 0, "explain": "ODD signifie Objectifs de développement durable.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Combien y a-t-il d’objectifs mondiaux ?", "options": ["7", "17", "12", "27"], "answer": 1, "explain": "Il y a 17 objectifs mondiaux, et l’objectif 4 concerne l’éducation.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Quel mot décrit le mieux l’objectif 4 ?", "options": ["Vitesse", "Silence", "Qualité", "Prix"], "answer": 2, "explain": "L’objectif 4 s’appelle Éducation de qualité.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Quel numéro d’objectif correspond à l’eau propre et à l’assainissement ?", "options": ["2", "9", "15", "6"], "answer": 3, "explain": "L’objectif 6 est Eau propre et assainissement.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Qu’est-ce qu’une cible dans les objectifs mondiaux ?", "options": ["Un but précis à atteindre", "Un type de papier", "Un type de sport", "Un type d’aliment"], "answer": 0, "explain": "Chaque objectif a des cibles qui précisent exactement ce qu’il faut atteindre.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Quel obstacle peut empêcher une fille d’aller à l’école ?", "options": ["Trop de livres", "Une longue marche sur une route dangereuse", "Trop de soleil", "Trop de professeurs"], "answer": 1, "explain": "La distance et les routes dangereuses peuvent empêcher les enfants d’atteindre l’école.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 1, "q": "Que signifie qu’une école est gratuite ?", "options": ["Les enfants doivent payer pour s’inscrire", "Les enfants doivent apporter de l’argent à chaque cours", "Les enfants ne paient pas de frais pour s’inscrire", "Les enfants ne peuvent venir que le week-end"], "answer": 2, "explain": "Une école gratuite signifie que les enfants n’ont pas à payer de frais pour y aller.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Quel droit dit que chaque enfant doit pouvoir aller à l’école ?", "options": ["Le droit à une voiture", "Le droit aux vacances", "Le droit à une équipe de sport", "Le droit à l’éducation"], "answer": 3, "explain": "Le droit à l’éducation signifie que chaque enfant peut aller à l’école.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 1, "q": "Qu’est-ce qu’une zone isolée ?", "options": ["Un lieu éloigné des villes et des villages", "Un lieu sans ciel", "Un lieu sous la mer", "Un lieu sans aucun habitant"], "answer": 0, "explain": "Les zones isolées sont loin des villes, donc il peut être difficile pour les enfants d’atteindre l’école.", "src": "UNESCO"}, {"ch": 2, "q": "Qu’est-ce qu’un décrocheur ?", "options": ["Un élève qui finit en avance", "Un élève qui quitte l’école avant la fin", "Un professeur qui s’en va", "Un élève qui lit vite"], "answer": 1, "explain": "Un décrocheur quitte l’école avant de l’avoir terminée.", "src": "UNESCO"}, {"ch": 2, "q": "Pourquoi est-il important que les enfants terminent l’école primaire ?", "options": ["Cela signifie qu’on n’apprend plus jamais", "C’est seulement pour s’amuser", "Cela leur donne des bases en lecture, en écriture et en maths", "Cela supprime le besoin de devoirs"], "answer": 2, "explain": "Terminer l’école primaire développe des compétences de base pour la vie.", "src": "UNESCO"}, {"ch": 2, "q": "Qu’est-ce qui peut aider les élèves à rester à l’école ?", "options": ["Manquer les cours", "Partir tôt", "Ignorer les professeurs", "Le tutorat et le soutien"], "answer": 3, "explain": "Le tutorat et le soutien aident les élèves à rester à l’école et à continuer d’apprendre.", "src": "UNESCO"}, {"ch": 2, "q": "Qu’est-ce que l’assiduité ?", "options": ["Être présent à l’école", "Gagner un prix", "Écrire une lettre", "Acheter des livres"], "answer": 0, "explain": "L’assiduité signifie être à l’école pour les cours.", "src": "UNESCO"}, {"ch": 2, "q": "Que doit faire une école quand un enfant est absent pendant de nombreux jours ?", "options": ["L’oublier", "Chercher la raison et l’aider à revenir", "Le retirer de la liste sans raison", "Lui demander de payer une amende"], "answer": 1, "explain": "Les écoles peuvent soutenir les familles pour aider les enfants à revenir.", "src": "UNESCO"}, {"ch": 3, "q": "De quoi traite principalement la numératie ?", "options": ["Peindre des tableaux aux couleurs vives avec des pinceaux", "Chanter des chansons sur les animaux et les saisons", "Utiliser les nombres et les maths de base dans la vie de tous les jours", "Mémoriser les noms des pays du monde"], "answer": 2, "explain": "La numératie signifie utiliser les nombres avec assurance dans la vie quotidienne.", "src": "UNESCO"}, {"ch": 3, "q": "Quelle est une bonne façon de vérifier ce que l’on a appris ?", "options": ["Ne jamais réessayer", "Copier sans réfléchir", "Dormir pendant les cours", "Poser des questions et s’entraîner"], "answer": 3, "explain": "S’entraîner et poser des questions aide à comprendre les choses nouvelles.", "src": "UNESCO"}, {"ch": 3, "q": "Qu’est-ce qu’un résultat d’apprentissage ?", "options": ["Ce qu’un apprenant sait faire après avoir appris", "Le prix de l’école", "La météo le jour de l’examen", "Le nombre de bureaux"], "answer": 0, "explain": "Un résultat d’apprentissage est la compétence ou la connaissance acquise par l’apprenant.", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "À quoi sert un test ?", "options": ["À décider du temps qu’il fera", "À vérifier ce qu’une personne a appris", "À faire lever le soleil", "À choisir le menu de la cantine"], "answer": 1, "explain": "Les tests aident les professeurs et les apprenants à voir ce qui a été appris.", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "Qu’est-ce que la compréhension de lecture ?", "options": ["Lire très vite", "Lire à voix très haute", "Comprendre ce que l’on lit", "Ne lire que les images"], "answer": 2, "explain": "La compréhension de lecture signifie comprendre le sens d’un texte.", "src": "UNESCO"}, {"ch": 4, "q": "Quelle compétence aide à bien travailler avec des personnes venant d’ailleurs ?", "options": ["Ignorer les autres", "Crier sur les autres", "Se cacher des autres", "Le respect des autres"], "answer": 3, "explain": "Le respect aide les personnes d’origines différentes à travailler et à apprendre ensemble.", "src": "UNESCO"}, {"ch": 4, "q": "Qu’est-ce que la pensée critique ?", "options": ["Vérifier si une idée est logique", "Croire toutes les idées en même temps", "Ne jamais poser de questions", "Oublier ce que l’on lit"], "answer": 0, "explain": "La pensée critique consiste à poser des questions et à vérifier les faits.", "src": "UNESCO"}, {"ch": 4, "q": "Quelle compétence peut t’aider à trouver un emploi un jour ?", "options": ["Dormir longtemps pendant la journée scolaire", "Des compétences pratiques comme l’informatique ou la réparation", "Éviter tous les cours et l’entraînement à la maison", "Refuser d’apprendre quoi que ce soit de nouveau"], "answer": 1, "explain": "Les compétences pratiques et professionnelles aident les gens à travailler et à subvenir à leurs besoins.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Quelle compétence aide une équipe à prendre une décision ?", "options": ["Crier le plus fort", "Ignorer l’équipe", "Écouter chaque personne", "Quitter la salle"], "answer": 2, "explain": "Écouter tout le monde aide une équipe à bien choisir.", "src": "UNESCO"}, {"ch": 4, "q": "Qu’est-ce qu’une compétence numérique ?", "options": ["Utiliser seulement des crayons", "Casser des ordinateurs", "Ne jamais utiliser Internet", "Utiliser les ordinateurs et Internet en toute sécurité"], "answer": 3, "explain": "Les compétences numériques aident à utiliser la technologie en sécurité et efficacement.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Que signifie l’équité en éducation ?", "options": ["Un soutien juste pour que chaque enfant puisse apprendre", "Chaque enfant reçoit exactement la même chose", "Seuls les meilleurs élèves reçoivent de l’aide", "Les écoles n’ont pas besoin d’aider"], "answer": 0, "explain": "L’équité signifie donner à chaque enfant le soutien dont il a besoin pour apprendre.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Quel groupe d’enfants est souvent laissé de côté par l’école ?", "options": ["Les enfants qui aiment jouer au football à la récré", "Les enfants de familles pauvres ou de zones isolées", "Les enfants qui aiment chanter dans la chorale de l’école", "Les enfants qui s’assoient toujours au premier rang"], "answer": 1, "explain": "Les enfants de familles pauvres et de zones isolées sont plus susceptibles de ne pas aller à l’école.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "Qu’est-ce que l’écart de genre à l’école ?", "options": ["Un trou dans la cour de récréation", "Une courte pause entre deux cours chaque jour", "Une différence entre les filles et les garçons à l’école", "Un trou dans un mur de l’école à réparer"], "answer": 2, "explain": "L’écart de genre est une différence entre filles et garçons dans la scolarisation ou l’apprentissage.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Pourquoi les écoles devraient-elles accueillir les enfants de toutes les langues et de tous les milieux ?", "options": ["Une seule langue devrait être parlée", "Un seul milieu devrait être admis", "Les enfants devraient être renvoyés", "Chacun mérite une chance équitable d’apprendre"], "answer": 3, "explain": "L’éducation doit inclure tous les enfants équitablement, quel que soit leur milieu.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Quel groupe d’apprenants peut avoir besoin d’une aide supplémentaire pour être en sécurité à l’école ?", "options": ["Les enfants vulnérables", "Les enfants toujours heureux", "Les enfants qui savent voler", "Les enfants qui ne manquent jamais un cours"], "answer": 0, "explain": "Les enfants vulnérables risquent davantage d’être laissés de côté ou blessés, ils ont donc besoin d’aide supplémentaire.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "Qu’est-ce qu’une pénurie d’enseignants ?", "options": ["Trop de professeurs pour les enfants", "Pas assez de professeurs formés pour les enfants", "Des professeurs qui ne travaillent jamais", "Des professeurs qui ont trop de vacances"], "answer": 1, "explain": "Une pénurie signifie qu’il n’y a pas assez de professeurs formés.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce qui aide un nouveau professeur à bien réussir ?", "options": ["Aucun soutien du tout", "Être envoyé dans un autre pays", "L’accompagnement et la formation", "De longues pauses non payées"], "answer": 2, "explain": "L’accompagnement et la formation aident les nouveaux professeurs à progresser.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Pourquoi les conditions de travail des enseignants comptent-elles ?", "options": ["Elles n’ont aucun effet", "Elles ne comptent que pour les voitures des professeurs", "Elles ne comptent que dans les villes", "Elles influencent la qualité de l’apprentissage des enfants"], "answer": 3, "explain": "De bonnes conditions aident les professeurs à rester et à bien enseigner.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "De quoi les enseignants ont-ils besoin pour préparer un cours ?", "options": ["Des objectifs clairs et un bon plan", "Aucune idée de la matière", "Une chaise cassée", "Des vacances"], "answer": 0, "explain": "Des objectifs clairs et un plan aident les professeurs à bien enseigner.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "De quoi les enseignants ont-ils besoin pour continuer d’apprendre ?", "options": ["Ne plus jamais apprendre", "Une formation continue", "Seulement des vacances", "Seulement de l’argent"], "answer": 1, "explain": "Les professeurs continuent d’apprendre grâce à une formation continue.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "Qu’est-ce qu’un droit de scolarité ?", "options": ["Un prix pour de bonnes notes", "Un cadeau du professeur", "L’argent payé pour aller à l’école", "Une amende pour retard"], "answer": 2, "explain": "Un droit de scolarité est une somme que les familles paient parfois pour que leur enfant aille à l’école.", "src": "UNESCO"}, {"ch": 7, "q": "Pourquoi les gouvernements dépensent-ils de l’argent pour les écoles ?", "options": ["Seulement pour acheter plus de vacances", "Seulement pour construire des routes", "Pour réduire le nombre de jours d’école", "Pour aider les enfants à apprendre et à grandir"], "answer": 3, "explain": "L’argent public paie les professeurs, les bâtiments et les livres pour que les enfants apprennent.", "src": "UNESCO"}, {"ch": 7, "q": "De quoi une salle de classe a-t-elle besoin pour être un lieu sûr où apprendre ?", "options": ["Un bon éclairage, de l’air frais et un toit solide", "Aucune fenêtre, pour que la pièce reste sombre", "Un bruit fort venant de la rue pendant tout le cours", "Des chaises cassées et un toit qui fuit chaque semaine"], "answer": 0, "explain": "De bons bâtiments aident les enfants à apprendre dans le confort et la sécurité.", "src": "UN 2030 Agenda (2015)"}, {"ch": 7, "q": "Que peut-il se passer si une école n’a pas d’argent pour les livres ?", "options": ["Les enfants apprennent plus vite", "Les enfants ont moins de chances d’apprendre", "Les enfants n’ont plus besoin de l’école", "Les enfants ont des vacances supplémentaires"], "answer": 1, "explain": "Sans livres, les enfants peuvent avoir plus de mal à apprendre.", "src": "UNESCO"}, {"ch": 8, "q": "En quelle année la Convention des Nations unies relative aux droits de l’enfant a-t-elle été adoptée ?", "options": ["1948", "1990", "1989", "2015"], "answer": 2, "explain": "Elle a été adoptée en 1989 par l’Assemblée générale des Nations unies.", "src": "UN Convention on the Rights of the Child, 1989"}, {"ch": 8, "q": "Que furent les Objectifs du Millénaire pour le développement ?", "options": ["Un ensemble d’objectifs de 1900", "Un ensemble d’objectifs pour la Lune", "Un ensemble d’objectifs pour le sport", "Un ensemble d’objectifs de 2000 à 2015"], "answer": 3, "explain": "Les OMD ont couvert la période de 2000 à 2015, avant les objectifs mondiaux.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 8, "q": "Quelle réunion de 1990 a porté sur l’Éducation pour tous ?", "options": ["La Conférence mondiale sur l’éducation pour tous à Jomtien", "Une foire commerciale internationale tenue à New York cette année-là", "Un festival mondial du film tenu à Cannes cet été-là", "Un sommet mondial sur les règles du football au Brésil"], "answer": 0, "explain": "Des pays se sont réunis à Jomtien, en Thaïlande, en 1990 pour s’engager en faveur de l’éducation pour tous.", "src": "UNESCO"}, {"ch": 8, "q": "Quel jour fête-t-on chaque année les enseignants ?", "options": ["Le 1er janvier", "Journée mondiale des enseignants, le 5 octobre", "Le 25 décembre", "Le 8 septembre"], "answer": 1, "explain": "L’UNESCO célèbre la Journée mondiale des enseignants chaque année le 5 octobre.", "src": "UNESCO"}, {"ch": 9, "q": "Qu’est-ce que la petite enfance ?", "options": ["Seulement les années d’adolescence", "Seulement les années universitaires", "Les années de la naissance à environ huit ans", "Seulement la dernière année d’école"], "answer": 2, "explain": "La petite enfance désigne généralement les années de la naissance à environ huit ans.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Pourquoi l’apprentissage précoce est-il important ?", "options": ["Les premières années n’ont pas d’importance", "Seules les années suivantes comptent", "L’apprentissage précoce n’aide que le sport", "Les expériences précoces façonnent la croissance du cerveau"], "answer": 3, "explain": "Les expériences précoces façonnent la croissance et l’apprentissage du cerveau.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Quelle est une bonne activité d’apprentissage précoce ?", "options": ["Lire des albums ensemble", "Regarder la télévision toute la journée", "Laisser un enfant seul pendant des heures", "Ne manger que des bonbons"], "answer": 0, "explain": "Lire ensemble développe le langage et l’apprentissage précoce.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Qu’est-ce que l’apprentissage par le jeu ?", "options": ["Apprendre en restant assis", "Apprendre en jouant", "Apprendre uniquement en copiant", "Apprendre sans jamais poser de questions"], "answer": 1, "explain": "L’apprentissage par le jeu aide les jeunes enfants à apprendre en faisant.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "Quand a lieu la Journée internationale de l’alphabétisation ?", "options": ["Le 1er janvier", "Le 25 décembre", "Le 8 septembre", "Le 30 avril"], "answer": 2, "explain": "L’UNESCO célèbre la Journée internationale de l’alphabétisation chaque année le 8 septembre.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "Qu’est-ce qui aide les adultes à apprendre à lire ?", "options": ["Être obligé d’arrêter de lire", "Dormir davantage", "Éviter les livres", "Les cours d’alphabétisation pour adultes"], "answer": 3, "explain": "Les cours d’alphabétisation pour adultes aident à apprendre à lire et à écrire.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Pourquoi certaines personnes ont-elles du mal à lire ?", "options": ["Elles n’ont pas eu la chance d’apprendre", "Lire est interdit", "Les livres sont toxiques", "Les lettres sont trop grosses"], "answer": 0, "explain": "Beaucoup de personnes ne peuvent pas apprendre à lire faute d’avoir eu la chance d’aller à l’école.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "Quand a lieu la Journée internationale de la langue maternelle ?", "options": ["Le 1er mai", "Le 21 février", "Le 31 octobre", "Le 14 juillet"], "answer": 1, "explain": "L’UNESCO célèbre la Journée internationale de la langue maternelle le 21 février.", "src": "UNESCO, International Mother Language Day"}, {"ch": 11, "q": "Que doit faire une école pour les enfants handicapés ?", "options": ["Les tenir à l’écart des autres", "Refuser de les accueillir", "Les intégrer et leur apporter du soutien", "Les renvoyer chez eux"], "answer": 2, "explain": "Les écoles inclusives accueillent les enfants handicapés et leur apportent du soutien.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Qu’est-ce qu’un aménagement raisonnable à l’école ?", "options": ["Un moyen d’éviter d’enseigner", "Un bus spécial vers la ville", "Un type de frais d’examen", "Un ajustement qui aide un enfant à participer"], "answer": 3, "explain": "Un aménagement raisonnable est un ajustement qui aide un enfant à participer à la vie scolaire.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Lequel de ces éléments est un exemple d’inclusion ?", "options": ["Des livres en braille à la bibliothèque", "Une école sans entrée", "Des professeurs qui ignorent tous les élèves", "Une salle que seuls certains enfants peuvent franchir"], "answer": 0, "explain": "Les livres en braille aident les enfants aveugles à lire en classe.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Que signifie inclusif ?", "options": ["Qui tient certaines personnes à l’écart", "Qui accueille tout le monde", "Qui n’accueille qu’un seul groupe", "Qui fait partir les gens"], "answer": 1, "explain": "Inclusif signifie accueillir tout le monde et faire de la place pour chacun.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Qu’est-ce qu’une place scolaire ?", "options": ["Un siège dans une voiture", "Un endroit pour dormir", "Un siège pour un enfant à l’école", "Une boutique de livres"], "answer": 2, "explain": "Une place scolaire est un siège permettant à un enfant d’apprendre.", "src": "UNESCO"}], "4": [{"ch": 0, "q": "Que vise l’objectif 4 ?", "options": ["Une qualité et un apprentissage tout au long de la vie pour tous", "Seulement le sport pour les enfants", "Seulement des emplois pour les adultes", "Moins d’école pour tout le monde"], "answer": 0, "explain": "L’objectif 4 vise un apprentissage inclusif, de qualité et tout au long de la vie pour tous.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Combien de cibles l’objectif 4 comporte-t-il ?", "options": ["5", "10", "17", "169"], "answer": 1, "explain": "L’objectif 4 compte 10 cibles : sept cibles de résultats et trois de moyens de mise en œuvre.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Combien de cibles figurent dans l’ensemble des 17 objectifs mondiaux ?", "options": ["17", "50", "169", "300"], "answer": 2, "explain": "Les 17 objectifs mondiaux comptent 169 cibles au total.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Quel objectif porte sur l’élimination de la pauvreté ?", "options": ["L’objectif 4", "L’objectif 9", "L’objectif 12", "L’objectif 1"], "answer": 3, "explain": "L’objectif 1 est « Pas de pauvreté ».", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Pourquoi un enfant d’un village peut-il ne pas aller à l’école ?", "options": ["L’école est trop loin", "L’école est trop proche", "Il y a trop de bus", "Il y a trop d’amis"], "answer": 0, "explain": "Les longues distances sont un obstacle courant à l’école.", "src": "UNESCO"}, {"ch": 1, "q": "Pourquoi certaines familles gardent-elles leurs enfants à la maison ?", "options": ["Elles ne veulent pas d’éducation", "Elles ont besoin d’aide pour le travail ou pour gagner de l’argent", "L’école est illégale", "Elles ont trop de voitures"], "answer": 1, "explain": "Certaines familles ont besoin que les enfants les aident à gagner de l’argent ou à travailler à la maison.", "src": "UNESCO"}, {"ch": 1, "q": "Laquelle de ces solutions aide les enfants des zones rurales à rejoindre l’école ?", "options": ["Fermer les routes", "Traverser seul les rivières sans aide", "Des bus scolaires ou des chemins sûrs", "Rester à la maison"], "answer": 2, "explain": "Les transports et les chemins sûrs facilitent la scolarisation des enfants ruraux.", "src": "UNESCO"}, {"ch": 1, "q": "Qu’est-ce que l’enseignement préprimaire ?", "options": ["L’apprentissage après l’université", "L’apprentissage uniquement le week-end", "L’apprentissage uniquement sur le lieu de travail", "L’apprentissage avant l’école primaire"], "answer": 3, "explain": "L’enseignement préprimaire est l’apprentissage des jeunes enfants avant l’école primaire.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Pourquoi un bâtiment scolaire sûr est-il important ?", "options": ["Il protège les enfants du danger", "Il rallonge la durée de l’école", "Il empêche les enfants d’apprendre", "Il ne sert que de décor"], "answer": 0, "explain": "Des bâtiments sûrs protègent les enfants et rendent l’apprentissage possible.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Qu’est-ce que l’école primaire ?", "options": ["La dernière étape de l’université", "La première grande étape de la scolarité", "Seulement pour les professeurs", "Une sorte de colonie de vacances"], "answer": 1, "explain": "L’école primaire est généralement la première grande étape de l’enseignement formel.", "src": "UNESCO"}, {"ch": 2, "q": "Qu’est-ce que l’enseignement secondaire ?", "options": ["L’étape qui précède la maternelle", "Une sorte de camp sportif", "L’étape qui suit l’école primaire", "Un lieu réservé aux adultes"], "answer": 2, "explain": "L’enseignement secondaire fait suite à l’école primaire.", "src": "UNESCO"}, {"ch": 2, "q": "Quel facteur augmente souvent le décrochage scolaire précoce ?", "options": ["Le beau temps", "Trop de livres", "Gagner des prix", "La pauvreté"], "answer": 3, "explain": "La pauvreté est l’une des principales raisons pour lesquelles les enfants quittent l’école tôt.", "src": "UNESCO"}, {"ch": 2, "q": "Que signifie le taux d’achèvement ?", "options": ["La part des enfants qui terminent un niveau scolaire", "La part des professeurs qui dorment", "Le nombre de sonneries de l’école", "Le prix des cartables"], "answer": 0, "explain": "Le taux d’achèvement est la part des enfants qui achèvent un niveau d’études.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Qu’est-ce qui aide les enfants à terminer l’école ?", "options": ["Fermer les écoles plus tôt", "Aider les familles à payer les frais et le transport", "Retirer les livres", "Allonger les examens chaque jour"], "answer": 1, "explain": "Un soutien pour les frais et le transport aide les enfants à rester à l’école.", "src": "UNESCO"}, {"ch": 2, "q": "Que peut faire une école pour que les élèves continuent de venir ?", "options": ["Ignorer les élèves absents et attendre leur retour", "Donner moins de cours aux élèves qui manquent l’école", "Suivre l’assiduité et contacter les familles", "Fermer l’école plus tôt chaque vendredi"], "answer": 2, "explain": "Les écoles peuvent suivre l’assiduité et travailler avec les familles pour soutenir les élèves.", "src": "UNESCO"}, {"ch": 3, "q": "Que signifie un bon niveau de lecture ?", "options": ["Lire seulement des chiffres", "Ne jamais lire à voix haute", "Lire plus vite qu’une voiture", "Lire et comprendre un texte adapté à son âge"], "answer": 3, "explain": "Un bon niveau de lecture signifie comprendre un texte simple adapté à son âge.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Quelle matière porte sur les nombres, les régularités et les formes ?", "options": ["Les mathématiques", "La musique", "L’art dramatique", "L’histoire de l’art"], "answer": 0, "explain": "Les mathématiques sont la matière qui porte sur les nombres, les régularités et les formes.", "src": "UNESCO"}, {"ch": 3, "q": "Qu’est-ce qu’un programme scolaire ?", "options": ["Un type d’uniforme scolaire", "L’ensemble des matières et de ce que les élèves apprennent", "Un parking d’école", "Une liste de vacances"], "answer": 1, "explain": "Le programme scolaire indique ce que les élèves doivent apprendre dans chaque matière.", "src": "UNESCO"}, {"ch": 3, "q": "Pourquoi apprendre dans sa langue maternelle est-il utile ?", "options": ["Ce n’est jamais utile", "Cela signifie apprendre moins", "Les enfants comprennent mieux les cours", "Cela raccourcit l’école"], "answer": 2, "explain": "Les enfants apprennent plus facilement quand ils comprennent la langue utilisée en classe.", "src": "UNESCO, International Mother Language Day"}, {"ch": 3, "q": "Qu’est-ce qu’une compétence en éducation ?", "options": ["Quelque chose que l’on perd", "Un type d’aliment", "Seulement une matière scolaire", "Quelque chose qu’une personne sait bien faire"], "answer": 3, "explain": "Une compétence est une capacité que l’on peut pratiquer et améliorer.", "src": "UNESCO"}, {"ch": 4, "q": "Que signifie résoudre un problème ?", "options": ["Trouver un moyen de répondre à une question difficile", "Ignorer les problèmes", "Rendre les problèmes plus grands", "Attendre indéfiniment les autres"], "answer": 0, "explain": "Résoudre un problème consiste à trouver comment répondre à une question ou corriger quelque chose.", "src": "UNESCO"}, {"ch": 4, "q": "Quelle compétence t’aide à partager clairement tes idées avec un groupe ?", "options": ["Cacher sa voix", "Parler clairement devant un groupe", "Parler très doucement", "Ne jamais parler"], "answer": 1, "explain": "Présenter ses idées t’aide à les partager clairement avec les autres.", "src": "UNESCO"}, {"ch": 4, "q": "Qu’est-ce que le leadership ?", "options": ["Ordonner aux autres de se taire", "Prendre tout le mérite", "Guider les autres de façon utile", "Éviter les responsabilités"], "answer": 2, "explain": "Le leadership consiste à aider et à guider les autres vers un objectif.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Qu’est-ce que la culture numérique ?", "options": ["Utiliser la technologie pour casser des choses", "Ne jamais utiliser d’ordinateur", "Écrire seulement des lettres", "Utiliser la technologie pour trouver et partager des informations"], "answer": 3, "explain": "La culture numérique consiste à utiliser des outils numériques en sécurité pour apprendre et communiquer.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Qu’est-ce qu’une compétence professionnelle ?", "options": ["Une compétence pratique de métier, comme la menuiserie", "Une compétence pour dormir", "Une compétence pour éviter le travail", "Une compétence pour se cacher"], "answer": 0, "explain": "Les compétences professionnelles sont des compétences pratiques utilisées dans un emploi ou un métier.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Que signifie l’égalité des genres à l’école ?", "options": ["Seuls les garçons peuvent apprendre", "Les filles et les garçons ont des chances égales", "Seules les filles peuvent apprendre", "Les filles doivent rester à la maison"], "answer": 1, "explain": "L’égalité des genres signifie que filles et garçons ont les mêmes droits et les mêmes chances en éducation.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Quel groupe l’objectif 4 cite-t-il pour l’accès égal ?", "options": ["Seulement les personnes grandes", "Seulement les personnes de la ville", "Les personnes handicapées", "Seulement les personnes qui aiment le sport"], "answer": 2, "explain": "L’objectif 4 mentionne les personnes handicapées parmi les groupes qui ont besoin d’un accès égal.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Pourquoi les filles manquent-elles parfois l’école ?", "options": ["Les filles n’aiment pas apprendre", "L’école est trop courte", "Les filles ont trop de livres", "Mariage précoce, tâches ménagères ou trajets dangereux"], "answer": 3, "explain": "Le mariage précoce, les tâches ménagères et les trajets dangereux peuvent empêcher les filles d’aller à l’école.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Qu’est-ce qu’un groupe vulnérable en éducation ?", "options": ["Des groupes qui rencontrent plus d’obstacles pour apprendre", "Des groupes qui n’apprennent jamais", "Des groupes qui lisent seulement", "Des groupes très riches"], "answer": 0, "explain": "Les groupes vulnérables font face à plus d’obstacles et peuvent donc avoir besoin d’un soutien supplémentaire.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Qu’est-ce qu’une communauté autochtone ?", "options": ["Un type de bâtiment scolaire", "Les premiers peuples à avoir vécu sur un territoire", "Un type de professeur", "Un type de cartable"], "answer": 1, "explain": "Les peuples autochtones sont les populations originelles d’une région, souvent avec leurs propres langues et cultures.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Qu’est-ce qu’une école adaptée aux filles ?", "options": ["Une école réservée aux filles en ville", "Une école où les filles ne sont pas admises", "Une école avec des toilettes sûres et sans harcèlement", "Une école qui n’enseigne que la danse"], "answer": 2, "explain": "Les écoles adaptées aux filles sont sûres, bien équipées et ont des professeurs respectueux.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 6, "q": "Pourquoi les écoles ont-elles besoin d’assez de professeurs ?", "options": ["Les professeurs ne sont pas nécessaires", "Pour que les enfants arrêtent d’apprendre", "Pour que l’école finisse plus tôt", "Pour que chaque classe ait quelqu’un pour enseigner"], "answer": 3, "explain": "Un nombre suffisant de professeurs permet à chaque classe d’être bien enseignée.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce qu’un professeur qualifié ?", "options": ["Un professeur formé pour enseigner", "Un professeur sans formation", "Un professeur qui raconte seulement des blagues", "Un professeur qui n’enseigne jamais"], "answer": 0, "explain": "Les professeurs qualifiés ont la formation nécessaire pour leur métier.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce qui peut aider les professeurs à rester dans leur métier ?", "options": ["De longues journées sans pause", "Un salaire équitable et de bonnes conditions", "Aucun soutien du tout", "Être muté loin chaque jour"], "answer": 1, "explain": "Un salaire équitable et de bonnes conditions aident les professeurs à rester dans la profession.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce qu’un professeur mentor ?", "options": ["Un professeur qui s’enfuit", "Un professeur qui ne fait que s’asseoir", "Un professeur expérimenté qui aide un collègue plus jeune", "Un professeur qui écrit seulement de la poésie"], "answer": 2, "explain": "Les mentors guident les jeunes professeurs et les aident à progresser.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Pourquoi les professeurs doivent-ils comprendre leurs élèves ?", "options": ["Pour donner davantage de devoirs", "Pour arrêter d’enseigner", "Pour éviter les parents", "Pour enseigner d’une manière qui aide chaque enfant"], "answer": 3, "explain": "Comprendre les élèves aide les professeurs à préparer des cours adaptés.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "Qu’est-ce qu’une école publique ?", "options": ["Une école financée par l’argent de l’État", "Une école qui vend seulement de la nourriture", "Une école dirigée par une seule famille", "Une école sans élèves"], "answer": 0, "explain": "Les écoles publiques sont financées principalement par l’argent public.", "src": "UNESCO"}, {"ch": 7, "q": "Qu’est-ce qu’un budget de l’éducation ?", "options": ["Une liste de dates de vacances", "L’argent prévu pour l’éducation", "Un jeu sur l’argent", "Le prix d’un uniforme scolaire"], "answer": 1, "explain": "Un budget de l’éducation est la somme que l’État prévoit de dépenser pour les écoles.", "src": "UNESCO"}, {"ch": 7, "q": "Que peut-il se passer quand une école manque d’argent ?", "options": ["Plus de professeurs apparaissent", "Les livres deviennent moins chers", "Moins de professeurs et moins de livres", "Les écoles deviennent plus grandes"], "answer": 2, "explain": "Un budget limité peut signifier moins de professeurs et moins de supports d’apprentissage.", "src": "UNESCO"}, {"ch": 7, "q": "Quels frais les familles peuvent-elles encore avoir même quand l’école est gratuite ?", "options": ["Aucun", "Seulement de l’air", "Seulement du soleil", "Les uniformes, les transports et les fournitures"], "answer": 3, "explain": "Les familles peuvent payer les uniformes, le transport et les fournitures scolaires même quand les frais de scolarité sont gratuits.", "src": "UNESCO"}, {"ch": 7, "q": "Qu’est-ce qu’une bourse scolaire ?", "options": ["Une somme versée pour aider une école ou un élève", "Une amende pour un devoir en retard", "Un type d’examen", "Seulement un billet de bus scolaire"], "answer": 0, "explain": "Une bourse est une somme d’argent versée pour aider une école ou un élève, souvent sans remboursement.", "src": "UNESCO"}, {"ch": 8, "q": "En quelle année les Objectifs du Millénaire pour le développement ont-ils commencé ?", "options": ["1948", "2000", "1990", "2015"], "answer": 1, "explain": "Les OMD ont commencé en 2000.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 8, "q": "Où les pays se sont-ils réunis en 1990 pour lancer le mouvement Éducation pour tous ?", "options": ["Paris, en France", "Le Caire, en Égypte", "Jomtien, en Thaïlande", "Tokyo, au Japon"], "answer": 2, "explain": "Les pays se sont réunis à Jomtien, en Thaïlande, en 1990 pour l’Éducation pour tous.", "src": "UNESCO"}, {"ch": 8, "q": "Quel cadre a fixé des objectifs éducatifs à Dakar en 2000 ?", "options": ["Les règles de football de Dakar", "La feuille de route de Dakar", "Le plan alimentaire de Dakar", "Le Cadre d’action de Dakar"], "answer": 3, "explain": "Le Cadre d’action de Dakar a été adopté en 2000 lors du Forum mondial sur l’éducation.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "Quel document dit que l’enseignement primaire doit être obligatoire et gratuit ?", "options": ["La Convention des Nations unies relative aux droits de l’enfant", "Un menu scolaire avec les options de déjeuner de la semaine", "Un guide touristique des plus belles plages de Bali", "Un règlement sportif pour les matchs de football scolaire"], "answer": 0, "explain": "L’article 28 affirme que l’enseignement primaire doit être obligatoire et gratuit pour tous.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 8, "q": "Comment s’appelle l’accord sur l’éducation de 2015 ?", "options": ["La Déclaration de Tokyo", "La Déclaration d’Incheon", "Le Pacte du Caire", "Le Plan de Lima"], "answer": 1, "explain": "La Déclaration d’Incheon de 2015 a fixé les objectifs éducatifs pour 2030.", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 9, "q": "Comment les jeunes enfants apprennent-ils souvent ?", "options": ["Par de longs examens", "Par des heures de silence", "Par le jeu, les chansons et les histoires", "Par des postes de nuit"], "answer": 2, "explain": "L’apprentissage précoce passe souvent par le jeu, les chansons et les histoires.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Pourquoi les premières années de la vie sont-elles importantes pour le cerveau ?", "options": ["Le cerveau cesse de grandir", "Le cerveau ne change pas", "Le cerveau ne grandit que la nuit", "Le cerveau grandit très vite"], "answer": 3, "explain": "Le cerveau se développe très rapidement pendant les premières années.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Que comprennent les soins de la petite enfance ?", "options": ["La santé, la nutrition et l’apprentissage", "Seulement le sommeil", "Seulement le sport", "Seulement l’argent"], "answer": 0, "explain": "Les soins de la petite enfance soutiennent ensemble la santé, l’alimentation et l’apprentissage.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "Qu’est-ce qu’une crèche ?", "options": ["Un lieu seulement pour faire pousser des arbres", "Un lieu où l’on garde de très jeunes enfants", "Un lieu pour envoyer du courrier", "Un lieu pour construire des voitures"], "answer": 1, "explain": "Les crèches accueillent de très jeunes enfants et les aident à apprendre.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Quelle activité aide un tout-petit à apprendre des mots ?", "options": ["Rester silencieux toute la journée", "Regarder seulement des publicités", "Nommer les objets et parler avec lui", "Être enfermé dans une pièce obscure"], "answer": 2, "explain": "Parler et nommer les choses aide les tout-petits à construire le langage.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "Qu’est-ce que le taux d’alphabétisation ?", "options": ["Le prix des livres", "Le nombre de bibliothèques", "Le nombre de professeurs", "La part des personnes qui savent lire et écrire"], "answer": 3, "explain": "Le taux d’alphabétisation indique la part des personnes qui savent lire et écrire.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Pourquoi les adultes ont-ils besoin de savoir lire et écrire ?", "options": ["Pour lire les consignes de travail et les informations de santé", "Pour ne faire aucun travail à l’usine", "Pour gagner tous les matchs de la compétition scolaire", "Pour arrêter d’apprendre de nouvelles choses après l’école"], "answer": 0, "explain": "Savoir lire aide les adultes à travailler, à rester en bonne santé et à participer à la vie.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Qu’est-ce qu’un coin lecture dans une classe ?", "options": ["Un endroit pour ranger les chaussures", "Un espace avec des livres pour lire", "Un endroit réservé au déjeuner", "Un endroit pour ranger les vélos"], "answer": 1, "explain": "Les coins lecture offrent aux enfants un endroit où lire et profiter des livres.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "Qu’est-ce qui aide un enfant qui a du mal à lire ?", "options": ["Moins de temps de lecture", "Qu’on lui dise qu’il n’est pas doué", "Une aide supplémentaire et de l’entraînement à la lecture", "Qu’on ne lui donne jamais de livres"], "answer": 2, "explain": "Une aide supplémentaire et de l’entraînement peuvent aider les enfants à rattraper leur retard.", "src": "UNESCO GEM Report 2026"}, {"ch": 11, "q": "Que signifie l’éducation inclusive ?", "options": ["Une éducation réservée aux meilleurs élèves", "Une éducation réservée à un seul groupe", "Une éducation sans professeurs", "Une éducation qui accueille tous les apprenants"], "answer": 3, "explain": "L’éducation inclusive accueille tous les apprenants et les soutient.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Pourquoi les écoles doivent-elles avoir des rampes et des toilettes accessibles ?", "options": ["Pour que tout le monde puisse utiliser l’école", "Pour que les enfants courent plus vite", "Pour que les écoles paraissent plus hautes", "Pour que les cours soient plus courts"], "answer": 0, "explain": "Des bâtiments accessibles permettent à tous d’utiliser les installations scolaires.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "À quoi sert la langue des signes à l’école ?", "options": ["Seulement pour danser", "Communiquer avec les élèves sourds", "Seulement pour cuisiner", "Seulement pour les contrôles de maths"], "answer": 1, "explain": "La langue des signes aide les élèves sourds à communiquer et à apprendre.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Qui profite d’une école inclusive ?", "options": ["Seulement les professeurs", "Seulement les parents", "Toutes les personnes de l’école", "Seulement le directeur"], "answer": 2, "explain": "Les écoles inclusives aident chaque enfant à apprendre et à grandir ensemble.", "src": "UN CRPD (2006), Article 24"}, {"ch": 3, "q": "Qu’est-ce qu’un plan de cours ?", "options": ["Un plan pour les vacances d’été en famille", "Une liste de snacks vendus à la cantine de l’école", "Un plan montrant les salles et les couloirs d’une école", "Un plan qui indique ce qui sera enseigné et comment"], "answer": 3, "explain": "Un plan de cours fixe les objectifs et les étapes d’une leçon.", "src": "UNESCO Global Report on Teachers (2024)"}], "5": [{"ch": 0, "q": "Combien de cibles de résultats l’objectif 4 comporte-t-il ?", "options": ["Sept", "Trois", "Dix", "Dix-sept"], "answer": 0, "explain": "L’objectif 4 comporte sept cibles de résultats, numérotées de 4.1 à 4.7.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Comment s’appellent les trois cibles des « moyens de mise en œuvre » de l’objectif 4 ?", "options": ["4.1, 4.2 et 4.3", "4.a, 4.b et 4.c", "4.5, 4.6 et 4.7", "4.8, 4.9 et 4.10"], "answer": 1, "explain": "Les cibles 4.a, 4.b et 4.c concernent les équipements, les bourses et les enseignants.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Quel objectif mondial correspond à l’égalité des genres ?", "options": ["L’objectif 2", "L’objectif 8", "L’objectif 5", "L’objectif 11"], "answer": 2, "explain": "L’objectif 5 est l’égalité des genres.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Que signifie ne laisser personne de côté ?", "options": ["Laisser de côté les personnes les plus lentes", "N’aider que les pays riches", "Mettre fin à toute aide", "Inclure les personnes les plus exclues"], "answer": 3, "explain": "Le Programme 2030 promet d’atteindre en premier les personnes les plus en retard.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Pourquoi les objectifs mondiaux sont-ils appelés mondiaux ?", "options": ["Ils s’appliquent à tous les pays", "Ils ne concernent qu’un seul pays", "Ils ne concernent que les écoles", "Ils ne concernent que le sport"], "answer": 0, "explain": "Les objectifs mondiaux s’appliquent à tous les pays, riches comme pauvres.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Quelle est l’année cible des objectifs mondiaux ?", "options": ["2015", "2030", "2050", "2100"], "answer": 1, "explain": "Les objectifs mondiaux doivent être atteints d’ici 2030.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Quel groupe a le plus de risques d’être exclu de l’école dans de nombreux pays ?", "options": ["Les enfants qui adorent lire", "Les enfants qui jouent au football", "Les enfants des zones de conflit", "Les enfants qui fréquentent les bibliothèques"], "answer": 2, "explain": "Les enfants des zones de conflit et de crise ont souvent le plus de mal à aller à l’école.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Que signifie « non scolarisé » ?", "options": ["Apprendre dans une bibliothèque", "Aller à l’école le dimanche", "Gagner un prix scolaire", "Non inscrit dans une école"], "answer": 3, "explain": "Les enfants non scolarisés sont ceux qui ne sont inscrits dans aucune école.", "src": "UNESCO"}, {"ch": 1, "q": "Pourquoi de nombreux enfants travaillent-ils au lieu d’aller à l’école ?", "options": ["Les familles ont besoin de leurs revenus", "Ils préfèrent travailler", "L’école est gratuite", "On apprend à travailler à l’école"], "answer": 0, "explain": "Les familles pauvres peuvent avoir besoin que leurs enfants travaillent pour gagner de l’argent.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Qu’est-ce que le travail des enfants ?", "options": ["Tout jeu calme à la maison avec des amis après l’école", "Un travail qui nuit à la santé des enfants ou interrompt leur scolarité", "Aider un parent pour les devoirs et de petites tâches à la maison", "Lire des histoires à voix haute à un petit frère ou une petite sœur"], "answer": 1, "explain": "Le travail des enfants est un travail qui nuit aux enfants et les empêche d’apprendre.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Qu’est-ce qu’un programme d’alimentation scolaire ?", "options": ["De la nourriture vendue dans les magasins", "Un type de sport scolaire", "Des repas distribués aux enfants à l’école", "Une fête de la gastronomie"], "answer": 2, "explain": "Les repas scolaires peuvent encourager les enfants à venir à l’école et à apprendre.", "src": "UNESCO"}, {"ch": 1, "q": "Pourquoi les repas scolaires peuvent-ils aider les enfants ?", "options": ["Ils empêchent d’apprendre", "Ils prennent tout l’argent", "Ils remplacent les livres", "Ils encouragent les enfants à venir à l’école"], "answer": 3, "explain": "Les repas peuvent faciliter la présence des enfants à l’école et leur concentration.", "src": "UNESCO"}, {"ch": 2, "q": "Qu’est-ce que la transition entre l’école primaire et le collège ?", "options": ["Passer d’un niveau scolaire au suivant", "Seulement déménager", "Changer de place dans la même classe", "Quitter l’école pour toujours"], "answer": 0, "explain": "La transition désigne le passage d’une étape de la scolarité à la suivante.", "src": "UNESCO"}, {"ch": 2, "q": "Pourquoi certains enfants redoublent-ils une année ?", "options": ["Redoubler est toujours des vacances", "Ils ont besoin de plus de temps pour apprendre les notions", "Redoubler est un prix", "Ils ont trop d’amis"], "answer": 1, "explain": "Certains enfants redoublent lorsqu’ils ont besoin de plus de temps pour apprendre.", "src": "UNESCO"}, {"ch": 2, "q": "Que signifie obtenir un diplôme ?", "options": ["Commencer une nouvelle école", "Déménager dans un autre pays", "Terminer un niveau d’études", "Arrêter d’aller en cours"], "answer": 2, "explain": "Obtenir un diplôme signifie achever avec succès un niveau d’études.", "src": "UNESCO"}, {"ch": 2, "q": "Quel est l’objectif de la fin du secondaire ?", "options": ["Seulement obtenir des vacances", "Seulement éviter les examens", "Seulement arrêter de lire", "Des compétences pour le travail et les études ultérieures"], "answer": 3, "explain": "L’enseignement secondaire développe des compétences pour le travail et les études ultérieures.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Que signifie la rétention scolaire ?", "options": ["Garder les élèves à l’école jusqu’à la fin de leur scolarité", "Enfermer les élèves dans une boîte", "Garder les livres pour toujours", "Garder l’école fermée"], "answer": 0, "explain": "La rétention signifie que les élèves restent à l’école jusqu’à avoir achevé le niveau.", "src": "UNESCO"}, {"ch": 2, "q": "Quel facteur aide les élèves à rester à l’école ?", "options": ["Être obligé de quitter l’école", "Un trajet sûr jusqu’à l’école", "Ne pas avoir de livres", "Manquer chaque contrôle"], "answer": 1, "explain": "Des trajets sûrs facilitent le maintien des enfants à l’école.", "src": "UNESCO"}, {"ch": 3, "q": "Que signifie l’évaluation des apprentissages ?", "options": ["Mesurer les bâtiments scolaires", "Compter les bureaux", "Mesurer ce que les élèves ont appris", "Compter les voitures des professeurs"], "answer": 2, "explain": "Les évaluations des apprentissages vérifient ce que les élèves savent et savent faire.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Qu’est-ce que la pauvreté d’apprentissage ?", "options": ["Ne pas avoir de crayon ni de cahier pour le travail en classe", "Ne pas avoir d’ordinateur à la maison pour faire ses devoirs", "Habiter loin de la bibliothèque la plus proche", "Ne pas savoir lire un texte simple à dix ans"], "answer": 3, "explain": "La pauvreté d’apprentissage signifie qu’un enfant ne peut pas lire et comprendre un texte simple à dix ans.", "src": "World Bank, learning poverty"}, {"ch": 3, "q": "Qu’est-ce qu’une compétence fondamentale ?", "options": ["Une compétence de base comme la lecture ou le calcul", "Une matière universitaire difficile", "Un type de sport", "Un type de musique"], "answer": 0, "explain": "Les compétences fondamentales, comme la lecture et le calcul, soutiennent tous les apprentissages ultérieurs.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Pourquoi la lecture précoce est-elle importante ?", "options": ["Elle n’aide qu’en arts plastiques", "Elle soutient l’apprentissage dans toutes les matières", "Elle n’est pas nécessaire à l’école", "Elle n’aide qu’en sport"], "answer": 1, "explain": "Les enfants qui lisent bien peuvent apprendre plus facilement dans toutes les matières.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Qu’est-ce que l’évaluation formative ?", "options": ["Seulement un examen final", "Un test de la taille d’un élève", "Vérifier les apprentissages pendant les cours", "Un test de compétences culinaires"], "answer": 2, "explain": "L’évaluation formative aide les professeurs à vérifier les progrès et à adapter leurs cours.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Qu’est-ce que l’évaluation sommative ?", "options": ["Une question posée seulement au début", "Un jeu sans notes", "Un test donné chaque matin", "Un test à la fin d’une unité ou d’une année"], "answer": 3, "explain": "L’évaluation sommative mesure les apprentissages à la fin d’une période.", "src": "UNESCO GEM Report 2026"}, {"ch": 4, "q": "Qu’est-ce que la créativité dans l’apprentissage ?", "options": ["Trouver des idées nouvelles et utiles", "Copier exactement", "N’utiliser que de vieilles idées", "Éviter toutes les idées"], "answer": 0, "explain": "La créativité consiste à trouver des manières nouvelles et utiles de penser et d’agir.", "src": "UNESCO"}, {"ch": 4, "q": "Quelle compétence t’aide à travailler avec des personnes de cultures différentes ?", "options": ["Se cacher des différences", "La compréhension interculturelle", "Refuser de parler", "Ignorer les autres langues"], "answer": 1, "explain": "La compréhension interculturelle aide à respecter les autres et à travailler avec eux.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Qu’est-ce que la résilience ?", "options": ["Abandonner au premier obstacle", "Ne jamais affronter de problèmes", "Rebondir après une difficulté", "Éviter toute nouveauté"], "answer": 2, "explain": "La résilience consiste à se relever et à apprendre des moments difficiles.", "src": "UNESCO"}, {"ch": 4, "q": "Pourquoi enseigne-t-on des compétences de vie dans certaines écoles ?", "options": ["Pour remplacer tous les cours de maths par des cours d’arts", "Pour allonger la journée scolaire de tout le monde", "Pour supprimer tous les examens de l’année", "Pour aider les élèves à faire face aux défis du quotidien"], "answer": 3, "explain": "Les compétences de vie aident les élèves à bien décider et à résoudre les problèmes du quotidien.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Qu’est-ce que la culture financière ?", "options": ["Comprendre l’argent et savoir le gérer", "Collectionner des pièces seulement pour le plaisir", "Ignorer les prix", "Dépenser tout son argent d’un coup"], "answer": 0, "explain": "La culture financière consiste à savoir utiliser et épargner son argent avec discernement.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Quelle compétence t’aide à utiliser des informations provenant de nombreuses sources ?", "options": ["Chanter", "Les compétences de recherche", "Jongler", "Seulement le jardinage"], "answer": 1, "explain": "Les compétences de recherche aident les élèves à trouver et à vérifier des informations.", "src": "UNESCO"}, {"ch": 5, "q": "Qu’est-ce que l’indice de parité entre les sexes ?", "options": ["Une mesure de la hauteur de l’école", "Un décompte des animaux de compagnie des professeurs", "Un chiffre qui compare la scolarisation des filles et des garçons", "Une liste des couleurs de l’école"], "answer": 2, "explain": "Un indice de parité proche de 1 signifie que filles et garçons sont scolarisés à égalité.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Que signifie un indice de parité de 1 ?", "options": ["Aucune fille à l’école", "Seulement des filles à l’école", "Il y a deux fois plus de garçons", "Un nombre égal de filles et de garçons"], "answer": 3, "explain": "Une valeur de 1 montre que filles et garçons sont scolarisés en nombre égal.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Quel groupe peut rencontrer des obstacles supplémentaires à cause d’un handicap ?", "options": ["Les enfants handicapés", "Les enfants qui aiment dessiner", "Les enfants qui jouent", "Les enfants qui portent des lunettes"], "answer": 0, "explain": "Les enfants handicapés peuvent rencontrer des obstacles supplémentaires sans soutien.", "src": "UN CRPD (2006), Article 24"}, {"ch": 5, "q": "Qu’est-ce que la discrimination à l’école ?", "options": ["Un traitement équitable pour tous", "Un traitement injuste en raison de ce que l’on est", "Choisir les livres selon leur couleur", "Donner les mêmes devoirs à tous"], "answer": 1, "explain": "La discrimination est un traitement injuste fondé sur le groupe ou le milieu d’une personne.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Pourquoi les écoles doivent-elles être exemptes de violence ?", "options": ["La violence aide les enfants à se concentrer", "La violence fait partie de la vie normale de l’école", "La violence empêche les enfants d’apprendre", "La violence rend les enfants plus forts"], "answer": 2, "explain": "Les enfants ne peuvent pas bien apprendre lorsqu’ils se sentent en insécurité.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Que font les politiques inclusives ?", "options": ["Elles ferment les écoles pour certains groupes", "Elles réservent les écoles aux riches", "Elles suppriment tous les professeurs", "Elles rendent l’éducation accessible à tous les groupes"], "answer": 3, "explain": "Les politiques inclusives aident tous les groupes à accéder à l’éducation et à en bénéficier.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "Qu’est-ce que le ratio élèves-professeur ?", "options": ["Le nombre d’élèves par professeur", "Le nombre de professeurs payés", "Le nombre de bureaux dans une salle", "Le nombre d’écoles visitées par un professeur"], "answer": 0, "explain": "Le ratio élèves-professeur indique combien d’élèves partagent un même professeur.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Pourquoi un faible ratio élèves-professeur est-il important ?", "options": ["Les professeurs n’ont rien à faire", "Les professeurs peuvent accorder plus d’attention à chaque enfant", "Cela signifie que les classes sont plus bruyantes", "Cela rend les professeurs plus riches"], "answer": 1, "explain": "Des classes plus petites permettent aux professeurs d’aider davantage chaque enfant.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce que la motivation des enseignants ?", "options": ["Être payé pour dormir", "Travailler le moins possible", "L’élan et l’enthousiasme pour bien enseigner", "Éviter les élèves"], "answer": 2, "explain": "Les enseignants motivés sont plus susceptibles de rester et de bien enseigner.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Pourquoi la formation des enseignants est-elle importante ?", "options": ["Elle remplace les cours", "Elle supprime le besoin d’élèves", "Elle ajoute seulement des vacances", "Elle améliore la qualité de l’enseignement"], "answer": 3, "explain": "Une bonne formation aide les enseignants à enseigner de manière efficace.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce qu’une école de formation des enseignants ?", "options": ["Un lieu où les enseignants sont formés", "Un lieu où l’on vend seulement du matériel pédagogique", "Une école pour les animaux de compagnie", "Un lieu pour construire des routes"], "answer": 0, "explain": "Les écoles de formation des enseignants préparent les personnes à devenir professeurs.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce qui peut soutenir les enseignants en zone rurale ?", "options": ["Aucun soutien du tout", "Un logement, des transports et une formation", "Être muté chaque jour", "Moins de salaire et plus de travail"], "answer": 1, "explain": "Un soutien comme le logement et les transports aide les enseignants à servir les communautés rurales.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "Qu’est-ce que la dépense publique d’éducation ?", "options": ["L’argent que les familles dépensent en jouets", "L’argent dépensé seulement pour le sport", "L’argent que les États consacrent aux écoles", "L’argent dépensé seulement pour les routes"], "answer": 2, "explain": "La dépense publique d’éducation est l’argent utilisé par les États pour faire fonctionner les écoles.", "src": "UNESCO"}, {"ch": 7, "q": "Qu’est-ce qu’un bon scolaire ?", "options": ["Un type d’uniforme scolaire", "Un billet pour un musée", "Un plan des lignes de bus", "Une aide qui paie les frais de scolarité"], "answer": 3, "explain": "Les bons peuvent aider les familles à payer les frais scolaires dans certains pays.", "src": "UNESCO"}, {"ch": 7, "q": "Quel coût peut éloigner les enfants pauvres de l’école ?", "options": ["Les frais et les uniformes", "Les livres gratuits", "Les repas gratuits", "Les transports gratuits"], "answer": 0, "explain": "Les frais et les uniformes peuvent être trop chers pour certaines familles.", "src": "UNESCO"}, {"ch": 7, "q": "Que signifie généralement l’éducation gratuite ?", "options": ["Des vacances gratuites", "Pas de frais de scolarité", "Des voitures gratuites", "Des bonbons gratuits"], "answer": 1, "explain": "L’éducation gratuite signifie en général qu’il n’y a pas de frais de scolarité, même si d’autres coûts peuvent s’appliquer.", "src": "UNESCO"}, {"ch": 8, "q": "En quelle année l’Éducation pour tous a-t-elle été adoptée à Jomtien ?", "options": ["1948", "1989", "1990", "2000"], "answer": 2, "explain": "L’Éducation pour tous a été adoptée à Jomtien en 1990.", "src": "UNESCO"}, {"ch": 8, "q": "Quel était l’objectif du Cadre de Dakar en 2000 ?", "options": ["L’éducation réservée aux adultes", "Aucune école du tout", "L’éducation seulement dans les villes", "L’Éducation pour tous d’ici 2015"], "answer": 3, "explain": "Le Cadre de Dakar fixait des objectifs pour atteindre l’Éducation pour tous d’ici 2015.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "Quel objectif du Millénaire pour le développement concernait l’enseignement primaire universel ?", "options": ["L’objectif 2", "L’objectif 1", "L’objectif 5", "L’objectif 8"], "answer": 0, "explain": "L’OMD 2 visait l’enseignement primaire universel.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 8, "q": "Qu’est-ce que le Forum mondial sur l’éducation ?", "options": ["Un match de football entre deux équipes nationales d’Asie", "Une réunion de pays et de partenaires sur l’éducation", "Un concours de cuisine pour les élèves et les familles", "Un festival de cinéma pour jeunes réalisateurs et acteurs"], "answer": 1, "explain": "Le Forum mondial sur l’éducation réunit des pays et des partenaires pour discuter d’éducation.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "Quel cadre soutient la Déclaration d’Incheon ?", "options": ["Le Cadre Sport 2030", "Le Plan Cuisine 2030", "Le Cadre d’action Éducation 2030", "Le Plan Musique 2030"], "answer": 2, "explain": "Le Cadre d’action Éducation 2030 guide les pays pour atteindre l’ODD 4.", "src": "Incheon Framework for Action (2015)"}, {"ch": 8, "q": "En quelle année les Objectifs du Millénaire pour le développement se sont-ils achevés ?", "options": ["2000", "2030", "2010", "2015"], "answer": 3, "explain": "Les OMD se sont achevés en 2015 et ont été remplacés par les objectifs mondiaux.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 9, "q": "Qu’est-ce que le développement de la petite enfance ?", "options": ["La croissance en santé, en apprentissage et en bien-être dès la naissance", "La croissance seulement en taille et en poids, année après année", "Apprendre seulement à l’université après de nombreuses années", "Jouer seulement dehors chaque jour"], "answer": 0, "explain": "Le développement de la petite enfance couvre la santé, l’apprentissage et le bien-être dès la naissance.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Qu’est-ce que le « renvoi de balle » dans la petite enfance ?", "options": ["Un type de partie de tennis sur gazon en été", "Un échange d’allers-retours entre un enfant et un adulte", "Une façon de rendre les jouets à une association caritative", "Un long sommeil que les bébés font chaque après-midi"], "answer": 1, "explain": "Le renvoi de balle est l’échange d’allers-retours qui construit le cerveau.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Pourquoi les jeunes enfants ont-ils besoin d’adultes attentifs ?", "options": ["Les adultes ne sont pas nécessaires", "Les adultes donnent seulement des ordres", "Ils apprennent d’eux le langage et les émotions", "Les adultes doivent rester silencieux"], "answer": 2, "explain": "Des adultes attentifs aident les enfants à développer le langage, les émotions et la pensée.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Quelle cible de l’ODD 4 concerne la petite enfance ?", "options": ["La cible 4.1", "La cible 4.6", "La cible 4.c", "La cible 4.2"], "answer": 3, "explain": "La cible 4.2 porte sur le développement, les soins et l’enseignement préprimaire de la petite enfance.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "À quoi sert l’enseignement préprimaire ?", "options": ["Préparer les jeunes enfants à l’école primaire", "Les préparer à l’université", "Remplacer l’école primaire", "Faire travailler les enfants"], "answer": 0, "explain": "L’enseignement préprimaire donne aux jeunes enfants des compétences avant l’école primaire.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "Pourquoi l’alimentation est-elle importante dans la petite enfance ?", "options": ["La nourriture n’a aucun effet sur le cerveau", "Une bonne alimentation favorise une croissance saine du cerveau", "Les enfants n’ont besoin que de bonbons", "Les enfants ne doivent manger qu’une fois par semaine"], "answer": 1, "explain": "Une alimentation saine soutient le cerveau et le corps pendant la forte croissance.", "src": "UN 2030 Agenda (2015)"}, {"ch": 10, "q": "Qu’est-ce que l’alphabétisation fonctionnelle ?", "options": ["Lire seulement des magazines et des bandes dessinées pour le plaisir", "Écrire seulement des poèmes et des chansons pour les spectacles de l’école", "Savoir lire et écrire suffisamment pour la vie quotidienne", "Lire seulement les chiffres imprimés sur les factures et les billets"], "answer": 2, "explain": "L’alphabétisation fonctionnelle signifie savoir lire et écrire assez pour accomplir les tâches du quotidien.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Quelles sont les deux compétences de base au cœur de la cible 4.6 ?", "options": ["Chanter et dessiner", "Cuisiner et conduire", "Marcher et courir", "La lecture-écriture et la numératie"], "answer": 3, "explain": "La cible 4.6 vise à ce que les jeunes et les adultes maîtrisent la lecture-écriture et la numératie.", "src": "UN 2030 Agenda (2015)"}, {"ch": 10, "q": "Pourquoi les bibliothèques aident-elles à l’alphabétisation ?", "options": ["Elles donnent un accès gratuit aux livres", "Elles vendent seulement des livres chers", "Elles sont fermées aux enfants", "Elles ne stockent que des meubles"], "answer": 0, "explain": "Les bibliothèques donnent à chacun un accès gratuit aux livres et à des lieux de lecture.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "Qu’est-ce que la fluidité en lecture ?", "options": ["Lire sans comprendre", "Lire avec aisance et précision", "Lire à l’envers", "Lire seulement en silence"], "answer": 1, "explain": "La fluidité consiste à lire avec aisance, précision et expression.", "src": "UNESCO GEM Report 2026"}, {"ch": 11, "q": "Qu’est-ce qu’une salle de ressources dans une école ?", "options": ["Une salle qui stocke seulement de vieux meubles", "Une salle qui vend des uniformes scolaires", "Une salle qui apporte une aide supplémentaire aux élèves qui en ont besoin", "Une salle qui conserve des trophées sportifs"], "answer": 2, "explain": "Une salle de ressources apporte un soutien supplémentaire aux élèves ayant des besoins d’apprentissage ou un handicap.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Que signifie la conception universelle pour les écoles ?", "options": ["Un seul type de bâtiment pour une ville", "Des bâtiments sans portes", "Des bâtiments réservés aux animaux", "Des bâtiments et des outils utilisables par tous"], "answer": 3, "explain": "La conception universelle rend les bâtiments et les outils utilisables par le plus grand nombre possible de personnes.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Pourquoi les enfants handicapés ont-ils parfois besoin d’aides techniques ?", "options": ["Elles les aident à entendre, à voir ou à se déplacer", "Elles les font dormir", "Elles remplacent les professeurs", "Elles les empêchent d’apprendre"], "answer": 0, "explain": "Les aides techniques, comme les appareils auditifs ou les fauteuils roulants, aident les enfants à participer à la vie scolaire.", "src": "UN CRPD (2006), Article 24"}], "6": [{"ch": 0, "q": "Quelle cible de l’ODD 4 concerne l’enseignement primaire et secondaire gratuit, équitable et de qualité ?", "options": ["La cible 4.1", "La cible 4.2", "La cible 4.4", "La cible 4.7"], "answer": 0, "explain": "La cible 4.1 vise un enseignement primaire et secondaire gratuit, équitable et de qualité.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Quelle cible mentionne les compétences techniques et professionnelles pour l’emploi ?", "options": ["La cible 4.1", "La cible 4.4", "La cible 4.5", "La cible 4.b"], "answer": 1, "explain": "La cible 4.4 porte sur les compétences, y compris techniques et professionnelles, pour l’emploi.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Quelle cible concerne les bourses pour les étudiants des pays en développement ?", "options": ["La cible 4.a", "La cible 4.c", "La cible 4.b", "La cible 4.6"], "answer": 2, "explain": "La cible 4.b demande davantage de bourses pour les étudiants des pays en développement.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Quelle cible concerne l’offre d’enseignants qualifiés ?", "options": ["La cible 4.b", "La cible 4.2", "La cible 4.7", "La cible 4.c"], "answer": 3, "explain": "La cible 4.c vise à augmenter le nombre d’enseignants qualifiés.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Quelle cible concerne la construction et l’amélioration des équipements éducatifs ?", "options": ["La cible 4.a", "La cible 4.1", "La cible 4.3", "La cible 4.5"], "answer": 0, "explain": "La cible 4.a appelle à des équipements d’apprentissage sûrs, inclusifs et efficaces.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "De quoi traite la cible 4.7 ?", "options": ["Seulement du sport, des jeux et de la condition physique toute l’année scolaire", "Des connaissances et compétences pour le développement durable et la citoyenneté mondiale", "Seulement de l’argent, de la banque et des comptes d’entreprise pour les adultes", "Seulement de la cuisine, de l’alimentation et de la nutrition pour la cantine"], "answer": 1, "explain": "La cible 4.7 couvre le développement durable, les droits humains, l’égalité des genres et la citoyenneté mondiale.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Quelle cible porte sur le développement de la petite enfance et l’enseignement préprimaire ?", "options": ["La cible 4.1", "La cible 4.6", "La cible 4.2", "La cible 4.c"], "answer": 2, "explain": "La cible 4.2 concerne le développement, les soins et l’enseignement préprimaire de la petite enfance.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Que signifie équitable dans la cible 4.1 ?", "options": ["Seulement pour les familles les plus riches du pays", "Seulement pour ceux qui vivent dans les grandes villes", "Seulement pour les adultes qui ont terminé leur scolarité", "Juste pour tous, y compris les plus défavorisés"], "answer": 3, "explain": "Un enseignement équitable atteint chacun de manière juste, y compris les personnes défavorisées.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Quel groupe est nommé dans la cible 4.5 comme ayant besoin d’un accès égal ?", "options": ["Les peuples autochtones", "Seulement les personnes qui ont de l’argent", "Seulement les personnes des grandes villes", "Seulement les personnes qui parlent une seule langue"], "answer": 0, "explain": "La cible 4.5 nomme les personnes handicapées, les peuples autochtones et les enfants en situation de vulnérabilité.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Pourquoi l’enseignement primaire gratuit est-il important ?", "options": ["Il augmente les frais de scolarité", "Il supprime un obstacle majeur pour les familles pauvres", "Il empêche les enfants d’apprendre", "Il rend les écoles moins utiles"], "answer": 1, "explain": "L’enseignement primaire gratuit aide les familles qui ne peuvent pas payer les frais.", "src": "UNESCO"}, {"ch": 1, "q": "Que signifie l’enseignement primaire universel ?", "options": ["Seuls certains enfants fréquentent l’école primaire", "Seuls les adultes fréquentent l’école primaire", "Chaque enfant peut fréquenter l’école primaire", "L’école primaire est facultative pour tous"], "answer": 2, "explain": "L’enseignement primaire universel signifie que chaque enfant a une place à l’école primaire.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 1, "q": "Quels enfants peuvent rester hors de l’école même lorsque les frais sont supprimés ?", "options": ["Les enfants très grands", "Les enfants qui aiment lire", "Les enfants qui ne mangent jamais", "Les enfants handicapés ou vivant dans des zones isolées"], "answer": 3, "explain": "Le coût n’est pas le seul obstacle : le handicap, la distance et la discrimination tiennent aussi les enfants à l’écart.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "À quoi sert le suivi des taux d’achèvement ?", "options": ["Voir si les enfants terminent l’école", "Choisir les meilleures destinations de vacances pour les sorties scolaires", "Vendre plus de livres scolaires dans les magasins locaux", "Mesurer la taille des bureaux dans chaque salle de classe"], "answer": 0, "explain": "Les taux d’achèvement montrent si les enfants atteignent la fin de chaque niveau.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Pourquoi les taux d’achèvement du secondaire sont-ils importants ?", "options": ["Ils montrent combien de professeurs dorment", "Ils montrent les progrès vers la cible 4.1", "Ils montrent le prix des cartables", "Ils montrent la météo"], "answer": 1, "explain": "Les taux d’achèvement aident à suivre les progrès vers l’objectif 4.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Qu’est-ce que l’éducation de la deuxième chance ?", "options": ["Un apprentissage seulement après l’obtention d’un diplôme universitaire", "Un apprentissage seulement par le sport et les jeux sur le terrain", "Des possibilités d’apprentissage pour les personnes qui ont manqué l’école", "Un apprentissage interdit dans la plupart des pays aujourd’hui"], "answer": 2, "explain": "L’éducation de la deuxième chance aide les personnes à rattraper les apprentissages qu’elles ont manqués.", "src": "UNESCO"}, {"ch": 2, "q": "Qu’est-ce qu’un programme passerelle ?", "options": ["Un programme pour construire des ponts sur les rivières et les routes", "Un programme qui ferme chaque année les écoles des villages isolés", "Un programme de sport et de jeux le week-end pour tous", "Un programme qui aide les apprenants à passer d’un niveau ou d’un système à l’autre"], "answer": 3, "explain": "Les programmes passerelles aident les apprenants à passer en douceur de l’école à la formation.", "src": "UNESCO"}, {"ch": 2, "q": "Pourquoi les élèves décrochent-ils au collège ?", "options": ["Les coûts, le travail et la distance", "Ils finissent trop vite", "Ils reçoivent trop de prix", "Ils n’ont pas de devoirs"], "answer": 0, "explain": "Les coûts, le travail et la distance sont des raisons fréquentes de quitter l’école tôt.", "src": "UNESCO"}, {"ch": 2, "q": "Qu’est-ce qui peut aider un élève à reprendre l’école après l’avoir quittée ?", "options": ["L’exclusion définitive", "Un programme souple et un accompagnement", "Être obligé de redoubler la même année", "Une sanction des professeurs"], "answer": 1, "explain": "Les programmes souples et l’accompagnement aident les élèves à reprendre leurs apprentissages.", "src": "UNESCO"}, {"ch": 3, "q": "Quel type d’apprentissage la cible 4.1 vise-t-elle ?", "options": ["Seulement une belle écriture", "Seulement de bonnes notes en sport", "Un apprentissage pertinent et efficace", "Seulement une lecture plus rapide"], "answer": 2, "explain": "La cible 4.1 vise des résultats d’apprentissage pertinents et efficaces, et pas seulement la présence.", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "Pourquoi mesurer les apprentissages est-il plus difficile que compter les présences ?", "options": ["Les apprentissages sont toujours faciles à compter", "La présence ne peut jamais être comptée", "Les apprentissages se mesurent seulement à la taille", "Les apprentissages doivent être évalués, pas seulement comptés"], "answer": 3, "explain": "La présence indique seulement qu’un élève est là, alors que les apprentissages demandent d’évaluer les compétences et la compréhension.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Qu’est-ce qu’un niveau minimal de maîtrise ?", "options": ["Le niveau le plus bas qu’un apprenant doit atteindre", "Le niveau le plus élevé d’apprentissage", "Un niveau réservé aux professeurs", "Un niveau pour les bâtiments scolaires"], "answer": 0, "explain": "Le niveau minimal de maîtrise est la compétence de base que tous les apprenants doivent atteindre.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Pourquoi de nombreux pays évaluent-ils la lecture et les mathématiques ?", "options": ["Pour choisir le déjeuner", "Pour voir si les apprenants atteignent les compétences de base", "Pour vérifier la météo", "Pour décider des vacances"], "answer": 1, "explain": "Les tests montrent si les apprenants atteignent les compétences de base essentielles.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Qu’est-ce que l’équité dans les apprentissages ?", "options": ["Seuls les meilleurs élèves apprennent", "Chacun reçoit exactement le même soutien quels que soient ses besoins", "Chaque apprenant a une chance équitable de bien apprendre", "L’apprentissage n’a lieu que dans certaines écoles"], "answer": 2, "explain": "L’équité dans les apprentissages consiste à apporter plus de soutien là où il est nécessaire.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Quelle compétence relie les lettres aux sons pour aider les enfants à lire ?", "options": ["Le jonglage", "La peinture", "Seulement la danse", "La phonétique"], "answer": 3, "explain": "La phonétique relie les lettres aux sons et aide les enfants à lire.", "src": "UNESCO GEM Report 2026"}, {"ch": 4, "q": "Qu’est-ce que la pensée computationnelle ?", "options": ["Découper un problème en étapes pour le résoudre", "Utiliser une calculatrice pour tout", "Deviner les réponses", "Éviter les énigmes"], "answer": 0, "explain": "La pensée computationnelle découpe les problèmes en étapes, une compétence utile en programmation et au-delà.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Qu’est-ce que l’éducation à l’entrepreneuriat ?", "options": ["Apprendre à bien dormir et à se reposer pendant la journée", "Apprendre à lancer et à gérer une entreprise ou un projet", "Apprendre à éviter le travail et à rester à la maison", "Apprendre à chanter dans une chorale chaque semaine"], "answer": 1, "explain": "L’éducation à l’entrepreneuriat aide les apprenants à créer et à gérer leurs propres idées.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Qu’est-ce que la citoyenneté mondiale ?", "options": ["Vivre seulement dans une ville", "Refuser d’apprendre sur d’autres pays", "Comprendre et se soucier du monde dans son ensemble", "Ignorer les autres personnes"], "answer": 2, "explain": "La citoyenneté mondiale encourage à comprendre et à respecter le monde dans son ensemble.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Quelle compétence aide à juger si une information est vraie ?", "options": ["Le jonglage", "Le jardinage", "La cuisine", "L’éducation aux médias"], "answer": 3, "explain": "L’éducation aux médias aide à vérifier les informations provenant de différentes sources.", "src": "UNESCO"}, {"ch": 4, "q": "Qu’est-ce que la collaboration dans l’apprentissage ?", "options": ["Travailler ensemble pour atteindre un objectif commun", "Travailler seul pour battre les autres", "Copier ses camarades", "Éviter les travaux de groupe"], "answer": 0, "explain": "La collaboration signifie que les apprenants travaillent ensemble et partagent la responsabilité.", "src": "UNESCO"}, {"ch": 4, "q": "Que signifie culture de la paix dans la cible 4.7 ?", "options": ["Vivre à l’écart des autres", "Vivre ensemble sans violence", "Gagner toutes les discussions", "Ignorer les autres cultures"], "answer": 1, "explain": "Une culture de la paix favorise la non-violence, le respect et la compréhension.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Quel facteur peut tenir les filles à l’écart du secondaire ?", "options": ["Le beau temps", "Les livres gratuits", "Le mariage précoce et les tâches domestiques", "Trop de professeurs"], "answer": 2, "explain": "Le mariage précoce et les tâches domestiques peuvent empêcher les filles de terminer le secondaire.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Qu’est-ce que les données désagrégées ?", "options": ["Des données tenues secrètes pour toujours", "Des données qui ne servent jamais à prendre de décisions", "Des données sur la météo de la région chaque jour", "Des données réparties par groupe, comme le genre ou le handicap"], "answer": 3, "explain": "Les données désagrégées aident à révéler qui est laissé de côté.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Pourquoi les données désagrégées sont-elles utiles ?", "options": ["Elles montrent quels groupes ont besoin d’aide", "Elles cachent les problèmes", "Elles ne sont jamais exactes", "Elles n’aident que les entreprises"], "answer": 0, "explain": "Répartir les données par groupe montre où un soutien est nécessaire.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Qu’est-ce que la violence fondée sur le genre liée à l’école ?", "options": ["Une règle de sport sur la façon de plaquer", "Une violence liée au genre à l’intérieur ou autour des écoles", "Un type d’examen passé à la fin de l’année", "Des vacances scolaires qui durent deux semaines entières"], "answer": 1, "explain": "Cette violence est liée au genre et nuit aux apprentissages des enfants.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Que peuvent faire les écoles pour protéger les enfants de la violence ?", "options": ["Ignorer les plaintes des élèves et de leurs parents", "Punir les enfants qui signalent des problèmes au personnel", "Mettre en place des systèmes sûrs de signalement et former le personnel", "Fermer l’école chaque fois qu’une plainte est déposée"], "answer": 2, "explain": "Des systèmes de signalement sûrs et la formation du personnel aident à protéger les enfants.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Qu’est-ce qu’un environnement d’apprentissage sûr ?", "options": ["Un lieu sans professeurs", "Un lieu sans aucune règle", "Un lieu où les élèves sont toujours seuls", "Un lieu où les élèves se sentent en sécurité pour apprendre"], "answer": 3, "explain": "Les environnements d’apprentissage sûrs permettent aux élèves d’apprendre sans crainte.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "Pourquoi est-il important de bien payer les professeurs ?", "options": ["Cela aide à garder des professeurs qualifiés dans les écoles", "Cela rend les écoles plus pauvres", "Cela réduit les apprentissages", "Cela empêche les professeurs de se soucier des élèves"], "answer": 0, "explain": "Un salaire équitable aide à retenir les professeurs formés dans les écoles.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce que l’attrition des enseignants ?", "options": ["Des professeurs qui sont promus", "Des professeurs qui quittent la profession", "Des professeurs qui prennent des vacances", "Des professeurs qui remportent des prix"], "answer": 1, "explain": "L’attrition désigne le départ des professeurs de la profession, ce qui nuit aux apprentissages.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce qu’un parcours professionnel pour les enseignants ?", "options": ["Un chemin seulement jusqu’au portail de l’école", "Un chemin réservé aux élèves", "Une voie de développement et de promotion", "Un chemin sans salaire"], "answer": 2, "explain": "Les parcours professionnels offrent aux enseignants des moyens de progresser et d’évoluer.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce que le développement professionnel continu des enseignants ?", "options": ["Une seule journée de formation pour toujours", "Aucune formation après l’obtention du diplôme", "Une formation réservée aux directeurs", "Une formation continue tout au long de la carrière"], "answer": 3, "explain": "Le développement continu permet aux enseignants de rester compétents tout au long de leur carrière.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Pourquoi la qualité des enseignants est-elle importante ?", "options": ["C’est l’un des facteurs clés de la réussite des enfants", "Elle n’a aucun effet sur l’apprentissage des enfants", "Elle compte seulement pour le sport et l’éducation physique", "Elle compte seulement pour l’aspect du bâtiment scolaire"], "answer": 0, "explain": "La qualité des enseignants est l’un des facteurs clés de la réussite des enfants.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Pourquoi les zones rurales ont-elles souvent du mal à garder leurs enseignants ?", "options": ["Les zones rurales ont trop d’enseignants", "Trop peu d’enseignants veulent y travailler", "Les enseignants préfèrent les vacances", "Les enseignants ne voyagent jamais"], "answer": 1, "explain": "Les zones rurales peinent souvent à attirer et à retenir assez d’enseignants.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "Qu’est-ce que le financement national de l’éducation ?", "options": ["L’argent venant de la Lune", "L’argent venant seulement des clubs de sport", "L’argent qu’un pays lève lui-même pour ses écoles", "L’argent venant seulement des uniformes scolaires"], "answer": 2, "explain": "Le financement national est l’argent qu’un pays lève grâce à ses propres impôts et revenus.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "Quelle part du PIB le Cadre d’Incheon suggère-t-il pour l’éducation ?", "options": ["0,5 à 1 %", "20 à 30 %", "50 à 60 %", "4 à 6 %"], "answer": 3, "explain": "Le Cadre d’Incheon suggère 4 à 6 % du PIB et/ou 15 à 20 % des dépenses publiques.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "Quelle part des dépenses publiques le Cadre d’Incheon suggère-t-il pour l’éducation ?", "options": ["15 à 20 %", "1 à 2 %", "40 à 50 %", "90 à 100 %"], "answer": 0, "explain": "Incheon suggère 15 à 20 % de l’ensemble des dépenses publiques d’éducation.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "Qu’est-ce qu’un déficit de financement de l’éducation ?", "options": ["De l’argent mis de côté pour les vacances en famille et les sorties d’été", "L’écart entre l’argent nécessaire et l’argent disponible", "La distance entre deux bâtiments scolaires de la ville", "De l’argent qui n’a aucune utilité réelle dans une école aujourd’hui"], "answer": 1, "explain": "Un déficit de financement est le montant qui manque encore pour financer les objectifs éducatifs.", "src": "UNESCO"}, {"ch": 7, "q": "Pourquoi les écoles des zones pauvres ont-elles souvent moins d’argent ?", "options": ["Elles ont trop d’élèves", "Elles choisissent de ne pas recevoir d’argent", "Moins de recettes fiscales et un financement inégal", "Elles n’ont pas besoin de livres"], "answer": 2, "explain": "Un financement inégal peut priver les zones pauvres de ressources.", "src": "UNESCO GEM Report 2026"}, {"ch": 7, "q": "Qu’est-ce que le financement par élève ?", "options": ["De l’argent versé pour la voiture de chaque professeur", "De l’argent versé pour chaque bus scolaire", "De l’argent versé pour chaque trophée sportif", "De l’argent versé aux écoles pour chaque élève"], "answer": 3, "explain": "Le financement par élève rémunère les écoles en fonction du nombre d’élèves.", "src": "UNESCO"}, {"ch": 8, "q": "Quels objectifs ont remplacé les Objectifs du Millénaire pour le développement ?", "options": ["Les Objectifs de développement durable", "Les objectifs olympiques", "Les objectifs commerciaux", "Les objectifs spatiaux"], "answer": 0, "explain": "Les ODD (objectifs mondiaux) ont remplacé les OMD en 2015.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "En quelle année le Cadre d’action Éducation 2030 a-t-il été adopté ?", "options": ["1990", "2015", "2000", "2030"], "answer": 1, "explain": "Le Cadre d’action Éducation 2030 a été adopté en 2015.", "src": "Incheon Framework for Action (2015)"}, {"ch": 8, "q": "Que disait la déclaration de 1948 sur l’éducation ?", "options": ["Les écoles doivent fermer", "L’éducation est réservée aux adultes", "Chacun a droit à l’éducation", "L’éducation est un luxe"], "answer": 2, "explain": "La Déclaration universelle des droits de l’homme affirme que l’éducation est un droit humain.", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "Que dit l’article 26 de la Déclaration universelle au sujet de l’enseignement primaire ?", "options": ["Il doit être coûteux", "Il doit être facultatif pour tous", "Il doit être réservé aux garçons", "Il doit être gratuit et obligatoire"], "answer": 3, "explain": "L’article 26 affirme que l’enseignement élémentaire doit être obligatoire et gratuit.", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "Que s’est-il passé au Forum mondial sur l’éducation de 2015 à Incheon ?", "options": ["Les pays ont convenu d’objectifs éducatifs pour 2030", "Les pays ont fermé toutes les écoles", "Les pays ont choisi un nouveau sport", "Les pays ont mis fin aux programmes d’alphabétisation"], "answer": 0, "explain": "La Déclaration d’Incheon a fixé les objectifs éducatifs pour 2030.", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "Que réclamait la conférence de Jomtien de 1990 ?", "options": ["L’éducation seulement pour les riches", "L’éducation pour tous", "L’éducation seulement en anglais", "Des écoles sans professeurs"], "answer": 1, "explain": "La conférence de Jomtien de 1990 a réclamé l’éducation pour tous.", "src": "UNESCO"}, {"ch": 9, "q": "Pourquoi la petite enfance est-elle liée aux apprentissages ultérieurs ?", "options": ["Les premières années n’ont aucun lien", "Seul l’apprentissage des adultes compte", "Les compétences précoces soutiennent la réussite scolaire future", "Les apprentissages ultérieurs n’ont aucun rapport"], "answer": 2, "explain": "De solides bases précoces facilitent les apprentissages futurs.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Qu’est-ce que la préparation à l’école ?", "options": ["Être prêt à quitter l’école", "Être assez grand pour les bureaux", "Savoir conduire", "Être prêt à apprendre au début de l’école"], "answer": 3, "explain": "La préparation à l’école signifie que les enfants ont les compétences et la santé pour commencer l’école.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Quel est le rôle du jeu dans l’apprentissage précoce ?", "options": ["Il développe la pensée, le langage et les compétences sociales", "Il n’a aucun rôle", "Il remplace tous les apprentissages pour toujours", "Il fait seulement perdre du temps"], "answer": 0, "explain": "Le jeu aide les enfants à développer la pensée, le langage et les compétences sociales.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Pourquoi les bébés ont-ils besoin de soins attentifs ?", "options": ["Cela les gâte", "Cela aide leur cerveau et leurs émotions à se développer", "Ce n’est pas nécessaire", "Cela les fait seulement dormir"], "answer": 1, "explain": "Des soins attentifs soutiennent un développement sain du cerveau et des émotions.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Que sont les mille premiers jours ?", "options": ["Le premier jour d’école", "La première semaine de vacances", "La période de la grossesse jusqu’à deux ans", "La première année d’université"], "answer": 2, "explain": "Les mille premiers jours, de la grossesse à deux ans, sont très importants pour le développement.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Quelle activité de la petite enfance favorise la croissance du cerveau ?", "options": ["Le silence total", "Seulement les écrans en continu", "Les laisser seuls pendant des heures", "Parler et lire avec les enfants"], "answer": 3, "explain": "Parler et lire avec les enfants favorisent le langage et la croissance du cerveau.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "Qu’est-ce que la post-alphabétisation ?", "options": ["Un apprentissage qui s’appuie sur l’alphabétisation de base", "Lire seulement des bandes dessinées", "L’alphabétisation réservée aux professeurs", "Lire seulement des magazines"], "answer": 0, "explain": "La post-alphabétisation aide les personnes à conserver et à développer leurs compétences de base en lecture et en écriture.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "Qu’est-ce que l’alphabétisation pour tous ?", "options": ["L’alphabétisation seulement pour les enfants", "Des possibilités d’alphabétisation pour chacun", "L’alphabétisation seulement pour les riches", "L’alphabétisation dans une seule langue"], "answer": 1, "explain": "L’alphabétisation pour tous vise à donner à chacun la chance de lire et d’écrire.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "Pourquoi les programmes d’alphabétisation multilingue sont-ils utiles ?", "options": ["Ils empêchent d’apprendre une deuxième langue", "Ils suppriment le besoin de livres", "Ils aident les apprenants à lire d’abord dans leur propre langue", "Ils ne fonctionnent que dans le sport"], "answer": 2, "explain": "Apprendre à lire dans une langue que l’enfant comprend favorise les apprentissages ultérieurs.", "src": "UNESCO, International Mother Language Day"}, {"ch": 10, "q": "Quel est le lien entre alphabétisation et santé ?", "options": ["La lecture rend malade", "Il n’existe aucun lien", "La santé dépend seulement du sport", "La lecture aide à comprendre les conseils de santé"], "answer": 3, "explain": "L’alphabétisation aide à lire les notices de médicaments et les consignes de santé.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Que vise une campagne d’alphabétisation ?", "options": ["Enseigner la lecture et l’écriture à un grand nombre de personnes", "Vendre plus de journaux aux familles occupées chaque semaine", "Empêcher les gens de lire des livres et des magazines", "Construire davantage de routes et de ponts dans le pays"], "answer": 0, "explain": "Une campagne d’alphabétisation œuvre à réduire l’illettrisme dans les communautés.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "Quelle compétence est à la base de l’alphabétisation ?", "options": ["Jongler avec des balles", "Reconnaître les lettres et leurs sons", "Conduire un bus", "Cuisiner du riz"], "answer": 1, "explain": "Reconnaître les lettres et leurs sons est une compétence de base de l’alphabétisation.", "src": "UNESCO GEM Report 2026"}, {"ch": 11, "q": "Que garantit la cible 4.5 pour les groupes vulnérables ?", "options": ["Un accès seulement pour les meilleurs élèves", "Un accès seulement pour les familles riches", "Un accès égal à l’éducation", "Un accès seulement dans les grandes villes"], "answer": 2, "explain": "La cible 4.5 garantit un accès égal pour les groupes vulnérables.", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "Qu’est-ce qu’un plan d’éducation individualisé pour un élève ?", "options": ["Un plan pour les vacances", "Un plan pour éviter les cours", "Un plan pour transférer les élèves dans une autre école", "Un plan adapté aux besoins d’un apprenant"], "answer": 3, "explain": "Les plans d’éducation individualisés aident les professeurs à répondre aux besoins spécifiques d’un élève.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Qu’est-ce qu’un aménagement raisonnable exige des écoles ?", "options": ["Des adaptations qui aident les apprenants à participer", "Ignorer les besoins des apprenants", "Facturer des frais supplémentaires", "Supprimer tout soutien"], "answer": 0, "explain": "Les écoles doivent faire des aménagements raisonnables pour que les apprenants handicapés puissent participer.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Pourquoi les supports accessibles sont-ils importants ?", "options": ["Ils rendent l’apprentissage plus difficile pour tous", "Ils permettent à tous les apprenants d’utiliser le même contenu", "Ils sont seulement pour les professeurs", "Ils remplacent les professeurs"], "answer": 1, "explain": "Les supports accessibles, comme les gros caractères ou le braille, aident les apprenants à suivre les cours.", "src": "UN CRPD (2006), Article 24"}], "7": [{"ch": 0, "q": "Quel Objectif mondial porte sur la lutte contre les changements climatiques ?", "options": ["Objectif 13", "Objectif 3", "Objectif 14", "Objectif 10"], "answer": 0, "explain": "L’Objectif 13 porte sur la lutte contre les changements climatiques.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Quelle cible vise à éliminer les inégalités entre les genres dans l’éducation ?", "options": ["La cible 4.1", "La cible 4.5", "La cible 4.4", "La cible 4.a"], "answer": 1, "explain": "La cible 4.5 vise à éliminer les inégalités entre les genres et à garantir un accès égal.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Pourquoi est-il important de mesurer les résultats d’apprentissage ?", "options": ["Il compte seulement le nombre de bâtiments scolaires de la ville", "Il fixe le prix des livres scolaires dans chaque magasin", "Il montre ce que les enfants apprennent réellement, et pas seulement les inscriptions", "Il mesure la taille et le poids de chaque élève"], "answer": 2, "explain": "Suivre les résultats d’apprentissage montre si les enfants apprennent vraiment.", "src": "UNESCO GEM Report 2026"}, {"ch": 0, "q": "À quoi servent les indicateurs de l’ODD 4 ?", "options": ["Choisir les couleurs de l’école", "Classer les professeurs par taille", "Fixer les dates des vacances", "Mesurer les progrès de chaque cible"], "answer": 3, "explain": "Les indicateurs mesurent les progrès vers chaque cible.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Pourquoi l’Objectif 4 est-il lié aux autres Objectifs mondiaux ?", "options": ["L’éducation soutient la santé, l’emploi et l’égalité", "L’éducation n’a aucun lien avec les autres objectifs", "L’éducation ne compte que pour le sport", "L’éducation ne concerne que les villes"], "answer": 0, "explain": "L’éducation favorise les progrès dans de nombreux objectifs, comme la santé, le travail et l’égalité des genres.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Quelle cible vise la maîtrise de la lecture et du calcul pour les jeunes et les adultes ?", "options": ["La cible 4.1", "La cible 4.6", "La cible 4.5", "La cible 4.c"], "answer": 1, "explain": "La cible 4.6 vise la maîtrise de la lecture et du calcul pour tous les jeunes et une part importante des adultes.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Que mesure l’indicateur 4.1.1 ?", "options": ["Le nombre de bus scolaires qui circulent sur chaque grand axe", "Le prix moyen des uniformes scolaires dans chaque ville", "Les enfants qui atteignent le niveau minimal de maîtrise en lecture et en mathématiques", "La hauteur moyenne de chaque salle de classe de l’école"], "answer": 2, "explain": "L’indicateur 4.1.1 mesure la part des enfants qui atteignent les niveaux minimaux de maîtrise.", "src": "UN SDG Report 2026"}, {"ch": 1, "q": "Qu’est-ce que la fracture numérique ?", "options": ["Un écart entre deux salles de classe d’un même grand bâtiment scolaire", "Une pause entre deux longs cours pendant une journée scolaire chargée", "Une séparation entre deux langues parlées uniquement à la maison", "L’écart entre les personnes qui ont accès à internet et celles qui n’y ont pas accès"], "answer": 3, "explain": "La fracture numérique désigne l’écart d’accès aux appareils et à internet.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Pourquoi l’enseignement à distance peut-il aider certains apprenants ?", "options": ["Il atteint les apprenants des zones isolées", "Il remplace tous les professeurs", "Il met fin à l’apprentissage", "Il ne concerne que les adultes"], "answer": 0, "explain": "L’enseignement à distance et en ligne peut toucher les personnes qui vivent loin des écoles.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Qu’est-ce qu’un centre d’apprentissage dans une communauté isolée ?", "options": ["Un centre commercial avec de nombreux magasins et cafés", "Un espace où les apprenants peuvent étudier avec un soutien", "Un service hospitalier où les patients se reposent et se rétablissent", "Un stade de sport pour de grands matchs de football"], "answer": 1, "explain": "Les centres d’apprentissage offrent aux apprenants isolés un lieu pour étudier et être aidés.", "src": "UNESCO"}, {"ch": 1, "q": "Qu’est-ce que la cartographie scolaire ?", "options": ["Dessiner des cartes d’itinéraires de vacances pour des voyages en famille à l’étranger", "Cartographier les terrains de sport utilisés pour les matchs scolaires", "Repérer où des écoles sont nécessaires et qui peut y accéder", "Concevoir de nouveaux logos et affiches pour chaque école"], "answer": 2, "explain": "La cartographie scolaire aide les gouvernements à planifier où construire de nouvelles écoles et organiser les transports.", "src": "UNESCO"}, {"ch": 1, "q": "Quel est un obstacle courant à la scolarisation dans les villes ?", "options": ["Trop d’espaces verts", "Trop de bibliothèques", "Trop de professeurs", "Le coût élevé de la vie pour les familles pauvres"], "answer": 3, "explain": "Dans les villes, les familles pauvres peuvent avoir du mal à payer les transports et le coût de la vie.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Que signifie l’accès pour les apprenants en situation de handicap ?", "options": ["Pouvoir entrer dans les installations scolaires et les utiliser", "Pouvoir quitter l’école à tout moment", "Pouvoir sécher les cours", "Pouvoir éviter les examens"], "answer": 0, "explain": "L’accès signifie que les apprenants en situation de handicap peuvent entrer dans les espaces scolaires et utiliser les supports d’apprentissage.", "src": "UN CRPD (2006), Article 24"}, {"ch": 2, "q": "Qu’est-ce qu’un écart d’achèvement ?", "options": ["Un trou dans un mur de l’école qui doit être réparé d’urgence", "Une différence dans la fin de la scolarité entre des groupes", "Un espace entre deux tables dans une salle de classe bondée", "Un créneau vide dans l’emploi du temps chaque vendredi après-midi"], "answer": 1, "explain": "Un écart d’achèvement montre que certains groupes terminent l’école moins souvent que d’autres.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "Pourquoi les enfants issus de familles plus aisées terminent-ils plus souvent l’école ?", "options": ["Leurs enfants sont moins intelligents", "Leurs enfants ne passent jamais d’examens", "Leurs familles peuvent payer les coûts et les transports", "Leurs enfants évitent les devoirs"], "answer": 2, "explain": "Les revenus aident les familles à couvrir les coûts et les transports, ce qui rend l’achèvement plus probable.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "Que mesure le taux de survie jusqu’à la dernière année ?", "options": ["La part de ceux qui gagnent des courses", "La part de ceux qui possèdent un vélo", "La part de ceux qui parlent deux langues", "La part des enfants qui atteignent la dernière année"], "answer": 3, "explain": "Le taux de survie mesure le nombre d’élèves qui atteignent la dernière année d’un niveau.", "src": "UNESCO"}, {"ch": 2, "q": "Pourquoi le mariage précoce affecte-t-il l’achèvement scolaire ?", "options": ["Il peut mettre fin à la scolarité d’une fille", "Il améliore la fréquentation scolaire", "Il n’a aucun effet", "Il ne touche que les garçons"], "answer": 0, "explain": "Le mariage précoce met souvent fin à la scolarité des filles avant qu’elles ne terminent l’école.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 2, "q": "Qu’est-ce que la réintégration scolaire ?", "options": ["Entrer pour la première fois dans une école", "Revenir à l’école après l’avoir quittée", "Quitter l’école pour toujours", "Changer d’uniforme scolaire"], "answer": 1, "explain": "Les politiques de réintégration aident les jeunes à retourner à l’école après un abandon.", "src": "UNESCO"}, {"ch": 2, "q": "Qu’est-ce que la transition de l’école vers le travail ?", "options": ["Le changement de bâtiment scolaire", "Le changement de professeurs", "Le passage de l’école à l’emploi ou à la formation", "Un simple déménagement dans un autre pays"], "answer": 2, "explain": "La transition de l’école vers le travail est le passage de l’éducation à l’emploi ou à la formation.", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "Qu’est-ce que la perte d’acquis ?", "options": ["La perte de sa trousse dans le bus chaque matin", "L’oubli du mot de passe de l’ordinateur de l’école", "La défaite face à une école rivale lors d’un match de football", "La perte de compétences après une longue interruption des apprentissages"], "answer": 3, "explain": "La perte d’acquis signifie que les compétences s’estompent lorsque les écoles ferment ou que l’apprentissage est interrompu.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Qu’est-ce qui aide les élèves à rattraper une perte d’acquis ?", "options": ["Le soutien scolaire ciblé et les cours de rattrapage", "Moins d’enseignement", "La suppression de tous les examens", "Des vacances plus longues uniquement"], "answer": 0, "explain": "Un soutien ciblé aide les apprenants à rattraper ce qu’ils ont manqué.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Qu’est-ce que l’apprentissage par la maîtrise ?", "options": ["Les apprenants ne reprennent jamais un sujet", "Les apprenants passent à la suite seulement après avoir compris un sujet", "Les apprenants évitent tous les sujets difficiles", "Les apprenants se contentent de mémoriser les réponses"], "answer": 1, "explain": "L’apprentissage par la maîtrise garantit que les apprenants comprennent avant de passer à la suite.", "src": "UNESCO"}, {"ch": 3, "q": "Pourquoi la langue d’enseignement est-elle importante ?", "options": ["Elle n’a aucun effet", "Une seule langue devrait toujours être utilisée", "Les apprenants comprennent mieux les cours dans une langue qu’ils connaissent", "Elle ne compte que dans le sport"], "answer": 2, "explain": "Utiliser une langue que les apprenants comprennent favorise l’apprentissage.", "src": "UNESCO, International Mother Language Day"}, {"ch": 3, "q": "Qu’est-ce que l’enseignement bilingue ?", "options": ["Enseigner uniquement par le jeu", "Enseigner sans aucune langue", "Enseigner dans une seule langue pour la danse", "Enseigner dans deux langues"], "answer": 3, "explain": "L’enseignement bilingue utilise deux langues pour aider les apprenants à comprendre et à progresser.", "src": "UNESCO, International Mother Language Day"}, {"ch": 3, "q": "Qu’est-ce que la lecture critique ?", "options": ["Questionner et évaluer un texte", "Lire sans réfléchir", "Ne lire que le titre", "Ne regarder que les images"], "answer": 0, "explain": "La lecture critique cherche à savoir si le texte est exact, juste et bien argumenté.", "src": "UNESCO"}, {"ch": 4, "q": "Que signifie TIC dans l’éducation ?", "options": ["Association internationale de cuisine", "Technologies de l’information et de la communication", "Visite intéressante du campus", "Test important en classe"], "answer": 1, "explain": "TIC signifie technologies de l’information et de la communication.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Qu’est-ce que l’enseignement professionnel ?", "options": ["Un enseignement sans compétences pratiques ni formation sur le terrain", "Un enseignement réservé à ceux qui travaillent déjà comme professeurs", "Un enseignement qui prépare à des métiers ou à des emplois précis", "Un enseignement réservé aux étudiants qui vont à l’université"], "answer": 2, "explain": "L’enseignement professionnel développe des compétences pratiques pour des emplois précis.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Que signifie EFTP ?", "options": ["Examen vidéo des enseignants", "Outil visuel éducatif total", "Thème vidéo de l’enseignement supérieur", "Enseignement et formation techniques et professionnels"], "answer": 3, "explain": "EFTP signifie enseignement et formation techniques et professionnels.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Pourquoi enseigne-t-on la programmation dans certaines écoles ?", "options": ["Elle développe la résolution de problèmes et les compétences numériques", "Elle remplace toutes les autres matières", "Elle ne sert qu’à jouer", "Elle met fin à l’apprentissage"], "answer": 0, "explain": "La programmation enseigne la logique et des compétences numériques utiles dans de nombreux métiers.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Qu’est-ce que la citoyenneté numérique ?", "options": ["Utiliser la technologie pour nuire aux autres", "Utiliser la technologie de manière sûre, responsable et respectueuse", "Éviter toute technologie", "Utiliser la technologie uniquement pour jouer"], "answer": 1, "explain": "La citoyenneté numérique consiste à bien se comporter en ligne et à respecter les autres.", "src": "UNESCO"}, {"ch": 4, "q": "Qu’est-ce qu’une compétence émergente ?", "options": ["Une compétence qui n’est plus nécessaire", "Une compétence réservée aux langues anciennes", "Une compétence qui devient importante dans les nouveaux métiers", "Une compétence pour bien dormir"], "answer": 2, "explain": "Les compétences émergentes deviennent importantes à mesure que de nouveaux types de travail apparaissent.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Qu’est-ce que l’écart entre les genres dans les STIM ?", "options": ["Les filles étudient plus les mathématiques que les garçons dans presque tous les pays aujourd’hui", "Aucun écart n’existe dans les cours de sciences, nulle part", "Seuls les garçons ont le droit d’étudier les matières scientifiques à l’école", "Moins de filles que de garçons étudient les sciences, la technologie, l’ingénierie et les mathématiques"], "answer": 3, "explain": "De nombreux pays comptent moins de filles dans les matières STIM, ce qui limite leurs choix.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Pourquoi les enseignantes peuvent-elles compter dans certains endroits ?", "options": ["Elles peuvent servir de modèles et aider les filles à rester à l’école", "Elles ne sont nécessaires dans aucune école du monde", "Elles n’enseignent que le sport et les activités physiques en plein air", "Elles empêchent les enfants d’apprendre de nouvelles matières"], "answer": 0, "explain": "Les enseignantes peuvent encourager les filles et contribuer à créer des environnements sûrs.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Qu’est-ce qu’une école sensible au genre ?", "options": ["Une école réservée aux filles", "Une école qui répond aux besoins des filles et des garçons", "Une école qui ignore le genre", "Une école sans toilettes"], "answer": 1, "explain": "Les écoles sensibles au genre prévoient les différents besoins des filles et des garçons.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Que signifie marginalisé ?", "options": ["Placé au centre de l’attention", "Recevant automatiquement de l’argent supplémentaire", "Repoussé aux marges de la société et laissé de côté", "Autorisé à établir toutes les règles"], "answer": 2, "explain": "Les groupes marginalisés sont souvent exclus de l’éducation et des opportunités.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Pourquoi les locuteurs de langues minoritaires risquent-ils d’être laissés pour compte ?", "options": ["Ils sont toujours les meilleurs élèves", "Leur langue n’est jamais parlée", "Ils ne vont jamais à l’école", "Les écoles n’enseignent peut-être pas dans leur langue"], "answer": 3, "explain": "Quand les cours utilisent une langue que les enfants ne parlent pas, beaucoup prennent du retard.", "src": "UNESCO, International Mother Language Day"}, {"ch": 5, "q": "Qu’est-ce que l’action positive dans l’éducation ?", "options": ["Un soutien supplémentaire aux groupes confrontés à un désavantage", "Sanctionner les groupes qui réussissent", "Ignorer toutes les différences", "Fermer les écoles pour certains groupes"], "answer": 0, "explain": "L’action positive apporte un soutien supplémentaire pour aider les groupes défavorisés à rattraper leur retard.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Que signifie le statut socio-économique ?", "options": ["Un type d’examen scolaire", "La position sociale et économique d’une personne", "La couleur d’un cartable", "Un nombre de victoires sportives"], "answer": 1, "explain": "Le statut socio-économique décrit les revenus, le niveau d’études et la position sociale d’une famille.", "src": "UNESCO GEM Report 2026"}, {"ch": 6, "q": "Qu’est-ce qu’un déficit d’enseignants ?", "options": ["Des enseignants supplémentaires qui ne font rien", "Des enseignants sans cours", "Le nombre d’enseignants supplémentaires nécessaires pour répondre à la demande", "Des enseignants qui ne quittent jamais l’école"], "answer": 2, "explain": "Un déficit d’enseignants correspond au nombre d’enseignants supplémentaires nécessaires pour atteindre les objectifs éducatifs.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Pourquoi la disponibilité des enseignants pose-t-elle problème dans de nombreux pays ?", "options": ["Trop de personnes veulent enseigner", "Les enseignants ne sont jamais nécessaires", "Les enseignants ont uniquement trop d’élèves", "Trop peu de personnes se forment ou restent enseignants"], "answer": 3, "explain": "Les pénuries viennent du petit nombre de candidats à la formation, des salaires bas et d’un fort taux de rotation.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce que le statut des enseignants ?", "options": ["La manière dont les enseignants sont valorisés dans la société", "La taille d’un enseignant", "La voiture d’un enseignant", "Le cartable d’un enseignant"], "answer": 0, "explain": "Le statut des enseignants influence le choix de ce métier et la décision d’y rester.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce qu’un enseignant dans une zone de crise ?", "options": ["Un enseignant qui ne travaille que dans les villes", "Un enseignant qui travaille là où un conflit ou une catastrophe a frappé", "Un enseignant qui n’enseigne jamais", "Un enseignant qui ne travaille que pendant les vacances"], "answer": 1, "explain": "Les enseignants des zones de crise travaillent dans des conditions difficiles pour que les enfants continuent d’apprendre.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Pourquoi certains enseignants quittent-ils la profession ?", "options": ["Des salaires trop élevés et trop de vacances payées", "Trop peu de travail et trop de jours libres", "Des salaires bas, des charges de travail lourdes ou un soutien insuffisant", "Trop de prix et trop d’éloges"], "answer": 2, "explain": "Des salaires bas et des charges de travail lourdes poussent certains enseignants à quitter la profession.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce que la charge de travail d’un enseignant ?", "options": ["Le poids du cartable d’un enseignant", "Le nombre de vacances des enseignants", "Le prix de la voiture d’un enseignant", "La quantité de travail qu’un enseignant doit accomplir"], "answer": 3, "explain": "La charge de travail comprend l’enseignement, la préparation, la correction et d’autres tâches.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "À quoi sert le taux de pauvreté en apprentissage ?", "options": ["Suivre les enfants qui ne savent pas lire à dix ans", "Suivre les bâtiments scolaires", "Suivre le prix des stylos", "Suivre les vacances des enseignants"], "answer": 0, "explain": "Le taux de pauvreté en apprentissage indique la part des enfants incapables de lire un texte simple à dix ans.", "src": "World Bank, learning poverty"}, {"ch": 7, "q": "Pourquoi les dépenses publiques d’éducation sont-elles importantes ?", "options": ["Elles n’ont aucune utilité", "Elles financent les enseignants, les bâtiments et le matériel", "Elles ne financent que les vacances", "Elles n’achètent que du matériel de sport"], "answer": 1, "explain": "L’argent public fait fonctionner les écoles et rend l’apprentissage accessible à tous.", "src": "UNESCO"}, {"ch": 7, "q": "Qu’est-ce que l’exécution budgétaire dans l’éducation ?", "options": ["Annuler tous les cours", "Suspendre toutes les sorties scolaires", "Dépenser l’argent comme prévu", "Vendre les bâtiments scolaires"], "answer": 2, "explain": "L’exécution budgétaire vérifie si l’argent prévu pour l’éducation est réellement dépensé.", "src": "UNESCO"}, {"ch": 7, "q": "Qu’est-ce que le partage des coûts dans l’éducation ?", "options": ["Des écoles qui paient les familles", "Des enseignants qui paient les élèves", "Des élèves qui paient les enseignants", "Des familles qui paient une partie du coût de l’école"], "answer": 3, "explain": "Le partage des coûts signifie que les familles contribuent, ce qui peut limiter l’accès des enfants les plus pauvres.", "src": "UNESCO"}, {"ch": 7, "q": "Qu’est-ce qu’une taxe pour l’éducation ?", "options": ["Un impôt destiné à financer les écoles", "Des frais uniquement pour passer des examens", "Un impôt uniquement sur les livres scolaires", "Une amende pour absence à l’école"], "answer": 0, "explain": "Certains pays lèvent une taxe pour l’éducation afin de financer les écoles.", "src": "UNESCO"}, {"ch": 7, "q": "Pourquoi les écoles ont-elles besoin de réparations régulières ?", "options": ["Les bâtiments neufs ont toujours besoin de réparations", "Les vieux bâtiments peuvent devenir dangereux", "Les réparations agrandissent les écoles", "Les réparations empêchent les enfants d’apprendre"], "answer": 1, "explain": "Des réparations régulières maintiennent les bâtiments sûrs et adaptés à l’apprentissage.", "src": "UNESCO"}, {"ch": 7, "q": "Qu’est-ce que le rapport qualité-prix des dépenses d’éducation ?", "options": ["Dépenser le maximum d’argent chaque année", "Dépenser de l’argent uniquement en matériel de sport", "Obtenir de bons résultats d’apprentissage pour l’argent dépensé", "Ne dépenser aucun argent chaque année"], "answer": 2, "explain": "Le rapport qualité-prix signifie dépenser avec discernement pour améliorer l’apprentissage.", "src": "UNESCO"}, {"ch": 8, "q": "Quelle conférence a adopté le Programme 2030 ?", "options": ["Une réunion régionale tenue à Tokyo, en 2005", "Une réunion au Caire sur la population, en 1994", "Une conférence à Lima sur l’agriculture, en 2014", "Le sommet de l’ONU à New York, en 2015"], "answer": 3, "explain": "Les dirigeants mondiaux ont adopté le Programme 2030 lors d’un sommet de l’ONU à New York en 2015.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "Quand s’est tenue la Conférence mondiale sur l’éducation pour tous de Jomtien ?", "options": ["1990", "1975", "2005", "2020"], "answer": 0, "explain": "La conférence de Jomtien s’est tenue en 1990.", "src": "UNESCO"}, {"ch": 8, "q": "En quelle année s’est tenu le Forum mondial sur l’éducation de Dakar ?", "options": ["1995", "2000", "2010", "2015"], "answer": 1, "explain": "Le Forum mondial sur l’éducation de Dakar s’est tenu en 2000.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "Sur quoi portait la déclaration de Jomtien de 1990 ?", "options": ["Uniquement l’apprentissage universitaire", "Uniquement le sport", "Répondre aux besoins éducatifs fondamentaux de tous", "Uniquement les examens"], "answer": 2, "explain": "La déclaration de 1990 visait à répondre aux besoins éducatifs fondamentaux de toutes les personnes.", "src": "UNESCO"}, {"ch": 8, "q": "Sur quoi portaient les OMD en matière d’éducation ?", "options": ["Des voitures gratuites", "Uniquement des bourses universitaires", "Des championnats sportifs", "L’enseignement primaire universel"], "answer": 3, "explain": "L’OMD 2 portait sur l’enseignement primaire universel.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 8, "q": "À quoi sert un rapport mondial sur l’éducation ?", "options": ["Suivre les progrès et partager des données probantes", "Fermer des écoles", "Choisir les vacances", "Vendre des manuels scolaires"], "answer": 0, "explain": "Les rapports mondiaux suivent les progrès et partagent des données probantes pour guider les politiques.", "src": "UNESCO GEM Report 2026"}, {"ch": 9, "q": "Que couvre le développement de l’enfant pendant les premières années ?", "options": ["La seule croissance physique", "La croissance du corps, de l’esprit et des compétences sociales", "La seule croissance de l’argent", "La seule croissance de la vitesse"], "answer": 1, "explain": "Le développement de l’enfant couvre la croissance physique, la pensée, le langage et les compétences sociales.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Qu’est-ce que le stress toxique dans la petite enfance ?", "options": ["Un type d’aliment sain que les enfants mangent chaque jour", "Un jeu amusant auquel les enfants jouent souvent dans le parc", "Un stress intense et durable qui peut nuire au développement", "Une matière scolaire enseignée aux jeunes enfants"], "answer": 2, "explain": "Le stress toxique peut nuire au cerveau en développement lorsqu’il est prolongé et sans soutien.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Pourquoi les programmes de la petite enfance aident-ils les enfants défavorisés ?", "options": ["Ils créent des écarts", "Ils ne sont réservés qu’aux enfants riches", "Ils remplacent les familles", "Ils réduisent les écarts avant le début de l’école"], "answer": 3, "explain": "Les programmes précoces peuvent égaliser le départ des enfants issus de foyers défavorisés.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Qu’apporte le soutien à la parentalité à l’apprentissage précoce ?", "options": ["Il aide les parents à soutenir l’apprentissage de leurs enfants", "Il remplace entièrement les parents dans la vie de leurs enfants", "Il empêche les enfants d’apprendre à la maison et à l’école", "Il ne sert qu’à acheter des jouets pour les enfants"], "answer": 0, "explain": "Le soutien à la parentalité donne aux adultes des idées pour parler, jouer et prendre soin des jeunes enfants.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Que comprend un environnement d’apprentissage à la maison ?", "options": ["Uniquement la télévision", "Des livres, la conversation et le jeu à la maison", "Uniquement le silence", "Uniquement les devoirs"], "answer": 1, "explain": "Un environnement d’apprentissage familial favorable encourage la lecture, la conversation et le jeu.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Pourquoi la petite enfance est-elle importante pour les filles ?", "options": ["Elle n’est pas nécessaire pour les filles", "Elle ne compte qu’après l’école", "Elle les aide à commencer l’école prêtes à apprendre", "Elle ne compte que pour les garçons"], "answer": 2, "explain": "Une bonne prise en charge précoce soutient la santé, l’apprentissage et la confiance des filles.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 10, "q": "Qu’est-ce que la littératie familiale ?", "options": ["La littératie réservée aux grands-parents", "La lecture sans les enfants", "L’écriture réservée aux personnes âgées", "Des parents et des enfants qui apprennent à lire ensemble"], "answer": 3, "explain": "La littératie familiale aide parents et enfants à développer ensemble leurs compétences en lecture.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Qu’est-ce que l’écart de lecture entre les pays ?", "options": ["Les différences de niveau de lecture entre les pays", "L’espace entre les livres sur les étagères", "L’écart entre les tables de classe", "La distance entre deux écoles"], "answer": 0, "explain": "L’écart de lecture montre à quel point les niveaux de lecture diffèrent d’un endroit à l’autre.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "Qu’est-ce que la fluidité à l’écrit ?", "options": ["Écrire sans mots", "Écrire clairement et rapidement", "Écrire uniquement en majuscules", "Écrire uniquement sur ordinateur"], "answer": 1, "explain": "La fluidité à l’écrit consiste à écrire assez aisément pour exprimer ses idées.", "src": "UNESCO"}, {"ch": 10, "q": "Qu’est-ce que le langage oral ?", "options": ["Uniquement le langage écrit", "Le langage utilisé uniquement dans les livres", "Le langage parlé", "Le langage utilisé uniquement par les animaux"], "answer": 2, "explain": "Le langage oral est la langue parlée que les enfants apprennent en premier.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "Pourquoi le langage oral est-il important avant la lecture ?", "options": ["Il n’a aucun lien avec la lecture", "Il empêche les enfants de lire", "Il ne sert qu’à chanter", "Il construit le vocabulaire qui soutient la lecture"], "answer": 3, "explain": "Un langage oral solide aide les enfants à comprendre ce qu’ils lisent.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "Quel est l’objectif de la Journée internationale de l’alphabétisation ?", "options": ["Sensibiliser à l’alphabétisation et à ses bienfaits", "Fermer toutes les bibliothèques du pays", "Vendre davantage de livres dans les magasins du pays", "Arrêter tous les cours de lecture à l’école primaire"], "answer": 0, "explain": "La Journée internationale de l’alphabétisation sensibilise à l’alphabétisation et à ce qu’elle rend possible.", "src": "UNESCO, International Literacy Day"}, {"ch": 11, "q": "Que demande l’éducation inclusive aux enseignants ?", "options": ["Enseigner uniquement aux meilleurs élèves", "Adapter les cours aux différents apprenants", "Ignorer les apprenants qui ont besoin d’aide", "Refuser toute formation supplémentaire"], "answer": 1, "explain": "L’enseignement inclusif adapte les méthodes pour que chaque apprenant puisse participer.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Qu’est-ce que la conception universelle de l’apprentissage ?", "options": ["Une conception de bâtiments scolaires sans aucune salle de classe", "Un enseignement qui n’utilise qu’une seule voie pour tous les apprenants", "Un enseignement conçu pour convenir à de nombreux types d’apprenants", "Un type d’uniforme scolaire porté chaque jour par tous les élèves"], "answer": 2, "explain": "La conception universelle de l’apprentissage propose plusieurs façons d’apprendre et de montrer sa compréhension.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Pourquoi les apprenants en situation de handicap ont-ils besoin d’aménagements raisonnables ?", "options": ["Pour échapper au travail", "Pour éviter les examens", "Pour partir en vacances", "Pour participer aux cours sur un pied d’égalité"], "answer": 3, "explain": "Les aménagements permettent aux apprenants en situation de handicap de participer sur un pied d’égalité.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Que fait un interprète en langue des signes en classe ?", "options": ["Il traduit entre la langue des signes et la langue parlée", "Il enseigne la danse et la musique à toute la classe", "Il vend des livres et des fournitures aux élèves", "Il conduit le bus scolaire sur le trajet du matin"], "answer": 0, "explain": "Les interprètes aident les apprenants sourds à suivre les cours.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "À quoi aide le braille aux apprenants ?", "options": ["Écouter de la musique", "Lire avec le toucher", "Nager plus vite", "Grandir davantage"], "answer": 1, "explain": "Le braille permet aux personnes aveugles de lire en touchant des points en relief.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Pourquoi l’inclusion profite-t-elle à tous dans une école ?", "options": ["Elle rend les classes plus petites sans raison", "Elle réduit l’apprentissage", "Elle développe la compréhension et le respect", "Elle empêche les amitiés"], "answer": 2, "explain": "Les classes inclusives enseignent le respect et la compréhension entre tous les apprenants.", "src": "UN CRPD (2006), Article 24"}], "8": [{"ch": 0, "q": "Combien de cibles de l’ODD 4 concernent les moyens de mise en œuvre ?", "options": ["Trois", "Sept", "Dix", "Quatre"], "answer": 0, "explain": "Les cibles 4.a à 4.c sont les trois moyens de mise en œuvre.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "De quoi traite la cible 4.c ?", "options": ["Construire de nouveaux terrains de sport", "Accroître le nombre d’enseignants qualifiés", "Donner des livres gratuits aux adultes", "Réduire la taille des écoles"], "answer": 1, "explain": "La cible 4.c appelle à davantage d’enseignants qualifiés, y compris par la formation.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Quelle cible porte sur le développement durable et la citoyenneté mondiale ?", "options": ["La cible 4.1", "La cible 4.2", "La cible 4.7", "La cible 4.b"], "answer": 2, "explain": "La cible 4.7 couvre les connaissances pour le développement durable et la citoyenneté mondiale.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Sur quoi porte un indicateur de maîtrise ?", "options": ["Combien de bâtiments possède une école", "Combien de jours de vacances il y a par an", "Quelle est la taille des apprenants", "Savoir si les apprenants atteignent un niveau fixé dans des compétences clés"], "answer": 3, "explain": "Les indicateurs de maîtrise vérifient si les apprenants atteignent un niveau fixé dans des compétences comme la lecture et les mathématiques.", "src": "UN SDG Report 2026"}, {"ch": 0, "q": "Que signifie ventiler les données par sexe, âge et handicap ?", "options": ["Découper les données selon chacun de ces groupes", "Garder les données secrètes", "Ne collecter des données qu’auprès des hommes", "Ne collecter des données que sur les bâtiments"], "answer": 0, "explain": "La ventilation montre si les progrès touchent chaque groupe.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Quel Objectif porte sur la réduction des inégalités ?", "options": ["Objectif 6", "Objectif 10", "Objectif 13", "Objectif 15"], "answer": 1, "explain": "L’Objectif 10 porte sur la réduction des inégalités.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Qu’est-ce que le taux de non-scolarisation ?", "options": ["La part des élèves qui sautent le déjeuner", "La part des écoles sans toit", "La part des enfants d’âge scolaire qui ne sont pas à l’école", "La part des enseignants en congé"], "answer": 2, "explain": "Le taux de non-scolarisation mesure les enfants d’âge scolaire qui ne sont pas inscrits.", "src": "UNESCO"}, {"ch": 1, "q": "Qu’est-ce qui rend une école accessible en termes de distance ?", "options": ["Elle est loin de toutes les habitations", "On ne peut y accéder qu’en avion", "Elle est fermée en semaine", "Elle se trouve à une distance sûre du domicile des enfants"], "answer": 3, "explain": "L’accessibilité signifie que les enfants peuvent rejoindre l’école en toute sécurité et régulièrement.", "src": "UNESCO"}, {"ch": 1, "q": "Quel coût est souvent caché pour les familles pauvres ?", "options": ["Le manque à gagner lié au travail des enfants", "Les cahiers gratuits", "Les repas scolaires gratuits", "Le transport gratuit"], "answer": 0, "explain": "Les familles pauvres peuvent perdre des revenus lorsque les enfants vont à l’école au lieu de travailler.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Qu’est-ce que le défi du « dernier kilomètre » en éducation ?", "options": ["Courir la course la plus longue", "Atteindre les enfants les plus isolés", "Passer le dernier examen", "Fermer la dernière école"], "answer": 1, "explain": "Les défis du dernier kilomètre visent à atteindre les enfants les plus difficiles à joindre.", "src": "UNESCO"}, {"ch": 1, "q": "Pourquoi les gouvernements suivent-ils les données d’inscription ?", "options": ["Pour choisir les couleurs de l’école", "Pour classer les élèves selon leur taille", "Pour planifier les enseignants, les bâtiments et les places", "Pour choisir les dates des vacances"], "answer": 2, "explain": "Les données d’inscription aident les gouvernements à planifier les enseignants, les salles de classe et les transports.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "Que mesure un taux de transition ?", "options": ["La vitesse des bus scolaires sur la route principale", "Le nombre de sonneries d’école en une journée entière", "Le prix des cahiers et des stylos vendus à la cantine", "La part des élèves qui passent d’un niveau au suivant"], "answer": 3, "explain": "Les taux de transition indiquent combien d’élèves accèdent au niveau suivant.", "src": "UNESCO"}, {"ch": 2, "q": "Pourquoi certains élèves n’accèdent-ils pas au secondaire ?", "options": ["Les coûts, la distance et des acquis faibles au primaire", "Le secondaire est toujours gratuit", "Le secondaire n’a aucune règle d’admission", "Les élèves sont trop grands"], "answer": 0, "explain": "Les coûts, la distance et les lacunes des acquis du primaire peuvent empêcher les élèves de passer au niveau supérieur.", "src": "UNESCO"}, {"ch": 2, "q": "Que signifie l’achèvement du second cycle du secondaire ?", "options": ["Terminer la première année de maternelle", "Terminer la dernière étape du secondaire", "Terminer un cours de sport", "Terminer un camp de vacances"], "answer": 1, "explain": "L’achèvement du second cycle du secondaire signifie terminer la dernière étape du secondaire.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Quel groupe risque le plus de cumuler plusieurs obstacles à l’achèvement ?", "options": ["Les garçons de familles aisées et urbaines", "Les enfants sans aucun obstacle", "Les filles de familles pauvres et rurales en situation de handicap", "Les adultes uniquement"], "answer": 2, "explain": "Des désavantages qui se cumulent rendent l’achèvement plus difficile pour certains apprenants.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Qu’est-ce qu’une voie d’apprentissage alternative ?", "options": ["Un chemin vers un diplôme sans aucun examen écrit", "Un chemin réservé aux seuls enseignants qualifiés", "Un chemin qui empêche les apprenants de terminer leurs études", "Un chemin vers le même diplôme par une autre voie"], "answer": 3, "explain": "Les voies alternatives permettent aux apprenants d’obtenir des diplômes de manière souple.", "src": "UNESCO"}, {"ch": 2, "q": "Qu’est-ce qu’un système d’alerte précoce dans les écoles ?", "options": ["Repérer les apprenants à risque de décrochage pour aider tôt", "Prévenir les élèves des examens finaux de fin d’année", "Déclencher des alarmes bruyantes à l’heure du déjeuner pour rappeler les élèves", "Faire sonner la cloche de l’école plus fort et plus longtemps pour les assemblées"], "answer": 0, "explain": "Les systèmes d’alerte précoce signalent les problèmes d’assiduité et d’apprentissage pour que les écoles puissent agir.", "src": "UNESCO"}, {"ch": 3, "q": "Qu’est-ce qu’une évaluation internationale des acquis ?", "options": ["Une compétition sportive scolaire", "Un test qui compare les apprentissages entre pays", "Un test d’embauche des enseignants", "Un plan budgétaire du gouvernement"], "answer": 1, "explain": "Les évaluations internationales comme PISA, TIMSS et PIRLS comparent les apprentissages entre pays.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Qu’est-ce que PISA ?", "options": ["Un réseau de bus scolaires pour les enfants des zones rurales", "Un type d’uniforme scolaire porté par les élèves de la ville", "Un test des compétences des élèves de 15 ans en lecture, mathématiques et sciences", "Un tournoi sportif mondial pour jeunes athlètes chaque année"], "answer": 2, "explain": "PISA est un test de l’OCDE auprès des élèves de 15 ans en lecture, mathématiques et sciences.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Pourquoi les évaluations des acquis doivent-elles être soigneusement conçues ?", "options": ["Pour qu’aucun test ne soit jamais nécessaire", "Pour que les tests soient plus longs", "Pour que les élèves ne les voient jamais", "Pour mesurer équitablement selon les langues et les cultures"], "answer": 3, "explain": "Les bonnes évaluations sont conçues pour être équitables et comparables entre les groupes.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Qu’est-ce qu’une crise des apprentissages ?", "options": ["De nombreux enfants vont à l’école sans apprendre", "Les enfants apprennent trop vite", "Les écoles ont trop de livres", "Les enfants ne vont jamais à l’école"], "answer": 0, "explain": "La crise des apprentissages désigne des enfants scolarisés qui n’acquièrent pas les compétences de base.", "src": "World Bank, learning poverty"}, {"ch": 3, "q": "Qu’est-ce qu’une évaluation de la lecture en début de scolarité ?", "options": ["Un test réservé aux adultes, passé après leur journée de travail", "Un test de lecture pendant les premières années d’école", "Un test de compétences sportives pour l’équipe de football de l’école", "Un test de cuisine pour jeunes apprenants à la maison"], "answer": 1, "explain": "Les évaluations de lecture en début de scolarité vérifient si les jeunes enfants apprennent à lire.", "src": "UNESCO"}, {"ch": 3, "q": "En quoi la compréhension aide-t-elle les apprenants face à un problème de mathématiques ?", "options": ["À deviner la réponse sans lire", "À sauter la question", "À comprendre ce que demande le problème", "À copier sur un camarade"], "answer": 2, "explain": "La compréhension aide les apprenants à comprendre un problème avant de le résoudre.", "src": "UNESCO"}, {"ch": 4, "q": "Qu’est-ce que la maîtrise des données ?", "options": ["Recueillir des données sur les animaux de compagnie", "Cacher des données aux autres", "Stocker les données uniquement sur papier", "Lire, comprendre et utiliser des données"], "answer": 3, "explain": "La maîtrise des données signifie comprendre et utiliser les données pour prendre des décisions.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Pourquoi les élèves doivent-ils comprendre l’intelligence artificielle ?", "options": ["Pour l’utiliser avec discernement et en connaître les limites", "Pour remplacer tous les enseignants", "Pour cesser d’utiliser les ordinateurs", "Pour éviter toute technologie"], "answer": 0, "explain": "Les apprenants doivent utiliser les outils d’IA de façon responsable et comprendre ce qu’ils peuvent et ne peuvent pas faire.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Qu’est-ce qu’un état d’esprit entrepreneurial ?", "options": ["Éviter tout risque et rester toujours au même endroit", "Repérer les opportunités et prendre des risques raisonnables", "Travailler uniquement pour les autres et jamais pour soi-même", "Ne jamais essayer de nouvelles choses ni de nouvelles idées dans sa vie"], "answer": 1, "explain": "Un état d’esprit entrepreneurial consiste à repérer les opportunités et à agir avec responsabilité.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Que sont les compétences non techniques (soft skills) ?", "options": ["Des compétences pour soulever des charges lourdes", "Des compétences uniquement pour faire du pain", "Des compétences comme le travail d’équipe, l’empathie et la communication", "Des compétences pour dormir"], "answer": 2, "explain": "Les compétences non techniques aident les personnes à bien travailler et vivre avec les autres.", "src": "UNESCO"}, {"ch": 4, "q": "Qu’est-ce que l’apprentissage tout au long de la vie ?", "options": ["Apprendre seulement jusqu’à dix ans", "Apprendre seulement à l’université", "Apprendre seulement le dimanche", "Apprendre tout au long de la vie, et pas seulement à l’école"], "answer": 3, "explain": "L’apprentissage tout au long de la vie désigne la poursuite de l’apprentissage sur l’ensemble de la vie.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Pourquoi l’apprentissage tout au long de la vie est-il important pour le travail ?", "options": ["Le travail évolue, les personnes ont donc besoin de nouvelles compétences", "Les emplois ne changent jamais", "Apprendre est inutile après l’école", "Les emplois ne demandent aucune compétence"], "answer": 0, "explain": "Les nouvelles technologies et industries amènent les personnes à continuer d’acquérir de nouvelles compétences.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Que signifie apprendre à apprendre ?", "options": ["Ne rien mémoriser en espérant réussir quand même", "Savoir comment on apprend le mieux et planifier son apprentissage", "Copier rapidement les réponses dans le cahier d’un camarade", "Ne jamais poser de questions en classe ni à la maison"], "answer": 1, "explain": "Apprendre à apprendre aide les personnes à devenir des apprenants autonomes.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Qu’est-ce que l’intersectionnalité en éducation ?", "options": ["Un type de bâtiment scolaire à plusieurs étages et de nombreuses salles", "Un type d’emploi du temps scolaire utilisé dans toutes les classes", "Comment des identités qui se recoupent peuvent accroître les désavantages", "Une façon de répartir les classes selon la taille de chaque enfant"], "answer": 2, "explain": "L’intersectionnalité reconnaît que le genre, la pauvreté, le handicap et d’autres facteurs peuvent se cumuler.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Que vise l’éducation qui transforme les normes de genre ?", "options": ["Maintenir les normes de genre inchangées", "Enseigner à un seul genre", "Ignorer le genre dans toutes les matières", "Changer les normes de genre néfastes"], "answer": 3, "explain": "L’éducation transformatrice du genre remet en question les stéréotypes et les rôles inégaux.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Pourquoi certaines filles risquent-elles davantage de quitter l’école en période de conflit ?", "options": ["L’insécurité, le déplacement et les violences fondées sur le genre", "Les filles sont toujours plus en sécurité", "Le conflit n’a aucun effet sur les écoles", "Les filles préfèrent les conflits"], "answer": 0, "explain": "Les conflits peuvent accroître des risques comme le déplacement et la violence, qui poussent les filles hors de l’école.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Qu’est-ce qui aide à prévenir les violences fondées sur le genre dans les écoles ?", "options": ["Cacher les incidents aux parents et au public", "Des politiques, des codes de conduite et de la formation", "Blâmer les victimes pour ce qui leur est arrivé", "Ignorer tous les signalements reçus par l’école"], "answer": 1, "explain": "La prévention comprend des codes de conduite clairs, de la formation et des systèmes de signalement.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Qu’est-ce que la participation équitable en classe ?", "options": ["Seuls les élèves les plus bruyants parlent", "Seuls les garçons parlent en classe", "Tous les apprenants peuvent participer et être entendus", "Seul l’enseignant parle"], "answer": 2, "explain": "La participation équitable signifie que chaque apprenant a une chance égale de contribuer.", "src": "UNESCO"}, {"ch": 5, "q": "Qu’est-ce qu’un langage discriminatoire à l’école ?", "options": ["Des mots qui saluent le travail acharné", "Des mots qui expliquent une leçon", "Des mots qui décrivent la météo", "Des mots qui rabaissent les personnes en raison de ce qu’elles sont"], "answer": 3, "explain": "Le langage discriminatoire nuit aux apprenants et crée un environnement dangereux.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Que signifie la stigmatisation pour les apprenants ?", "options": ["Des jugements négatifs qui excluent les personnes", "Un type de prix scolaire", "Un type d’uniforme scolaire", "Une forme d’éloge"], "answer": 0, "explain": "La stigmatisation conduit à traiter les personnes de manière injuste, ce qui peut les empêcher d’apprendre.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "Que sont les normes professionnelles des enseignants ?", "options": ["Une liste des vacances des enseignants", "Les attentes sur ce que les enseignants doivent savoir et faire", "Une liste des goûters de l’école", "Seulement une liste des salaires des enseignants"], "answer": 1, "explain": "Les normes professionnelles décrivent ce à quoi ressemble un bon enseignement.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Pourquoi le recrutement des enseignants est-il un défi politique ?", "options": ["Il faut embaucher uniquement des proches", "Il ne nécessite aucune planification", "Il faut attirer et sélectionner des personnes compétentes", "Il faut fermer des écoles"], "answer": 2, "explain": "Un bon recrutement trouve des personnes compétentes et les affecte là où elles sont nécessaires.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce que l’affectation des enseignants ?", "options": ["Envoyer les enseignants en vacances", "Envoyer les enseignants uniquement dans d’autres pays", "Retirer les enseignants des écoles", "Placer les enseignants là où ils sont nécessaires"], "answer": 3, "explain": "L’affectation consiste à répartir les enseignants dans les écoles et les zones où ils sont le plus nécessaires.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce que la fidélisation des enseignants ?", "options": ["Garder les enseignants dans la profession", "Garder les enseignants en classe sans pause", "Empêcher les élèves de devenir enseignants", "Tenir les enseignants éloignés des enfants"], "answer": 0, "explain": "Les stratégies de fidélisation permettent de garder les enseignants formés dans leur poste.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Pourquoi les enseignants ont-ils besoin d’une certaine autonomie ?", "options": ["Pour échapper à toutes les règles", "Pour adapter leurs leçons à leurs élèves", "Pour ne rien enseigner", "Pour travailler sans soutien"], "answer": 1, "explain": "Une certaine autonomie aide les enseignants à adapter leurs leçons aux besoins réels de la classe.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce qu’un syndicat d’enseignants ?", "options": ["Un groupe qui ferme des écoles", "Un groupe qui vend des manuels", "Une organisation qui défend les intérêts des enseignants", "Un groupe qui fixe seul les dates des examens"], "answer": 2, "explain": "Les syndicats d’enseignants représentent les enseignants dans les discussions sur les salaires et les conditions de travail.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce que l’absentéisme des enseignants ?", "options": ["Des enseignants qui suivent une formation", "Des enseignants qui aident dans des clubs", "Des enseignants qui lisent des livres", "Des enseignants qui manquent le travail sans bonne raison"], "answer": 3, "explain": "L’absentéisme réduit le temps d’apprentissage, c’est donc une préoccupation politique.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Sur quoi le bien-être des enseignants a-t-il une incidence ?", "options": ["Sur la qualité de leur enseignement et leur maintien dans le métier", "Seulement sur le prix des bus scolaires", "Seulement sur la météo", "Rien d’important"], "answer": 0, "explain": "Le bien-être des enseignants influence la qualité de l’enseignement et la fidélisation.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "Qu’est-ce que la transparence budgétaire en éducation ?", "options": ["Cacher les dépenses au public", "Publier la manière dont l’argent de l’éducation est dépensé", "Dépenser l’argent en secret", "Ignorer les budgets"], "answer": 1, "explain": "La transparence permet aux citoyens de vérifier comment les fonds de l’éducation sont utilisés.", "src": "UNESCO"}, {"ch": 7, "q": "Qu’est-ce que le financement ciblé de l’éducation ?", "options": ["Des fonds égaux pour chaque école, quels que soient leurs besoins", "Des fonds dépensés uniquement pour le sport, les jeux et les sorties scolaires", "Des fonds supplémentaires envoyés aux écoles ou aux élèves qui en ont le plus besoin", "Des fonds envoyés uniquement aux écoles déjà très riches"], "answer": 2, "explain": "Le financement ciblé oriente davantage de ressources là où les besoins sont les plus grands.", "src": "UNESCO GEM Report 2026"}, {"ch": 7, "q": "Qu’est-ce que l’efficience des dépenses scolaires ?", "options": ["Dépenser le plus d’argent possible", "Dépenser pour les choses les moins utiles", "Dépenser uniquement pour les bâtiments", "Obtenir le maximum d’apprentissages avec l’argent dépensé"], "answer": 3, "explain": "Des dépenses efficaces donnent de meilleurs résultats d’apprentissage avec le même montant d’argent.", "src": "UNESCO"}, {"ch": 7, "q": "Pourquoi de nombreux pays financent-ils les écoles par des impôts locaux ?", "options": ["Pour donner aux communautés locales leur mot à dire sur les dépenses", "Les impôts locaux sont illégaux", "Les impôts locaux remplacent tout l’argent de l’État", "Les impôts locaux servent uniquement au sport"], "answer": 0, "explain": "Un financement local peut rendre les écoles plus réactives, mais il peut aussi accroître les inégalités.", "src": "UNESCO"}, {"ch": 7, "q": "Quel est le risque de ne compter que sur les impôts locaux ?", "options": ["Les zones plus pauvres reçoivent toujours plus d’argent", "Les zones plus riches peuvent mieux financer leurs écoles", "Les écoles n’ont jamais besoin d’argent", "Les impôts locaux mettent toujours fin aux inégalités"], "answer": 1, "explain": "Ne compter que sur les impôts locaux peut creuser l’écart entre zones riches et zones pauvres.", "src": "UNESCO GEM Report 2026"}, {"ch": 7, "q": "Qu’est-ce qu’un budget d’investissement pour les écoles ?", "options": ["L’argent destiné uniquement aux salaires des enseignants", "L’argent destiné aux vacances", "L’argent destiné aux bâtiments et aux équipements", "L’argent destiné uniquement aux uniformes scolaires"], "answer": 2, "explain": "Un budget d’investissement finance des actifs durables comme les bâtiments et les équipements.", "src": "UNESCO"}, {"ch": 7, "q": "Qu’est-ce qu’un budget de fonctionnement pour les écoles ?", "options": ["L’argent destiné à construire une seule nouvelle école", "L’argent destiné à un seul examen", "L’argent destiné à des événements sportifs ponctuels", "L’argent destiné aux dépenses courantes, comme les salaires"], "answer": 3, "explain": "Un budget de fonctionnement couvre les coûts récurrents comme les salaires des enseignants et les fournitures.", "src": "UNESCO"}, {"ch": 7, "q": "Qu’est-ce que le coût unitaire en éducation ?", "options": ["Le coût de l’éducation d’un élève pendant un an", "Le coût d’un bus scolaire", "Le coût d’un uniforme scolaire complet", "Le coût d’une seule épreuve d’examen"], "answer": 0, "explain": "Le coût unitaire aide les gouvernements à planifier le montant nécessaire pour chaque apprenant.", "src": "UNESCO"}, {"ch": 8, "q": "En quelle année le Forum mondial sur l’éducation s’est-il réuni à Incheon ?", "options": ["1990", "2015", "2000", "2030"], "answer": 1, "explain": "Le Forum mondial sur l’éducation s’est tenu à Incheon, en République de Corée, en 2015.", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "Où s’est tenu le Forum mondial sur l’éducation de 2015 ?", "options": ["Dakar, Sénégal", "Jomtien, Thaïlande", "Incheon, République de Corée", "Paris, France"], "answer": 2, "explain": "Incheon, en République de Corée, a accueilli le forum de 2015.", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "Où s’est tenu le Forum mondial sur l’éducation de 2000 ?", "options": ["Incheon, République de Corée", "Jomtien, Thaïlande", "Nairobi, Kenya", "Dakar, Sénégal"], "answer": 3, "explain": "Le forum de Dakar de 2000 a adopté le Cadre d’action de Dakar.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "Que couvre l’article 26 de la Déclaration universelle des droits de l’homme ?", "options": ["Le droit à l’éducation", "Le droit d’avoir une voiture", "Le droit aux vacances", "Le droit de voter dans les écoles"], "answer": 0, "explain": "L’article 26 énonce le droit à l’éducation.", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "Sur quoi l’Éducation 2030 s’appuie-t-elle ?", "options": ["Uniquement sur les Jeux olympiques et les règles pour les athlètes", "Sur les Objectifs du Millénaire pour le développement et l’Éducation pour tous", "Uniquement sur l’exploration spatiale et les études de fusées", "Uniquement sur les règles du sport et les résultats des tournois de football"], "answer": 1, "explain": "L’Éducation 2030 s’appuie sur les engagements mondiaux antérieurs en matière d’éducation.", "src": "Incheon Framework for Action (2015)"}, {"ch": 8, "q": "Pourquoi le monde est-il passé des OMD aux ODD ?", "options": ["Pour annuler tous les objectifs éducatifs de la décennie suivante", "Pour se concentrer sur un seul pays et ignorer les autres", "Pour couvrir un éventail plus large de questions pour tous les pays", "Pour supprimer toutes les cibles fixées par les pays"], "answer": 2, "explain": "Les ODD sont universels et couvrent davantage de questions que les OMD.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "Quelle période couvraient les OMD ?", "options": ["De 1990 à 2000", "De 2015 à 2030", "De 2000 à 2030", "De 2000 à 2015"], "answer": 3, "explain": "Les OMD ont couvert la période de 2000 à 2015.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 9, "q": "Qu’est-ce que la prise en charge réactive ?", "options": ["Des adultes qui réagissent avec chaleur et à-propos aux signaux d’un enfant", "Ignorer les signaux d’un enfant et le laisser pleurer", "Donner seulement des ordres sans jamais écouter les enfants", "Tenir les enfants à l’écart des adultes dans tous les contextes"], "answer": 0, "explain": "La prise en charge réactive instaure la confiance et soutient les apprentissages.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Pourquoi la santé de l’enfant compte-t-elle pour les apprentissages ?", "options": ["La santé n’a aucun effet sur les apprentissages", "La maladie et la faim peuvent empêcher les enfants d’apprendre", "Seul le sport a besoin de santé", "Les enfants en bonne santé n’ont jamais besoin de l’école"], "answer": 1, "explain": "Une bonne santé et une bonne alimentation aident les enfants à apprendre et à se concentrer.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "Qu’est-ce que le retard de croissance ?", "options": ["Grandir très vite et devenir beaucoup plus grand que la plupart de ses camarades", "Une règle disciplinaire scolaire sur l’uniforme, les cheveux et les chaussures pour tous", "Être beaucoup plus petit que prévu pour son âge en raison d’une mauvaise alimentation", "Être très grand pour son âge et grandir plus vite que la plupart de ses camarades"], "answer": 2, "explain": "Le retard de croissance est un signe de dénutrition chronique et peut affecter les apprentissages.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "Qu’est-ce que la stimulation précoce ?", "options": ["Garder un bébé dans un silence complet pendant de longues heures chaque jour", "Ne donner aux tout-petits que des sucreries à chaque repas", "Garder les bébés dans des pièces sombres pendant presque toute la journée", "Des activités qui stimulent les sens et la pensée d’un bébé"], "answer": 3, "explain": "La stimulation précoce comprend la parole, le chant, le toucher et le jeu.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Pourquoi les services de la petite enfance ont-ils besoin d’un personnel formé ?", "options": ["Un personnel formé soutient au mieux le développement des enfants", "Le personnel n’est pas nécessaire", "La formation est un gaspillage d’argent", "Un personnel formé fait cesser l’apprentissage des enfants"], "answer": 0, "explain": "Un personnel bien formé comprend comment les jeunes enfants apprennent.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "Qu’est-ce qu’un programme de transition de la petite enfance vers le primaire ?", "options": ["Un pont au-dessus d’une rivière", "Un programme qui aide les enfants à s’adapter", "Une route pour les bus scolaires", "Un terrain de sport"], "answer": 1, "explain": "Les programmes de transition aident les jeunes enfants à s’installer à l’école primaire.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "Qu’est-ce que la conscience phonémique ?", "options": ["Connaître les noms des couleurs", "Écrire uniquement en majuscules", "Remarquer les sons dans les mots parlés", "Lire le dos d’un livre"], "answer": 2, "explain": "La conscience phonémique aide les enfants à relier les sons aux lettres.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "Qu’est-ce que le vocabulaire dans la lecture initiale ?", "options": ["Le prix des livres", "Le nombre de pages", "La taille des lettres", "Les mots qu’un enfant connaît et utilise"], "answer": 3, "explain": "Un vocabulaire riche aide les enfants à comprendre ce qu’ils lisent.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "Qu’est-ce que l’éducation de base des adultes ?", "options": ["La lecture, l’écriture et le calcul de base pour les adultes", "Des études universitaires avancées en physique et en droit", "L’entraînement sportif d’une équipe de football locale", "Des leçons de conduite pour les adultes qui veulent un permis"], "answer": 0, "explain": "L’éducation de base des adultes aide à acquérir les compétences essentielles en littératie et en calcul.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Qu’est-ce qu’un environnement riche en écrit ?", "options": ["Un lieu sans aucun mot imprimé", "Un lieu avec beaucoup de mots imprimés à lire", "Un lieu où tous les livres sont enfermés", "Un lieu avec seulement des images"], "answer": 1, "explain": "Les environnements riches en écrit exposent les enfants aux lettres et aux mots de la vie quotidienne.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "Pourquoi les zones rurales ont-elles souvent des niveaux de littératie plus bas ?", "options": ["Les habitants des campagnes ne lisent jamais", "La loi interdit d’enseigner la lecture dans les zones rurales", "Il y a moins d’écoles, de livres et de lieux de lecture à proximité", "Les habitants des campagnes n’ont pas besoin de lire"], "answer": 2, "explain": "De nombreux pays montrent une littératie plus faible dans les zones rurales, où écoles et livres sont plus difficiles d’accès.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Pourquoi la lecture pour le plaisir est-elle importante ?", "options": ["Elle fait perdre du temps", "Elle est réservée aux enseignants", "Elle empêche les enfants de lire plus tard", "Elle crée des habitudes de lecture et des connaissances plus larges"], "answer": 3, "explain": "La lecture pour le plaisir crée des habitudes qui soutiennent l’apprentissage tout au long de la vie.", "src": "UNESCO, International Literacy Day"}, {"ch": 11, "q": "Que favorise la conception universelle de l’apprentissage ?", "options": ["Plusieurs manières de présenter, d’engager et d’évaluer les apprentissages", "Une seule façon d’enseigner que tous les apprenants doivent suivre", "Supprimer toutes les évaluations de l’année scolaire", "Enseigner uniquement en silence, sans aucune discussion"], "answer": 0, "explain": "La conception universelle offre des choix pour que les apprenants accèdent aux apprentissages et montrent ce qu’ils savent.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Qu’est-ce qu’un plan de soutien aux apprentissages ?", "options": ["Un plan de vacances scolaires pour tous les élèves", "Un plan qui définit le soutien apporté aux besoins d’un apprenant", "Un plan pour arrêter les cours plus tôt chaque jour", "Un plan pour exclure certains élèves de l’école"], "answer": 1, "explain": "Les plans de soutien aux apprentissages définissent des aménagements et une aide pour des apprenants en particulier.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Pourquoi les familles d’apprenants en situation de handicap devraient-elles être impliquées ?", "options": ["Les familles ne devraient pas être impliquées", "Les familles ne font que payer des frais", "Elles connaissent mieux les besoins de l’apprenant", "Les familles créent des problèmes"], "answer": 2, "explain": "Les familles apportent des connaissances qui aident l’école à soutenir les apprenants.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Qu’est-ce que l’évaluation inclusive ?", "options": ["Des tests que seuls les meilleurs peuvent réussir", "Des tests qui ne sont jamais donnés", "Des tests qui mesurent seulement la vitesse", "Des tests qui permettent à tous les apprenants de montrer ce qu’ils savent"], "answer": 3, "explain": "L’évaluation inclusive adapte la manière de montrer les apprentissages pour que tous puissent les démontrer.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Qu’est-ce que le soutien par les pairs dans une école inclusive ?", "options": ["Des camarades qui s’aident à apprendre", "Des camarades qui rivalisent pour exclure les autres", "Des camarades qui travaillent seuls uniquement", "Des camarades qui s’évitent"], "answer": 0, "explain": "Le soutien par les pairs aide les apprenants à se sentir inclus et à apprendre ensemble.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Pourquoi les écoles inclusives réduisent-elles la discrimination ?", "options": ["Elles séparent les enfants selon leur niveau", "Elles enseignent le respect et rendent la différence normale", "Elles suppriment toute diversité", "Elles augmentent la peur"], "answer": 1, "explain": "Quand les enfants apprennent ensemble, ils développent le respect et la compréhension.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Qu’est-ce que la ségrégation dans les écoles ?", "options": ["Réunir tous les enfants dans la même classe chaque jour", "Partager équitablement les livres et le matériel entre les élèves", "Séparer les enfants selon leur handicap, leur genre ou leur origine", "Donner à chacun un tour équitable dans la cour de récréation"], "answer": 2, "explain": "La ségrégation sépare injustement les apprenants, et l’éducation inclusive s’y oppose.", "src": "UN CRPD (2006), Article 24"}, {"ch": 1, "q": "Qu’est-ce que la zone de recrutement d’une école ?", "options": ["Un type de sport scolaire", "Le toit d’une école", "Un repas scolaire", "La zone que l’école est censée desservir"], "answer": 3, "explain": "La zone de recrutement est la zone d’enfants que l’école est prévue pour accueillir.", "src": "UNESCO"}], "9": [{"ch": 0, "q": "Quel ODD porte sur les partenariats pour la réalisation des objectifs ?", "options": ["Objectif 17", "Objectif 7", "Objectif 12", "Objectif 1"], "answer": 0, "explain": "L’Objectif 17 porte sur les partenariats pour la réalisation des objectifs.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "À quoi renvoient les moyens de mise en œuvre ?", "options": ["Aux noms de tous les objectifs écrits sur une grande affiche", "Aux ressources et outils nécessaires pour atteindre les objectifs", "Aux dates des réunions tenues chaque année à la mairie", "Aux couleurs des affiches accrochées dans le hall de l’école"], "answer": 1, "explain": "Les moyens de mise en œuvre comprennent le financement, la technologie, les capacités et les partenariats.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Quel est le problème du manque de données dans le suivi des ODD ?", "options": ["Il y a beaucoup trop de données pour que quiconque puisse vraiment les lire", "Les données ne sont conservées que sur papier, dans de vieux classeurs", "De nombreux pays ne disposent pas de données fiables pour suivre les progrès", "Les données sont toujours parfaites et n’ont jamais besoin d’être vérifiées"], "answer": 2, "explain": "Les lacunes de données rendent difficile la mesure des progrès et l’identification des personnes laissées pour compte.", "src": "UN SDG Report 2026"}, {"ch": 0, "q": "Pourquoi les ODD utilisent-ils des indicateurs ?", "options": ["Pour établir les emplois du temps scolaires", "Pour choisir l’hymne national", "Pour remplacer les enseignants", "Pour mesurer les progrès de manière cohérente"], "answer": 3, "explain": "Les indicateurs rendent les progrès comparables entre les pays et dans le temps.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Qu’est-ce que le Programme 2030 ?", "options": ["Un plan adopté en 2015 pour atteindre les objectifs d’ici 2030", "Un plan pour les Jeux olympiques organisés à Paris en 2030", "Un emploi du temps scolaire qui court jusqu’en 2030", "Un calendrier de vacances pour toutes les écoles de l’année 2030"], "answer": 0, "explain": "Le Programme 2030 est le plan de l’ONU adopté en 2015 pour les Objectifs mondiaux.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "À quoi sert un plan national pour l’ODD 4 ?", "options": ["À fermer toutes les écoles", "À définir comment un pays atteindra l’ODD 4", "À annuler tous les examens", "À supprimer les frais de scolarité par simple décret"], "answer": 1, "explain": "Un plan national fixe les priorités, les budgets et les actions pour atteindre l’ODD 4.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Qu’est-ce que l’exclusion scolaire ?", "options": ["Le fait de recevoir un prix", "Le fait de changer d’école par choix", "Le fait d’être écarté de l’école ou tenu à l’écart de celle-ci", "Le fait de recevoir des cours supplémentaires"], "answer": 2, "explain": "L’exclusion empêche les enfants d’apprendre, ce qui porte atteinte à leur droit à l’éducation.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 1, "q": "Quel est l’impact du mariage des enfants sur la scolarité ?", "options": ["Il améliore toujours l’école", "Il n’a aucun effet", "Il rend l’école gratuite", "Il met souvent fin prématurément à la scolarité"], "answer": 3, "explain": "Le mariage des enfants est une cause majeure de départ précoce des filles de l’école.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 1, "q": "Qu’est-ce que le déplacement forcé pour l’éducation ?", "options": ["Être contraint de quitter son foyer, ce qui perturbe souvent la scolarité", "Déplacer un pupitre de l’autre côté de la salle de classe", "Choisir chaque année une nouvelle école pour le trimestre suivant", "Un type d’examen scolaire passé au début du trimestre"], "answer": 0, "explain": "Les enfants déplacés peuvent perdre des années de scolarité sans soutien.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Qu’est-ce que l’éducation des réfugiés ?", "options": ["L’éducation réservée aux enseignants d’une école en particulier", "L’éducation des enfants et des jeunes qui ont fui leur foyer", "L’éducation uniquement par le sport et les activités de plein air pour toute l’école", "L’éducation réservée aux adultes qui reprennent leurs études plus tard"], "answer": 1, "explain": "L’éducation des réfugiés aide les apprenants déplacés à poursuivre leur apprentissage.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Pourquoi l’éducation en situation d’urgence est-elle importante ?", "options": ["Elle n’a aucune valeur pendant les crises", "Elle ne concerne que les touristes", "Elle offre stabilité et protection aux enfants", "Elle remplace toute l’aide alimentaire"], "answer": 2, "explain": "Les écoles en situation d’urgence offrent aux enfants sécurité, repères et espoir.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Qu’est-ce qu’un espace d’apprentissage temporaire ?", "options": ["Un bâtiment servant à stocker des voitures et des engins lourds", "Un magasin qui vend des livres, des stylos et du papier à tous les élèves", "Un lieu réservé aux adultes pour se reposer l’après-midi", "Un lieu sûr pour apprendre, installé rapidement après une crise"], "answer": 3, "explain": "Les espaces d’apprentissage temporaires permettent aux enfants de continuer à apprendre lorsque les écoles permanentes ne peuvent plus être utilisées.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Avec quoi mesure-t-on généralement la distance jusqu’à l’école ?", "options": ["Avec le temps ou la distance que l’enfant doit parcourir", "Avec le nombre de livres", "Avec la couleur de l’école", "Avec le nombre d’enseignants de la ville"], "answer": 0, "explain": "Le temps de trajet et la distance sont des mesures courantes de l’accès.", "src": "UNESCO"}, {"ch": 1, "q": "Pourquoi les enfants en situation de handicap manquent-ils souvent l’école ?", "options": ["Ils ne veulent pas apprendre", "Les écoles ne sont pas accessibles ni soutenues", "Ils sont trop intelligents pour l’école", "Ils ont trop de jouets"], "answer": 1, "explain": "Le manque de bâtiments accessibles, d’enseignement adapté et de soutien éloigne de l’école de nombreux enfants.", "src": "UN CRPD (2006), Article 24"}, {"ch": 2, "q": "Qu’est-ce que le taux de redoublement ?", "options": ["La part de ceux qui gagnent des courses", "La part de ceux qui entrent à l’école plus tôt", "La part des élèves qui redoublent une classe", "La part de ceux qui étudient la musique"], "answer": 2, "explain": "Les taux de redoublement indiquent à quelle fréquence les élèves redoublent une classe.", "src": "UNESCO"}, {"ch": 2, "q": "Pourquoi le redoublement est-il souvent une mauvaise solution ?", "options": ["Il améliore toujours les apprentissages", "Il est gratuit pour tous", "Il supprime toutes les lacunes", "Il peut accroître le risque d’abandon scolaire"], "answer": 3, "explain": "Redoubler une année augmente souvent les chances qu’un élève quitte l’école.", "src": "UNESCO"}, {"ch": 2, "q": "Qu’est-ce que le passage en classe supérieure ?", "options": ["Le fait de passer dans la classe suivante", "La vente d’uniformes scolaires", "Le fait de déménager dans un autre pays", "L’abandon de l’école"], "answer": 0, "explain": "Le passage signifie qu’un élève accède à la classe suivante.", "src": "UNESCO"}, {"ch": 2, "q": "Qu’est-ce qu’un certificat de fin de scolarité ?", "options": ["Un billet pour un grand match de football au stade national", "Un document qui atteste qu’un élève a terminé un niveau", "Une amende infligée à tout élève qui manque souvent l’école", "Une carte qui indique où se trouve chaque école de la ville"], "answer": 1, "explain": "Un certificat de fin de scolarité atteste l’achèvement d’un niveau d’enseignement.", "src": "UNESCO"}, {"ch": 2, "q": "À quoi servent les objectifs nationaux d’achèvement ?", "options": ["À réduire le nombre total d’écoles dans tout le pays", "À empêcher les enfants de passer au niveau suivant", "À augmenter la part des enfants qui terminent chaque niveau", "À donner moins d’examens à tous les élèves de l’école"], "answer": 2, "explain": "Les objectifs nationaux visent à aider davantage d’enfants à achever chaque niveau.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Qu’est-ce que la certification des compétences ?", "options": ["Un type de cartable avec beaucoup de petites poches", "Un calendrier de vacances pour toute la famille chaque été", "Une recette de cuisine pour un dîner familial spécial", "La reconnaissance officielle des compétences d’une personne"], "answer": 3, "explain": "La certification montre aux employeurs et à d’autres qu’une personne possède une compétence.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Qu’est-ce que la reconnaissance des acquis ?", "options": ["Accorder une validation aux apprentissages déjà acquis hors de l’école", "Ignorer tous les acquis antérieurs et repartir de zéro à chaque fois", "Ne compter que les examens passés à l’université ou dans un établissement supérieur", "Supprimer les diplômes que les personnes ont déjà obtenus"], "answer": 0, "explain": "Reconnaître les acquis aide les personnes à avancer sans répéter ce qu’elles savent déjà.", "src": "UNESCO"}, {"ch": 3, "q": "Qu’est-ce qu’un standard d’apprentissage ?", "options": ["Un type de bâtiment scolaire avec de nombreuses salles de classe", "Une description de ce que les apprenants doivent savoir et savoir faire", "Un type de bus scolaire qui circule chaque matin", "Un code vestimentaire pour les élèves et les enseignants"], "answer": 1, "explain": "Les standards d’apprentissage décrivent les résultats attendus pour chaque niveau.", "src": "UNESCO"}, {"ch": 3, "q": "Sur quoi porte le Rapport mondial de suivi sur l’éducation ?", "options": ["Sur la vente de manuels scolaires", "Sur le choix des sports scolaires", "Sur le suivi des progrès de l’éducation dans le monde", "Sur la planification des vacances"], "answer": 2, "explain": "Le Rapport GEM suit les progrès de l’éducation et partage des données probantes.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Qu’est-ce qu’un profil d’apprentissage ?", "options": ["Une photo d’un élève", "Une liste des vacances scolaires", "Un plan de l’école", "Un relevé des points forts et des besoins d’un apprenant"], "answer": 3, "explain": "Les profils d’apprentissage aident les enseignants à planifier le soutien de chaque apprenant.", "src": "UNESCO"}, {"ch": 3, "q": "Pourquoi les enseignants utilisent-ils des évaluations diagnostiques ?", "options": ["Pour savoir ce que les apprenants savent déjà et ce dont ils ont besoin", "Pour attribuer des notes uniquement à la fin de chaque année scolaire", "Pour éviter de faire cours à toute la classe pendant toute la journée", "Pour punir les enfants chaque fois qu’ils font une erreur"], "answer": 0, "explain": "Les évaluations diagnostiques aident les enseignants à planifier des leçons adaptées aux besoins des apprenants.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Qu’est-ce que la réforme des programmes ?", "options": ["Changer la couleur de l’école", "Modifier ce qui est enseigné et la manière de l’enseigner", "Fermer toutes les écoles", "Supprimer toutes les matières"], "answer": 1, "explain": "La réforme des programmes actualise les matières, les compétences et les méthodes d’enseignement.", "src": "UNESCO"}, {"ch": 3, "q": "Qu’est-ce que l’apprentissage par compétences ?", "options": ["Se concentrer uniquement sur la mémorisation de faits", "Se concentrer uniquement sur le sport", "Se concentrer sur ce que les apprenants savent faire", "Se concentrer uniquement sur le temps passé en classe"], "answer": 2, "explain": "L’apprentissage par compétences mesure les savoir-faire et les capacités, et pas seulement les connaissances.", "src": "UNESCO"}, {"ch": 3, "q": "Pourquoi la culture scientifique est-elle importante ?", "options": ["Elle remplace toutes les compétences en lecture et en écriture", "Elle n’aide que les scientifiques dans leurs laboratoires", "Elle n’a aucune utilité réelle dans la vie quotidienne", "Elle aide les personnes à comprendre et à juger les preuves"], "answer": 3, "explain": "La culture scientifique aide à prendre des décisions éclairées sur la santé et l’environnement.", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "Qu’est-ce que le raisonnement mathématique ?", "options": ["Expliquer pourquoi une méthode fonctionne", "Deviner la réponse", "Copier la réponse", "Sauter les étapes de calcul"], "answer": 0, "explain": "Le raisonnement montre que l’apprenant comprend la méthode, et pas seulement la réponse.", "src": "UNESCO"}, {"ch": 3, "q": "Qu’est-ce qu’un gain d’apprentissage ?", "options": ["Une prise de poids", "Le progrès réalisé par un apprenant sur une période donnée", "Un bénéfice tiré des ventes de l’école", "Un gain de vacances"], "answer": 1, "explain": "Les gains d’apprentissage mesurent la progression d’un apprenant au fil du temps.", "src": "UNESCO GEM Report 2026"}, {"ch": 4, "q": "Qu’est-ce qu’une compétence verte ?", "options": ["Une compétence pour peindre les murs en vert", "Une compétence uniquement pour faire pousser de l’herbe", "Une compétence qui aide à protéger l’environnement", "Une compétence pour jouer à des jeux verts"], "answer": 2, "explain": "Les compétences vertes soutiennent la protection de l’environnement et les emplois durables.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Pourquoi l’éducation au climat est-elle liée à la cible 4.7 ?", "options": ["Le climat n’a aucun lien avec les apprentissages", "L’éducation au climat est interdite", "L’éducation au climat remplace les mathématiques", "Elle soutient l’éducation au développement durable"], "answer": 3, "explain": "La cible 4.7 inclut l’éducation au développement durable, qui couvre le climat.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Qu’est-ce que l’éducation à la paix ?", "options": ["Apprendre à résoudre les conflits sans violence", "Apprendre à provoquer des conflits", "Apprendre uniquement l’histoire des guerres", "Apprendre à éviter les gens"], "answer": 0, "explain": "L’éducation à la paix enseigne le respect, le dialogue et la non-violence.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Qu’enseigne l’éducation aux droits humains ?", "options": ["Uniquement les règles des jeux", "Les droits et les responsabilités des apprenants", "Uniquement l’histoire des trains", "Uniquement la cuisine"], "answer": 1, "explain": "L’éducation aux droits humains aide les apprenants à connaître et à respecter les droits.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Qu’est-ce que l’éducation civique ?", "options": ["Apprendre uniquement sur les voitures", "Apprendre uniquement sur les arbres", "Apprendre la citoyenneté et la vie publique", "Apprendre uniquement sur le sport"], "answer": 2, "explain": "L’éducation civique aide les apprenants à participer de façon responsable à la vie de leur communauté.", "src": "UNESCO"}, {"ch": 4, "q": "Pourquoi enseigne-t-on la compréhension interculturelle ?", "options": ["Elle empêche les gens de voyager", "Elle rend toutes les cultures identiques", "Elle ne concerne que les touristes", "Elle aide à respecter les différentes façons de vivre"], "answer": 3, "explain": "La compréhension interculturelle réduit les préjugés et renforce le respect.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Qu’est-ce que l’apprentissage par la résolution de problèmes ?", "options": ["Apprendre en résolvant de vrais problèmes", "Apprendre en mémorisant des listes", "Apprendre en évitant les questions", "Apprendre en recopiant uniquement des notes"], "answer": 0, "explain": "L’apprentissage par problèmes développe la pensée en confrontant les apprenants à de vrais défis.", "src": "UNESCO"}, {"ch": 5, "q": "Qu’est-ce que la pauvreté dans l’éducation ?", "options": ["Avoir trop de livres sur l’étagère de la classe", "Un manque d’argent qui limite l’accès à l’apprentissage", "Avoir trop d’enseignants par rapport au nombre d’élèves", "Avoir trop de vacances pendant l’année scolaire"], "answer": 1, "explain": "La pauvreté peut limiter l’accès à l’école, à la nourriture, aux transports et au matériel scolaire.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "Qu’est-ce qu’une disparité ethnique dans l’éducation ?", "options": ["Des différences de couleur des cartables", "Des différences uniquement dans les vacances scolaires", "Des différences de résultats scolaires entre des groupes ethniques", "Des différences de chaussures d’école"], "answer": 2, "explain": "Les disparités ethniques montrent que certains groupes réussissent moins, ce qui peut refléter des obstacles injustes.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "Qu’est-ce qu’une disparité rural-urbain ?", "options": ["Des différences dans le nombre de parcs de la ville", "Des différences de pluviométrie", "Des différences d’uniformes scolaires", "Des différences entre l’apprentissage en zone rurale et en zone urbaine"], "answer": 3, "explain": "Les zones rurales disposent souvent de moins de ressources, ce qui peut accroître les écarts d’apprentissage.", "src": "UNESCO"}, {"ch": 5, "q": "Que mesure un quintile de richesse ?", "options": ["Répartir les ménages en cinq groupes selon leur richesse", "Cinq types de bus scolaires utilisés dans toute la ville", "Cinq façons de faire passer un test à toute une classe chaque année", "Cinq couleurs de craie utilisées dans chaque salle de classe"], "answer": 0, "explain": "Les quintiles de richesse répartissent les familles en cinq groupes pour comparer les résultats éducatifs.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "Qu’est-ce qu’une politique en faveur des plus pauvres dans l’éducation ?", "options": ["Une politique qui n’aide que les plus riches", "Une politique qui cible les apprenants les plus pauvres", "Une politique qui ferme les écoles des zones pauvres", "Une politique qui augmente les frais pour les pauvres"], "answer": 1, "explain": "Les politiques en faveur des plus pauvres concentrent les ressources sur ceux qui en ont le plus besoin.", "src": "UNESCO"}, {"ch": 5, "q": "Qu’est-ce que l’égalité des chances dans l’éducation ?", "options": ["Seuls les meilleurs apprenants ont des chances", "Les chances dépendent de la richesse familiale", "La même chance de réussir, quelle que soit l’origine", "Les chances ne sont offertes que dans les villes"], "answer": 2, "explain": "L’égalité des chances signifie que l’origine ne doit pas déterminer ce qu’un apprenant peut accomplir.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "Qu’est-ce que l’écart de salaire des enseignants ?", "options": ["Les enseignants sont mieux payés que les médecins", "Les enseignants sont payés en or", "Les enseignants ne sont jamais payés", "Les enseignants sont moins bien payés que des professionnels comparables"], "answer": 3, "explain": "Un écart de salaire signifie que les enseignants gagnent moins que des travailleurs comparables, ce qui rend le métier moins attractif.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Pourquoi le salaire des enseignants compte-t-il pour les apprentissages ?", "options": ["Il influe sur qui devient enseignant et qui le reste", "Il n’a aucun lien avec les apprentissages", "Il n’affecte que les bâtiments scolaires", "Il n’affecte que les vacances"], "answer": 0, "explain": "Le salaire influe sur le fait que des personnes compétentes choisissent d’enseigner et restent dans le métier.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce que l’habilitation à enseigner ?", "options": ["Un permis pour vendre la restauration scolaire", "L’autorisation officielle d’enseigner", "Un permis pour construire des écoles", "Un permis pour exploiter un service de bus"], "answer": 1, "explain": "L’habilitation fixe des normes minimales pour les personnes qui enseignent.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce qu’un programme d’accompagnement des nouveaux enseignants ?", "options": ["Une formation pour les conducteurs de bus scolaires", "Une formation pour les cuisiniers", "Un soutien aux enseignants pendant leurs premières années", "Une formation réservée aux parents"], "answer": 2, "explain": "L’accompagnement aide les nouveaux enseignants à s’installer et à progresser.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce que la mobilité des enseignants ?", "options": ["Des enseignants qui voyagent en avion", "Des enseignants qui courent des compétitions", "Des enseignants qui restent à jamais dans une même salle", "Le déplacement des enseignants entre écoles ou zones"], "answer": 3, "explain": "La mobilité des enseignants influence les zones qui disposent d’assez d’enseignants qualifiés.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce que la diversité des enseignants ?", "options": ["Des enseignants issus de milieux différents dans les écoles", "Des enseignants qui se ressemblent tous", "Des enseignants qui ne parlent qu’une seule langue", "Des enseignants sans formation"], "answer": 0, "explain": "Un corps enseignant diversifié peut aider les élèves à se reconnaître dans leurs enseignants.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 6, "q": "Qu’est-ce que le leadership pédagogique ?", "options": ["Des chefs d’établissement qui se concentrent uniquement sur le sport", "Des chefs d’établissement qui se concentrent sur l’enseignement et l’apprentissage", "Des chefs d’établissement qui se concentrent sur les vacances", "Des chefs d’établissement qui évitent les enseignants"], "answer": 1, "explain": "Les leaders pédagogiques aident les enseignants à améliorer leurs pratiques en classe.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Pourquoi les écoles ont-elles besoin de chefs d’établissement ?", "options": ["Ils remplacent les enseignants dans chaque classe", "Ils n’enseignent que le sport et l’éducation physique", "Ils orientent l’enseignement et gèrent l’école", "Ils ne sont pas nécessaires dans une école bien gérée"], "answer": 2, "explain": "Les chefs d’établissement soutiennent les enseignants et donnent la direction des apprentissages.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "Qu’est-ce que le financement durable de l’éducation ?", "options": ["De l’argent dépensé une seule fois et jamais plus", "De l’argent recueilli uniquement grâce à une loterie", "De l’argent dépensé uniquement pour les bâtiments", "Un financement qui dure sur le long terme"], "answer": 3, "explain": "Le financement durable désigne des ressources fiables qui se maintiennent pendant de nombreuses années.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "Qu’est-ce que l’aide à l’éducation ?", "options": ["De l’argent ou un soutien apporté par d’autres pays ou organisations", "De l’argent donné par les enseignants à leur école pour le matériel", "De l’argent provenant uniquement des frais payés par les parents", "De l’argent recueilli uniquement grâce aux ventes, aux gâteaux et aux fêtes de l’école"], "answer": 0, "explain": "L’aide à l’éducation provient de donateurs qui soutiennent les écoles d’autres pays.", "src": "UNESCO"}, {"ch": 7, "q": "Que signifie APD ?", "options": ["Accès numérique officiel", "Aide publique au développement", "Archive ouverte de documents", "Assiduité quotidienne en ligne"], "answer": 1, "explain": "APD signifie aide publique au développement, qui comprend l’aide à l’éducation.", "src": "UNESCO"}, {"ch": 7, "q": "Qu’est-ce que la mobilisation des ressources nationales ?", "options": ["Lever des fonds uniquement auprès d’autres pays", "Lever des fonds en vendant des écoles", "Lever des fonds à l’intérieur du pays pour les services publics", "Lever des fonds sur la Lune"], "answer": 2, "explain": "Les pays lèvent de l’argent par l’impôt et d’autres revenus intérieurs pour les écoles.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "Pourquoi certains pays dépendent-ils de l’aide extérieure pour l’éducation ?", "options": ["Ils disposent d’un budget illimité", "Ils ne veulent pas d’écoles", "Ils ne peuvent pas dépenser d’argent", "Leurs propres ressources sont limitées"], "answer": 3, "explain": "Des ressources intérieures limitées peuvent entraîner une dépendance à l’aide extérieure.", "src": "UNESCO"}, {"ch": 7, "q": "À quoi sert un fonds pour l’éducation ?", "options": ["À financer la scolarité et les programmes d’apprentissage", "À payer les vacances en famille et les voyages d’été", "À acheter des voitures neuves pour le personnel de l’école", "À payer des billets pour de grands événements sportifs"], "answer": 0, "explain": "Les fonds pour l’éducation financent la scolarité, le matériel et les programmes.", "src": "UNESCO"}, {"ch": 8, "q": "Qu’a produit la conférence de Jomtien de 1990 ?", "options": ["Un règlement de football réservé aux tournois scolaires", "Une déclaration sur la satisfaction des besoins éducatifs fondamentaux", "Une liste des vacances scolaires pour chaque année", "Une nouvelle monnaie introduite dans toute la région cette année-là"], "answer": 1, "explain": "La Déclaration mondiale sur l’éducation pour tous a été adoptée à Jomtien en 1990.", "src": "UNESCO"}, {"ch": 8, "q": "Qu’est-ce que la Déclaration mondiale sur l’éducation pour tous ?", "options": ["Un plan sportif de 2030 pour toutes les équipes nationales", "Un code de l’uniforme scolaire applicable à tous les élèves", "Une déclaration de 1990 qui promet l’éducation pour tous", "Une loi sur les salaires des enseignants votée l’an dernier"], "answer": 2, "explain": "La déclaration a été adoptée à Jomtien en 1990 et a défini l’Éducation pour tous.", "src": "UNESCO"}, {"ch": 8, "q": "Quel événement de 2000 a adopté le Cadre d’action de Dakar ?", "options": ["Une Coupe du monde de football", "Des Jeux olympiques", "Un sommet commercial", "Le Forum mondial sur l’éducation"], "answer": 3, "explain": "Le Cadre d’action de Dakar a été adopté au Forum mondial sur l’éducation en 2000.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "À quoi s’est engagée la Déclaration d’Incheon ?", "options": ["Une éducation inclusive, équitable et de qualité pour l’apprentissage tout au long de la vie", "Uniquement des études universitaires pour un petit groupe des meilleurs élèves", "Uniquement du sport et des jeux pour l’équipe de l’école chaque semaine", "Uniquement des vacances et des jours libres pour tous les élèves"], "answer": 0, "explain": "La Déclaration d’Incheon a engagé les pays à offrir des possibilités d’apprentissage tout au long de la vie.", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "Que comprenait le Cadre d’action de Dakar au-delà de la scolarité des enfants ?", "options": ["L’alphabétisation réservée aux enseignants", "L’alphabétisation des adultes et l’égalité entre les genres", "L’alphabétisation uniquement dans le sport", "L’alphabétisation réservée aux pays riches"], "answer": 1, "explain": "Le Cadre d’action de Dakar comprenait des objectifs d’alphabétisation des adultes et d’égalité entre les genres.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "Quel Objectif du Millénaire pour le développement visait à promouvoir l’égalité entre les genres ?", "options": ["Objectif 1", "Objectif 5", "Objectif 3", "Objectif 6"], "answer": 2, "explain": "L’OMD 3 visait à promouvoir l’égalité entre les genres et l’autonomisation des femmes.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 8, "q": "Que visaient à réduire les OMD ?", "options": ["Le sport", "Les écoles", "Les vacances", "L’extrême pauvreté et la faim"], "answer": 3, "explain": "Parmi d’autres objectifs, les OMD visaient à réduire l’extrême pauvreté et la faim.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 9, "q": "Qu’est-ce qu’un apprentissage précoce de qualité ?", "options": ["Un apprentissage attentif, ludique et soutenant", "Un apprentissage strict et silencieux", "Un apprentissage qui ne repose que sur des fiches d’exercices", "Un apprentissage qui évite les adultes"], "answer": 0, "explain": "L’apprentissage précoce de qualité développe les compétences à travers des interactions chaleureuses et ludiques.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Pourquoi est-il important de repérer tôt les retards de développement ?", "options": ["Les problèmes doivent être ignorés jusqu’à l’école", "Le soutien peut commencer pendant que le cerveau se développe rapidement", "Les enfants doivent être étiquetés pour la vie", "Les parents doivent être blâmés"], "answer": 1, "explain": "Un repérage précoce permet de commencer le soutien pendant que le cerveau se développe rapidement.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Pourquoi le personnel de la petite enfance est-il important ?", "options": ["Le personnel n’est pas nécessaire", "Le personnel ne fait que nettoyer les pièces", "Un personnel qualifié fait une grande différence pour les enfants", "Le personnel n’a pas d’effet sur les enfants"], "answer": 2, "explain": "Le personnel formé de la petite enfance façonne les apprentissages et le bien-être des enfants.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "Qu’est-ce qu’un espace adapté aux enfants ?", "options": ["Un magasin qui ne vend que des jouets et des bonbons pour enfants", "Un bâtiment sans fenêtres ni portes pour les élèves", "Une pièce où les enfants sont isolés des autres toute la journée", "Un lieu sûr où les enfants peuvent apprendre et jouer"], "answer": 3, "explain": "Les espaces adaptés aux enfants offrent des lieux sûrs pour apprendre et jouer, surtout en période de crise.", "src": "UNESCO GEM Report 2026"}, {"ch": 9, "q": "Que signifie un environnement stimulant pour les bébés ?", "options": ["Beaucoup de paroles, de contacts et de jeux", "Un silence total", "Des pièces sombres", "Un bruit fort et constant"], "answer": 0, "explain": "Les environnements stimulants favorisent le développement du cerveau grâce aux interactions.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Pourquoi la petite enfance est-elle une priorité politique ?", "options": ["Elle n’apporte aucun bénéfice aux enfants ni aux familles", "Un investissement précoce rapporte beaucoup plus tard", "Elle ne coûte que de l’argent sans rien rapporter", "Elle n’aide que les adultes déjà en activité"], "answer": 1, "explain": "Un investissement précoce aide les enfants à apprendre et réduit les coûts ultérieurs.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "Qu’est-ce que la littératie émergente ?", "options": ["La littératie réservée aux adultes", "La lecture uniquement à l’université", "Les premières compétences qui mènent à la lecture et à l’écriture", "La lecture uniquement des chiffres"], "answer": 2, "explain": "La littératie émergente comprend des compétences précoces, comme la connaissance des lettres et des rimes, qui mènent à la lecture.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "Qu’est-ce que la conscience des rimes ?", "options": ["Peindre des rimes sur les murs", "Chanter uniquement des chansons fortes", "Écrire des rimes uniquement sur papier", "Entendre et produire des sons qui riment"], "answer": 3, "explain": "La conscience des rimes aide les enfants à entendre les sons à l’intérieur des mots.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "Qu’inclut la littératie bilingue ?", "options": ["La lecture et l’écriture dans deux langues", "Uniquement la lecture des nombres", "Uniquement le dessin", "Uniquement l’écoute"], "answer": 0, "explain": "La littératie bilingue développe la lecture dans deux langues.", "src": "UNESCO, International Mother Language Day"}, {"ch": 10, "q": "Pourquoi la littératie est-elle liée à l’emploi ?", "options": ["Les emplois n’exigent jamais de lire", "De nombreux emplois exigent de lire et d’écrire", "La littératie ne concerne que les enseignants", "La littératie n’a aucun lien avec les emplois"], "answer": 1, "explain": "La littératie aide à lire des consignes, rédiger des rapports et apprendre de nouvelles compétences.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Qu’est-ce que la littératie informationnelle ?", "options": ["Cacher des informations à tout le monde autour de soi", "Mémoriser chaque page de chaque livre lu", "Trouver, juger et utiliser correctement l’information", "Ignorer l’actualité et les événements en cours"], "answer": 2, "explain": "La littératie informationnelle aide à juger les sources et à utiliser l’information de manière responsable.", "src": "UNESCO"}, {"ch": 10, "q": "Pourquoi de nombreux pays utilisent-ils les langues locales pour la lecture initiale ?", "options": ["Les langues locales ne sont pas autorisées", "Les langues locales rendent la lecture plus difficile", "Les langues locales sont réservées aux adultes", "Les enfants apprennent mieux dans une langue qu’ils parlent"], "answer": 3, "explain": "La lecture initiale est plus facile lorsque les enfants comprennent les mots qu’ils voient.", "src": "UNESCO, International Mother Language Day"}, {"ch": 10, "q": "Pourquoi l’entraînement à l’écriture est-il important ?", "options": ["Il transforme les connaissances en lecture en communication", "Il n’a aucun lien avec les compétences en lecture", "Il ne compte que pour les élèves qui étudient l’art", "Il remplace la lecture par le dessin uniquement"], "answer": 0, "explain": "L’entraînement à l’écriture aide les apprenants à exprimer des idées et à approfondir la lecture.", "src": "UNESCO GEM Report 2026"}, {"ch": 11, "q": "Qu’est-ce qu’un programme scolaire inclusif ?", "options": ["Un programme qui exclut certains apprenants", "Un programme qui valorise et intègre tous les apprenants", "Un programme réservé à un seul groupe", "Un programme sans matières"], "answer": 1, "explain": "Les programmes inclusifs reflètent les besoins et les identités de tous les apprenants.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Qu’est-ce que l’enseignement multisensoriel ?", "options": ["N’utiliser que le son", "Enseigner en silence", "Utiliser la vue, l’ouïe et le toucher dans les leçons", "Enseigner uniquement les yeux bandés"], "answer": 2, "explain": "L’enseignement multisensoriel aide les apprenants qui apprennent mieux de différentes manières.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Qu’est-ce que la technologie d’assistance dans l’éducation ?", "options": ["Des jeux qui rendent l’apprentissage beaucoup plus difficile pour tous les élèves", "Des outils qui empêchent les élèves de lire leurs livres", "Des équipements utilisés uniquement pour le sport et les jeux", "Des outils qui aident les apprenants en situation de handicap à participer"], "answer": 3, "explain": "La technologie d’assistance comprend les lecteurs d’écran, les appareils auditifs et les aides à la communication.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Qu’est-ce qu’un aménagement raisonnable pour les examens ?", "options": ["Des changements tels qu’un temps supplémentaire ou un lecteur", "Supprimer complètement l’examen pour tous", "Rendre les examens plus difficiles pour certains", "Faire payer les examens plus cher"], "answer": 0, "explain": "Les aménagements rendent les examens équitables sans modifier ce qui est évalué.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Pourquoi les écoles devraient-elles recueillir des données sur le handicap ?", "options": ["Pour classer les enfants selon leur handicap", "Pour planifier le soutien et suivre l’inclusion", "Pour empêcher les enfants de s’inscrire", "Pour vendre du matériel scolaire"], "answer": 1, "explain": "Les données sur le handicap aident les écoles à planifier le soutien et à vérifier que les enfants sont inclus.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Qu’est-ce qu’un stéréotype dans l’éducation ?", "options": ["Un type d’examen scolaire passé une fois par an", "Un trajet de bus scolaire qui passe devant la ferme", "Une idée figée et souvent injuste sur un groupe", "Un type de cartable qui contient beaucoup de livres"], "answer": 2, "explain": "Les stéréotypes peuvent limiter ce que les apprenants pensent pouvoir accomplir.", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "Qu’est-ce que le sentiment d’appartenance dans une école ?", "options": ["Être seul en classe", "Être écarté des cours", "Être déménagé dans une autre ville", "Se sentir accepté et valorisé"], "answer": 3, "explain": "Le sentiment d’appartenance aide les apprenants à s’impliquer et à rester à l’école.", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "Que signifie l’accès universel pour le handicap ?", "options": ["Un accès pour tous, y compris les personnes en situation de handicap", "Un accès uniquement pour les personnes sans handicap", "Un accès uniquement dans un seul bâtiment", "Un accès uniquement certains jours particuliers"], "answer": 0, "explain": "L’accès universel signifie que l’éducation est ouverte à tous, avec le soutien dont chacun a besoin.", "src": "UN CRPD (2006), Article 24"}], "10": [{"ch": 0, "q": "Quel principe signifie que l’Agenda 2030 vise à atteindre d’abord ceux qui sont le plus à la traîne ?", "options": ["Ne laisser personne de côté", "La loi du plus fort", "La croissance à tout prix", "Chaque pays pour soi"], "answer": 0, "explain": "Ne laisser personne de côté signifie donner la priorité aux personnes les plus défavorisées.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Quel indicateur de l’ODD 4 suit la participation à un apprentissage organisé un an avant l’école primaire ?", "options": ["Indicateur 4.1.1", "Indicateur 4.2.2", "Indicateur 4.5.1", "Indicateur 4.7.1"], "answer": 1, "explain": "L’indicateur 4.2.2 mesure la participation à un apprentissage organisé un an avant l’âge officiel d’entrée à l’école primaire.", "src": "UN SDG Report 2026"}, {"ch": 0, "q": "Quel est l’objectif des cibles 4.a à 4.c ?", "options": ["Rédiger les questions d’examen", "Choisir les couleurs de l’école", "Fournir les moyens de dispenser l’éducation", "Fermer les universités"], "answer": 2, "explain": "Ces cibles portent sur les infrastructures, les bourses et l’offre d’enseignants.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Pourquoi mesure-t-on les cibles de l’ODD 4 avec des indicateurs et des données ?", "options": ["Pour allonger les rapports", "Pour éviter de prendre des décisions", "Pour remplacer les enseignants", "Pour vérifier que les progrès sont réels et équitables"], "answer": 3, "explain": "Les indicateurs et les données désagrégées montrent les progrès et les inégalités.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Quel est le lien entre l’ODD 4 et l’ODD 1 (Pas de pauvreté) ?", "options": ["L’éducation aide à réduire la pauvreté et la pauvreté limite l’éducation", "Il n’existe aucun lien entre les deux, dans aucun pays", "L’éducation crée la pauvreté et appauvrit les familles chaque année", "La pauvreté affecte seulement les performances sportives des enfants à l’école"], "answer": 0, "explain": "L’éducation et la pauvreté sont étroitement liées dans les deux sens.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Qu’est-ce qu’une situation de référence dans le suivi des ODD ?", "options": ["La ligne d’arrivée qui marque la fin d’une longue course", "Le point de départ par rapport auquel on mesure les progrès", "Le fond d’un cartable où l’on range les vieux livres", "Le prix d’un manuel scolaire neuf dans la boutique locale"], "answer": 1, "explain": "Une situation de référence est la donnée initiale utilisée pour mesurer le changement.", "src": "UN SDG Report 2026"}, {"ch": 1, "q": "Qu’est-ce que l’instruction obligatoire ?", "options": ["L’éducation facultative pour tous", "L’éducation réservée aux adultes", "L’éducation que la loi oblige les enfants à suivre", "L’éducation interdite"], "answer": 2, "explain": "L’instruction obligatoire signifie que les enfants doivent aller à l’école jusqu’à un âge légal.", "src": "UNESCO"}, {"ch": 1, "q": "Qu’est-ce qu’un transfert monétaire conditionnel pour l’éducation ?", "options": ["De l’argent versé aux enseignants pour leurs vacances", "De l’argent versé uniquement par des donateurs pour les frais de scolarité", "De l’argent servant uniquement à construire des routes", "De l’argent versé aux familles si les enfants vont à l’école"], "answer": 3, "explain": "Les transferts monétaires conditionnels encouragent les familles à scolariser leurs enfants.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Pourquoi les gouvernements suppriment-ils les frais de scolarité ?", "options": ["Pour élargir l’accès des familles pauvres", "Pour réduire le nombre d’élèves", "Pour rendre les écoles moins utiles", "Pour arrêter le salaire des enseignants"], "answer": 0, "explain": "Supprimer les frais aide les enfants les plus pauvres à s’inscrire et à rester.", "src": "UNESCO"}, {"ch": 1, "q": "Qui sont les adolescents non scolarisés ?", "options": ["Des adultes qui étudient régulièrement en ligne depuis chez eux", "Des jeunes en âge d’être au secondaire qui ne sont pas scolarisés", "Des enfants de maternelle qui jouent dans le jardin toute la journée", "Des enseignants en congé de leur école cette année"], "answer": 1, "explain": "Les adolescents non scolarisés sont des jeunes qui ne sont inscrits dans aucun établissement.", "src": "UNESCO"}, {"ch": 1, "q": "Qu’est-ce que la scolarisation souple pour les enfants ?", "options": ["Une scolarisation sans aucune règle ni emploi du temps pour les enfants", "Une scolarisation uniquement la nuit pour toute la ville", "Une scolarisation organisée autour du travail ou des besoins de la famille", "Une scolarisation sans enseignant présent dans la salle à aucun moment"], "answer": 2, "explain": "La scolarisation souple aide les enfants qui ne peuvent pas être à l’école à plein temps.", "src": "UNESCO"}, {"ch": 1, "q": "Pourquoi un transport sûr est-il important pour la scolarisation des filles ?", "options": ["Le transport n’est jamais nécessaire pour un trajet scolaire", "Les filles ne peuvent se déplacer nulle part en dehors de leur foyer", "Les filles préfèrent marcher très loin pour rejoindre l’école", "Des trajets dangereux ou longs peuvent retenir les filles à la maison"], "answer": 3, "explain": "Un transport sûr peut faire une grande différence pour l’assiduité des filles.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 1, "q": "Qu’est-ce qu’une campagne d’inscription ?", "options": ["Une campagne pour amener les enfants à l’école", "Une course automobile", "Uniquement un dîner de collecte de fonds pour l’école", "Un tournoi sportif"], "answer": 0, "explain": "Les campagnes d’inscription encouragent les familles à inscrire leurs enfants à l’école.", "src": "UNESCO"}, {"ch": 2, "q": "Que signifie achever le premier cycle du secondaire ?", "options": ["Terminer la maternelle", "Terminer la première étape du secondaire", "Terminer l’université", "Terminer un stage de vacances"], "answer": 1, "explain": "Le premier cycle du secondaire est la première étape de l’enseignement secondaire.", "src": "UNESCO"}, {"ch": 2, "q": "Pourquoi les adolescents abandonnent-ils l’école dans de nombreux pays ?", "options": ["Ils terminent l’école trop vite et trop tôt chaque année", "Ils obtiennent tous une bourse pour les meilleures écoles", "La pression du travail, le coût et un apprentissage jugé inutile", "Ils ont beaucoup trop de vacances et de jours libres pendant l’année"], "answer": 2, "explain": "La pression du travail, le coût et un apprentissage jugé inutile poussent souvent les élèves à quitter l’école.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "Qu’est-ce qu’un parcours d’apprentissage pour les jeunes qui ont quitté l’école ?", "options": ["Une voie vers un magasin où l’on vend des produits aux clients", "Une voie qui ne mène à aucune qualification", "Une voie réservée aux enseignants et au personnel qualifié", "Une voie pour reprendre des études avec des qualifications reconnues"], "answer": 3, "explain": "Les parcours aident les jeunes à reprendre leurs études et à obtenir des qualifications.", "src": "UNESCO"}, {"ch": 2, "q": "Pourquoi l’achèvement du second cycle du secondaire est-il lié à l’emploi ?", "options": ["Il ouvre davantage de possibilités d’emploi et de formation", "Il supprime toutes les possibilités d’emploi", "Il signifie qu’il n’y a plus d’apprentissage ensuite", "Il n’aide que les artistes"], "answer": 0, "explain": "Achever le second cycle du secondaire élargit l’accès à l’emploi et aux études supérieures.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Qu’est-ce qu’une intervention en milieu scolaire pour garder les enfants à l’école ?", "options": ["Fermer l’école plus tôt chaque jour de la semaine", "Une action de soutien dans l’établissement, comme le tutorat", "Supprimer tous les cours de l’emploi du temps chaque semaine", "Ignorer les élèves absents depuis des semaines"], "answer": 1, "explain": "Le soutien en milieu scolaire aide les élèves exposés au risque de décrochage.", "src": "UNESCO"}, {"ch": 2, "q": "Pourquoi le soutien financier et alimentaire est-il lié à l’achèvement des études ?", "options": ["Il remplace tout l’enseignement dispensé en classe", "Il fait quitter l’école à davantage d’enfants chaque année", "Il réduit les coûts qui poussent les enfants hors de l’école", "Il rend la journée scolaire beaucoup plus longue et fatigante"], "answer": 2, "explain": "Une aide pour les coûts peut permettre aux enfants de rester jusqu’au bout.", "src": "UNESCO"}, {"ch": 2, "q": "Pourquoi certains élèves abandonnent-ils après des échecs répétés aux examens ?", "options": ["Les examens ne sont jamais échoués", "Échouer aux examens aide les élèves", "L’échec est récompensé", "Des échecs répétés peuvent décourager les apprenants"], "answer": 3, "explain": "Des échecs répétés sans soutien peuvent faire perdre confiance et conduire à quitter l’école.", "src": "UNESCO"}, {"ch": 3, "q": "Qu’est-ce que l’enseignement au niveau approprié ?", "options": ["Regrouper les apprenants selon leur niveau de compétence plutôt que selon leur âge", "Enseigner uniquement aux élèves les plus âgés", "Enseigner uniquement en anglais", "Enseigner sans aucun plan"], "answer": 0, "explain": "L’enseignement au niveau approprié regroupe les apprenants selon ce qu’ils savent déjà faire.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Qu’est-ce que l’apprentissage fondamental ?", "options": ["La recherche universitaire avancée en sciences, en droit et en médecine", "La lecture, l’écriture et le calcul de base qui soutiennent les apprentissages ultérieurs", "Uniquement l’éducation physique et le sport toute l’année scolaire", "Uniquement l’histoire de l’art et l’étude de la peinture et de la sculpture anciennes"], "answer": 1, "explain": "L’apprentissage fondamental est la base de toute la suite de l’éducation.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Quelle étude internationale évalue la lecture à l’école primaire ?", "options": ["PISA", "TIMSS", "PIRLS", "Test OACI"], "answer": 2, "explain": "PIRLS, l’Étude internationale sur les progrès en lecture, évalue la lecture à l’école primaire.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Que mesure TIMSS ?", "options": ["La musique et la danse", "Le sport et la condition physique", "Les compétences culinaires", "Les acquis en mathématiques et en sciences"], "answer": 3, "explain": "TIMSS, l’Étude sur les tendances internationales en mathématiques et en sciences, mesure les acquis en mathématiques et en sciences.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Qu’est-ce qu’une évaluation à faibles enjeux ?", "options": ["Une évaluation dont les résultats ne décident pas de l’avenir de l’élève", "Une évaluation qui décide qui est exclu", "Une évaluation sans aucune question", "Une évaluation utilisée seulement pour recruter des enseignants"], "answer": 0, "explain": "Les évaluations à faibles enjeux permettent aux enseignants de voir les apprentissages sans forte pression.", "src": "UNESCO"}, {"ch": 3, "q": "Pourquoi les résultats d’apprentissage diffèrent-ils au sein d’un même pays ?", "options": ["Seule la météo fait varier les résultats d’une école à l’autre", "Le revenu, la langue, le lieu et le genre jouent un rôle", "Seule la couleur de l’école détermine les performances des élèves", "Seul l’horaire du bus détermine les performances des élèves"], "answer": 1, "explain": "Les résultats d’apprentissage sont façonnés par de nombreux facteurs sociaux et économiques.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Qu’est-ce qu’une compétence cognitive dans l’apprentissage ?", "options": ["Des compétences pour bien dormir chaque nuit", "Des compétences pour jouer au football dans l’équipe de l’école toute l’année", "Des capacités de pensée comme la mémoire, le raisonnement et la résolution de problèmes", "Des compétences pour cuisiner des repas simples à la maison pour la famille"], "answer": 2, "explain": "Les compétences cognitives soutiennent le raisonnement et les apprentissages dans toutes les disciplines.", "src": "UNESCO"}, {"ch": 3, "q": "Pourquoi les évaluations des apprentissages sont-elles importantes pour les politiques ?", "options": ["Elles remplacent les écoles dans chaque communauté du pays", "Elles ne récompensent que les meilleurs élèves chaque année", "Elles suppriment le besoin d’enseignants dans chaque école", "Elles montrent où les apprentissages sont les plus faibles et ont besoin de soutien"], "answer": 3, "explain": "Les données d’évaluation aident les gouvernements à décider où investir et apporter leur soutien.", "src": "UNESCO GEM Report 2026"}, {"ch": 4, "q": "Quelles sont les quatre C des compétences du XXIe siècle ?", "options": ["Créativité, pensée critique, communication et collaboration", "Cuisiner, nettoyer, faire du vélo et colorier à l’école chaque semaine", "Calculer, compter, copier et coder dans la salle informatique", "Encourager, entraîner, concourir et cuisiner pour l’équipe de l’école"], "answer": 0, "explain": "Les quatre C décrivent largement les compétences clés pour le travail et la vie modernes.", "src": "UNESCO"}, {"ch": 4, "q": "Que signifie STEM ?", "options": ["Sports, enseignement, examens et musique", "Sciences, technologie, ingénierie et mathématiques", "Expression orale, théâtre, édition et marchés", "Sociologie, tourisme, économie et médias"], "answer": 1, "explain": "STEM englobe les sciences, la technologie, l’ingénierie et les mathématiques.", "src": "UNESCO"}, {"ch": 4, "q": "Qu’est-ce que la sécurité numérique pour les apprenants ?", "options": ["Partager ses mots de passe avec toutes les personnes rencontrées en ligne", "Ignorer la vie privée en ligne et partager chaque photo", "Protéger ses données personnelles et reconnaître les risques en ligne", "Rencontrer en personne des inconnus rencontrés en ligne et garder le secret"], "answer": 2, "explain": "La sécurité numérique aide les apprenants à protéger leurs informations et à rester en sécurité en ligne.", "src": "UNESCO"}, {"ch": 4, "q": "Qu’est-ce qu’un usage éthique de la technologie dans l’apprentissage ?", "options": ["Copier le travail des autres sans les citer", "Harceler ses camarades en ligne", "Partager des photos privées", "L’utiliser avec honnêteté, respect et consentement"], "answer": 3, "explain": "Un usage éthique de la technologie respecte les autres et l’honnêteté académique.", "src": "UNESCO"}, {"ch": 4, "q": "Qu’est-ce qu’un référentiel de compétences ?", "options": ["Une liste des compétences et des connaissances qu’un apprenant doit acquérir", "Un type de bâtiment scolaire à plusieurs étages et salles", "Une liste d’activités sportives, de jeux et de clubs scolaires", "Un plan uniquement pour les examens et les tests, sans autre apprentissage"], "answer": 0, "explain": "Les référentiels de compétences précisent ce que les apprenants doivent savoir faire.", "src": "UNESCO"}, {"ch": 4, "q": "Pourquoi l’esprit d’entreprendre est-il lié à l’ODD 4 ?", "options": ["Il n’a aucun lien avec l’emploi ni la résolution de problèmes", "Il développe les compétences pour créer des emplois et résoudre des problèmes", "Il enseigne uniquement la vente et la gestion de magasin", "Il empêche les gens de trouver du travail"], "answer": 1, "explain": "L’esprit d’entreprendre développe l’initiative et la capacité à résoudre des problèmes.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Qu’est-ce qu’un déficit de compétences ?", "options": ["Une fissure dans un mur d’école qui doit être réparée ce trimestre", "Une pause entre deux longs cours lors d’une journée scolaire chargée", "Un décalage entre les compétences des personnes et les besoins des emplois", "Un examen manquant dans l’emploi du temps scolaire de ce trimestre"], "answer": 2, "explain": "Les déficits de compétences rendent difficile la recherche d’emploi pour les personnes et le recrutement pour les employeurs.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Pourquoi l’EFTP est-elle importante pour l’emploi des jeunes ?", "options": ["Elle remplace tout l’apprentissage académique", "Elle n’est réservée qu’aux adultes", "Elle n’est jamais utile", "Elle offre des compétences pratiques liées à l’emploi"], "answer": 3, "explain": "L’EFTP donne aux jeunes des compétences immédiatement utiles et des voies d’accès à l’emploi.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Qu’est-ce qu’un obstacle à l’apprentissage lié au genre ?", "options": ["Une règle ou une norme qui rend l’apprentissage plus difficile pour un genre", "Un obstacle qui aide chaque élève à mieux apprendre", "Un obstacle qui touche seulement les enseignants de l’école", "Un obstacle qui n’a aucun effet réel sur l’apprentissage"], "answer": 0, "explain": "Les obstacles liés au genre comprennent les normes et pratiques qui limitent l’apprentissage des filles ou des garçons.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Comment le manque d’installations d’hygiène peut-il affecter les filles à l’école ?", "options": ["Cela n’a aucun lien avec l’assiduité scolaire dans aucun pays", "Les filles peuvent manquer l’école sans toilettes privées ni produits d’hygiène", "Cela touche seulement les garçons qui étudient dans la même école", "C’est une matière enseignée aux élèves de troisième"], "answer": 1, "explain": "L’accès à l’hygiène et à des toilettes privées aide les filles à rester à l’école.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Quel est l’objectif d’une politique de lutte contre le travail des enfants ?", "options": ["Obliger les enfants à travailler de longues heures dans les champs chaque jour", "Interdire toute éducation pour les enfants du village et de la ville", "Protéger les enfants contre un travail qui nuit à leur apprentissage et à leur santé", "Payer les enfants pour qu’ils sèchent l’école et restent à la maison"], "answer": 2, "explain": "Les politiques de lutte contre le travail des enfants protègent leur droit d’apprendre et d’être en bonne santé.", "src": "UNESCO"}, {"ch": 5, "q": "Que signifie groupe minoritaire dans l’éducation ?", "options": ["Un groupe toujours le plus riche", "Un groupe toujours le meilleur aux examens", "Un groupe qui ne fréquente jamais l’école", "Un groupe plus petit que la population principale"], "answer": 3, "explain": "Un groupe minoritaire est un groupe plus petit au sein d’une population, qui peut faire face à des obstacles.", "src": "UNESCO"}, {"ch": 5, "q": "Pourquoi les apprenants autochtones ont-ils souvent besoin d’une éducation culturellement adaptée ?", "options": ["Elle respecte leur identité et améliore l’apprentissage", "Elle remplace entièrement leur langue par une autre", "Elle n’est nécessaire dans aucune école, nulle part", "Elle concerne seulement le sport et les jeux à l’école"], "answer": 0, "explain": "Une éducation culturellement adaptée aide les apprenants autochtones à se sentir valorisés et à mieux apprendre.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Qu’est-ce que le ciblage dans une politique d’équité ?", "options": ["Donner des ressources aux plus riches", "Concentrer les ressources sur les groupes laissés pour compte", "Donner les mêmes ressources aux seuls plus forts", "Ignorer les groupes dans le besoin"], "answer": 1, "explain": "Le ciblage concentre les efforts sur les groupes les plus dans le besoin.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Qu’est-ce qu’un programme scolaire sensible au genre ?", "options": ["Un programme réservé aux garçons, enseigné dans toutes les écoles", "Un programme qui enseigne des stéréotypes sur les filles et les garçons", "Un programme qui évite les stéréotypes et traite tous les apprenants de manière égale", "Un programme sans aucune matière pour les élèves"], "answer": 2, "explain": "Les programmes sensibles au genre remettent en cause les stéréotypes et soutiennent tous les apprenants.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Que décrit la discrimination intersectionnelle ?", "options": ["Une discrimination en un seul lieu", "Une discrimination toujours juste", "Une discrimination uniquement contre les enseignants", "Plusieurs formes de discrimination qui se superposent"], "answer": 3, "explain": "La discrimination intersectionnelle survient lorsque plusieurs identités se combinent pour créer un désavantage.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "Qu’est-ce que l’offre d’enseignants dans la cible 4.c ?", "options": ["Le nombre d’enseignants qualifiés disponibles", "Le nombre de vacances", "Le nombre de sonneries d’école", "Le nombre de bureaux"], "answer": 0, "explain": "La cible 4.c vise à augmenter l’offre d’enseignants qualifiés.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "Pourquoi les pays doivent-ils recruter davantage d’enseignants ?", "options": ["Parce que les enseignants ne sont pas nécessaires", "Pour répondre à une demande croissante et remplacer ceux qui partent", "Pour réduire les effectifs des classes à zéro", "Pour fermer des écoles"], "answer": 1, "explain": "Le recrutement est nécessaire pour suivre la hausse des effectifs et les départs à la retraite.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce que l’enseignement sous contrat ?", "options": ["Un enseignement sous promesse d’emploi à vie", "Un enseignement sans aucune rémunération", "Un enseignement sous contrats courts et temporaires", "Un enseignement uniquement par téléphone"], "answer": 2, "explain": "Les enseignants contractuels ont souvent moins de sécurité, ce qui peut affecter leur maintien dans le métier.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Que signifie la formation initiale des enseignants ?", "options": ["La formation après la retraite", "La formation réservée aux chefs d’établissement", "La formation destinée aux parents", "La formation avant de commencer à enseigner"], "answer": 3, "explain": "La formation initiale prépare les personnes avant qu’elles ne commencent à enseigner.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Que signifie la formation continue des enseignants ?", "options": ["La formation suivie pendant qu’on enseigne déjà", "La formation pour les personnes qui n’enseignent pas", "La formation uniquement pendant les vacances, imposée par la loi", "La formation qui remplace tout l’enseignement"], "answer": 0, "explain": "La formation continue aide les enseignants à progresser en continu dans leur travail.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce qu’un code de conduite des enseignants ?", "options": ["Un langage secret des enseignants que seul le personnel utilise", "Des règles qui fixent le comportement professionnel attendu", "Une liste des vacances des enseignants pour toute l’année", "Une règle vestimentaire scolaire qui ne s’applique qu’aux enseignants"], "answer": 1, "explain": "Les codes de conduite définissent la manière dont les enseignants doivent se comporter envers les apprenants.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Pourquoi les enseignants ont-ils besoin d’une formation à l’enseignement inclusif ?", "options": ["Elle n’est pas nécessaire", "Pour pouvoir éviter les apprenants", "Pour accompagner des apprenants aux besoins différents", "Pour pouvoir enseigner moins de matières"], "answer": 2, "explain": "La formation inclusive aide les enseignants à répondre à une grande diversité de besoins.", "src": "UN CRPD (2006), Article 24"}, {"ch": 6, "q": "Qu’est-ce que l’épuisement professionnel des enseignants ?", "options": ["Des enseignants trop dynamiques", "Des enseignants qui enseignent trop bien", "Des enseignants trop bien payés", "Un épuisement durable causé par un travail stressant"], "answer": 3, "explain": "L’épuisement réduit le bien-être et peut pousser les enseignants à quitter le métier.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "Que mesure l’écart de financement de l’ODD 4 ?", "options": ["Les dépenses supplémentaires nécessaires au-delà des dépenses actuelles", "L’argent dépensé pour le sport", "L’argent épargné dans les banques", "L’argent versé aux vendeurs de l’école"], "answer": 0, "explain": "L’écart de financement indique le montant supplémentaire nécessaire pour atteindre les objectifs éducatifs.", "src": "UNESCO GEM Report 2026"}, {"ch": 7, "q": "Quelle est la contribution des recettes fiscales à l’éducation ?", "options": ["L’argent qui paie uniquement les vacances", "L’argent que les gouvernements utilisent pour financer les écoles", "L’argent qui remplace les enseignants", "L’argent toujours gaspillé"], "answer": 1, "explain": "Les recettes fiscales sont une source principale de financement public de l’éducation.", "src": "UNESCO"}, {"ch": 7, "q": "Qu’est-ce que le financement hors budget de l’éducation ?", "options": ["Des fonds dépensés pour les vacances", "De l’argent gardé sous le matelas", "Des fonds dépensés en dehors du budget officiel", "De l’argent dépensé pour des jets privés"], "answer": 2, "explain": "Le financement hors budget peut compliquer le suivi des dépenses totales d’éducation.", "src": "UNESCO"}, {"ch": 7, "q": "Pourquoi les donateurs financent-ils parfois l’éducation ?", "options": ["Pour réaliser un grand bénéfice en gérant des écoles pour enfants", "Pour fermer chaque année des écoles dans les pays les plus pauvres", "Pour empêcher les enfants d’apprendre dans n’importe quelle école", "Pour soutenir les enfants dans les pays disposant de moins de ressources"], "answer": 3, "explain": "Les donateurs financent souvent l’éducation pour aider les pays qui ont besoin d’un soutien supplémentaire.", "src": "UNESCO"}, {"ch": 7, "q": "Comment la dette peut-elle affecter les dépenses d’éducation ?", "options": ["Des remboursements élevés peuvent réduire l’argent destiné aux écoles", "La dette finance automatiquement les écoles", "La dette n’a aucun effet", "La dette affecte seulement le sport"], "answer": 0, "explain": "Les gouvernements qui consacrent beaucoup au remboursement de la dette peuvent disposer de moins de fonds pour l’éducation.", "src": "UNESCO"}, {"ch": 7, "q": "Qu’est-ce qu’un audit de rentabilité dans l’éducation ?", "options": ["Une vérification du prix et de la qualité des uniformes scolaires", "Une vérification que les dépenses produisent de bons résultats", "Une vérification du nombre de jours de congé pris par chaque enseignant", "Une vérification des repas servis chaque jour à la cantine"], "answer": 1, "explain": "Les audits de rentabilité vérifient si l’argent de l’éducation produit des résultats d’apprentissage.", "src": "UNESCO"}, {"ch": 7, "q": "Pourquoi les écoles ont-elles besoin d’un financement stable ?", "options": ["Pour changer le climat", "Pour se passer de tous les enseignants", "Pour planifier les enseignants, le matériel et les réparations", "Pour fermer plus tôt"], "answer": 2, "explain": "Un financement stable permet aux écoles de planifier à l’avance et de poursuivre les apprentissages.", "src": "UNESCO"}, {"ch": 7, "q": "À quoi sert une subvention au niveau de l’école ?", "options": ["Donner des vacances aux enseignants", "Donner uniquement des prix aux enfants", "Donner des voitures aux familles", "Donner aux écoles des fonds pour répondre aux besoins locaux"], "answer": 3, "explain": "Les subventions scolaires permettent aux écoles de répondre aux priorités locales.", "src": "UNESCO"}, {"ch": 8, "q": "Quelle déclaration de 1994 a promu les écoles inclusives pour tous les enfants ?", "options": ["La Déclaration de Salamanque", "La Déclaration de Tokyo", "Le Pacte du Caire", "Le Plan de Lima"], "answer": 0, "explain": "La Déclaration de Salamanque de 1994 a promu les écoles inclusives pour tous les enfants.", "src": "UN CRPD (2006), Article 24"}, {"ch": 8, "q": "En quelle année la Déclaration de Salamanque a-t-elle été adoptée ?", "options": ["1948", "1994", "1989", "2015"], "answer": 1, "explain": "La Déclaration de Salamanque a été adoptée en 1994.", "src": "UN CRPD (2006), Article 24"}, {"ch": 8, "q": "Que demandait la conférence de Jomtien de 1990 au-delà de la scolarisation ?", "options": ["Uniquement l’école pour les adultes", "Uniquement le sport", "L’apprentissage pour les enfants, les jeunes et les adultes", "Aucun apprentissage après dix ans"], "answer": 2, "explain": "Jomtien a mis l’accent sur l’apprentissage tout au long de la vie pour tous.", "src": "UNESCO"}, {"ch": 8, "q": "Combien d’objectifs le Cadre d’action de Dakar a-t-il fixés pour l’Éducation pour tous ?", "options": ["Trois", "Dix", "Dix-sept", "Six"], "answer": 3, "explain": "Le Cadre d’action de Dakar a fixé six objectifs pour l’Éducation pour tous.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "Que disait la Déclaration universelle des droits de l’homme de 1948 sur l’éducation ?", "options": ["C’est un droit humain", "C’est un luxe", "C’est réservé aux garçons", "C’est facultatif"], "answer": 0, "explain": "La DUDH affirme que l’éducation est un droit humain.", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "Pourquoi la conférence de Jomtien de 1990 était-elle importante ?", "options": ["Elle a interdit toutes les écoles du pays", "Elle a fixé l’engagement mondial pour l’Éducation pour tous", "Elle a fixé le prix des livres dans toutes les boutiques de la ville", "Elle a mis fin à la formation des enseignants dans la plupart des pays cette année-là"], "answer": 1, "explain": "Jomtien a fixé l’engagement mondial pour l’Éducation pour tous.", "src": "UNESCO"}, {"ch": 8, "q": "Qu’ont en commun les grands engagements mondiaux en éducation ?", "options": ["Ils ne sont jamais respectés", "Ils concernent uniquement les écoles privées", "Ils fixent des objectifs que les gouvernements acceptent de poursuivre", "Ils ne s’appliquent qu’à un seul pays"], "answer": 2, "explain": "Les engagements mondiaux fixent des objectifs communs que les gouvernements acceptent d’atteindre.", "src": "UNESCO"}, {"ch": 8, "q": "Quand a lieu la Journée internationale de l’éducation ?", "options": ["1er mai", "31 octobre", "25 décembre", "24 janvier"], "answer": 3, "explain": "L’UNESCO célèbre la Journée internationale de l’éducation chaque année le 24 janvier.", "src": "UNESCO"}, {"ch": 9, "q": "Qu’est-ce que le Cadre pour des soins bienveillants ?", "options": ["Un cadre réunissant santé, nutrition, soins et apprentissage dans la petite enfance", "Un plan pour construire des écoles uniquement dans les grandes villes du pays", "Une liste de règles et de punitions scolaires pour les jeunes enfants", "Un plan de sport et de jeux dans la cour chaque semaine"], "answer": 0, "explain": "Le cadre relie la santé, la nutrition, les soins attentionnés, la sécurité et l’apprentissage dans la petite enfance.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "Que signifie l’architecture cérébrale dans la petite enfance ?", "options": ["La forme d’un bâtiment scolaire", "La manière dont les connexions cérébrales se forment dès le plus jeune âge", "La conception des pupitres", "L’organisation d’une ville"], "answer": 1, "explain": "Les expériences précoces façonnent les connexions qui constituent l’architecture du cerveau.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Qu’est-ce que l’implication des parents dans l’apprentissage précoce ?", "options": ["Des parents qui n’assistent jamais aux événements scolaires", "Des parents qui paient des enseignants pour donner des cours particuliers à leurs enfants", "Des parents qui participent activement à l’apprentissage de leurs enfants", "Des parents qui évitent complètement leurs enfants et leurs devoirs"], "answer": 2, "explain": "Des parents impliqués soutiennent l’apprentissage à la maison comme à l’école.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Qu’est-ce que le jeu et l’exploration dans la petite enfance ?", "options": ["Rester assis pendant des heures sans bouger en classe", "Recopier au tableau pendant toute la leçon", "Des exercices silencieux répétés chaque jour à l’école", "Des activités pratiques qui aident les enfants à découvrir des idées"], "answer": 3, "explain": "Le jeu et l’exploration aident les enfants à découvrir le monde.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Qu’est-ce qui rend l’éducation de la petite enfance de haute qualité ?", "options": ["Un personnel formé, de bons espaces et des interactions chaleureuses", "De grandes classes sans adulte dans la salle", "Uniquement des fiches distribuées sans enseignement", "De longues heures de silence sans adultes ni activités"], "answer": 0, "explain": "La qualité repose sur un personnel qualifié, des espaces sûrs et des relations chaleureuses.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "Qu’est-ce que l’attachement dans la petite enfance ?", "options": ["Un type de jouet", "Un lien sécurisant entre un enfant et son référent", "Un emploi du temps scolaire fixe", "Un impôt pour les familles"], "answer": 1, "explain": "Un attachement sécurisant favorise le développement émotionnel et social de l’enfant.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Qu’est-ce que la préparation à l’école inclut au-delà des compétences scolaires ?", "options": ["Uniquement lire des mots à voix haute chaque jour", "Uniquement écrire des lettres et des chiffres sur papier pendant des heures", "La santé, le bien-être émotionnel et les compétences sociales", "Uniquement la force physique et la vitesse dans les courses chaque trimestre"], "answer": 2, "explain": "La préparation englobe la santé, les compétences sociales et émotionnelles, et pas seulement les compétences scolaires.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "Qu’est-ce qu’un environnement favorable à la lecture à la maison ?", "options": ["Des pièces silencieuses sans aucun livre", "Uniquement la télévision", "Aucun contact avec la famille", "Des livres, des échanges et une routine de lecture à la maison"], "answer": 3, "explain": "Un environnement favorable à la lecture à la maison soutient les compétences de lecture.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Qu’est-ce qu’une culture de la lecture ?", "options": ["Des habitudes partagées et la valeur accordée à la lecture", "Un type de danse présenté dans les salles de l’école", "Un sport pratiqué sur le terrain de l’école", "Un système de sonnerie scolaire utilisé toute la journée"], "answer": 0, "explain": "Une culture de la lecture fait de la lecture une partie du quotidien.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "Pourquoi les adultes peu lettrés ont-ils du mal à trouver du travail ?", "options": ["Les emplois ne demandent jamais de lire", "De nombreux emplois exigent de savoir lire et écrire", "Les adultes ne trouvent pas de travail de toute façon", "Les employeurs préfèrent l’illettrisme"], "answer": 1, "explain": "Un faible niveau de littératie peut limiter l’accès à de nombreux emplois et formations.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Qu’est-ce que la littératie post-primaire ?", "options": ["La littératie avant la naissance", "La littératie uniquement en maternelle", "Les compétences de lecture et d’écriture acquises après l’école primaire", "La littératie uniquement pour les enseignants"], "answer": 2, "explain": "La littératie post-primaire développe et entretient la lecture et l’écriture après l’école primaire.", "src": "UNESCO"}, {"ch": 10, "q": "Quelle est une cause de difficulté de lecture ?", "options": ["Un type de régime alimentaire", "Un type d’examen", "Un type de temps", "La dyslexie"], "answer": 3, "explain": "Certaines difficultés de lecture sont causées par la dyslexie, qui nécessite un soutien spécialisé.", "src": "UN CRPD (2006), Article 24"}, {"ch": 10, "q": "Qu’est-ce qui aide les communautés rurales à accéder aux livres ?", "options": ["Des bibliothèques à proximité ou la livraison de livres", "L’interdiction des livres", "La vente de livres à des prix très élevés", "Garder les livres uniquement dans les villes"], "answer": 0, "explain": "L’accès aux livres en zone rurale peut être amélioré grâce aux bibliothèques et aux services itinérants.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "Qu’est-ce qu’une bibliothèque itinérante ?", "options": ["Une bibliothèque installée uniquement dans un parking", "Une bibliothèque qui se déplace vers les communautés", "Une bibliothèque qui vend des téléphones portables", "Une bibliothèque fermée au public"], "answer": 1, "explain": "Les bibliothèques itinérantes apportent les livres aux personnes qui vivent loin des bibliothèques.", "src": "UNESCO"}, {"ch": 11, "q": "Que couvre l’article 24 de la CDPH de l’ONU ?", "options": ["Les sports et les jeux pour tous les élèves", "La cuisine et l’alimentation des familles à la maison", "L’éducation, y compris l’éducation inclusive", "Les vacances et le tourisme pour les groupes scolaires"], "answer": 2, "explain": "L’article 24 de la CDPH de l’ONU établit le droit à une éducation inclusive.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Que signifie l’accessibilité pour les écoles ?", "options": ["Une seule porte à l’entrée du bâtiment pour tous", "Des supports que seuls les enseignants ont le droit de lire", "Des informations gardées secrètes auprès des familles des élèves", "Des bâtiments, des supports et des informations que chacun peut utiliser"], "answer": 3, "explain": "L’accessibilité rend les espaces et les informations scolaires utilisables par tous.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Qu’est-ce que la pédagogie inclusive ?", "options": ["Des méthodes d’enseignement conçues pour inclure chaque apprenant", "Enseigner chaque jour uniquement aux meilleurs élèves de chaque classe", "Enseigner d’une seule façon fixe, censée convenir à tous les apprenants", "Enseigner sans aucun matériel ni ressource dans la salle"], "answer": 0, "explain": "La pédagogie inclusive adapte l’enseignement pour que tous participent et apprennent.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Pourquoi les écoles ont-elles besoin de personnel d’accompagnement pour l’inclusion ?", "options": ["Le personnel d’accompagnement n’est pas nécessaire", "Pour aider les apprenants à accéder aux cours et à la vie quotidienne", "Pour remplacer tous les enseignants", "Pour tenir les apprenants à l’écart les uns des autres"], "answer": 1, "explain": "Le personnel d’accompagnement aide les apprenants en situation de handicap à participer à la vie scolaire.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Qu’est-ce que l’environnement le moins restrictif ?", "options": ["La salle de classe la plus bondée de tout le bâtiment scolaire", "La salle la plus éloignée de toutes les autres classes", "Le cadre dans lequel un apprenant peut apprendre avec le plus d’inclusion", "La salle sans fenêtres, sans lumière et sans sièges"], "answer": 2, "explain": "L’environnement le moins restrictif favorise l’apprentissage avec le plus d’inclusion possible.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Que signifie la participation pleine et entière pour les apprenants en situation de handicap ?", "options": ["Venir uniquement les jours spéciaux", "Regarder de l’extérieur", "Être maintenu dans une salle séparée", "Prendre part sur un pied d’égalité à tous les aspects de la vie scolaire"], "answer": 3, "explain": "La participation pleine et entière signifie que les apprenants peuvent prendre part à toutes les activités et à tous les apprentissages.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Qu’est-ce que le modèle social du handicap ?", "options": ["Le handicap est façonné par les obstacles de la société", "Le handicap est une faute personnelle", "Le handicap peut être ignoré à l’école", "Le handicap concerne seulement le travail"], "answer": 0, "explain": "Le modèle social affirme que ce sont les obstacles de la société, et pas seulement la déficience, qui limitent la participation.", "src": "UN CRPD (2006), Article 24"}, {"ch": 0, "q": "Quel est le lien entre l’ODD 4 et l’ODD 5 (Égalité des genres) ?", "options": ["Il n’existe aucun lien", "L’éducation des filles soutient l’égalité des genres", "L’égalité des genres réduit l’apprentissage", "Les filles ne devraient pas étudier"], "answer": 1, "explain": "L’éducation est un outil clé de l’égalité des genres, qui est l’Objectif 5.", "src": "UN 2030 Agenda (2015)"}], "11": [{"ch": 0, "q": "Comment l’Agenda 2030 décrit-il le lien entre les objectifs ?", "options": ["Intégrés et indivisibles", "Séparés et sans lien", "En concurrence et en conflit", "Facultatifs et ignorés"], "answer": 0, "explain": "L’Agenda 2030 décrit les objectifs comme intégrés et indivisibles.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Que fournit un système national de suivi de l’éducation ?", "options": ["Uniquement les dates de vacances de chaque école de l’année", "Des données régulières pour suivre les progrès et repérer les écarts", "Uniquement les prix d’examen pour les meilleurs élèves de chaque classe", "Uniquement les plans des bâtiments des nouvelles écoles de la ville"], "answer": 1, "explain": "Les systèmes de suivi collectent des données pour que les gouvernements voient les progrès et les écarts.", "src": "UNESCO GEM Report 2026"}, {"ch": 0, "q": "Qu’est-ce qu’un SIGE ?", "options": ["Un ensemble d’instruments de musique électroniques utilisés dans les fanfares scolaires", "Un outil de correction d’examens utilisé uniquement par les enseignants en fin d’année", "Un système d’information pour la gestion de l’éducation qui collecte les données des écoles", "Un plan de gestion de l’énergie pour tous les bâtiments scolaires"], "answer": 2, "explain": "SIGE signifie système d’information pour la gestion de l’éducation, qui enregistre les données des écoles et des apprenants.", "src": "UNESCO GEM Report 2026"}, {"ch": 0, "q": "Qu’est-ce que la cohérence des politiques pour le développement durable ?", "options": ["Chaque secteur ignore les autres et travaille entièrement seul", "Des politiques qui se contredisent volontairement chaque année", "Des politiques qui s’arrêtent exactement aux limites de chaque district", "Aligner les politiques de différents secteurs pour qu’elles se soutiennent mutuellement"], "answer": 3, "explain": "La cohérence des politiques signifie que différents domaines travaillent ensemble vers les mêmes objectifs.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Que signifie la localisation de l’ODD 4 ?", "options": ["Adapter les objectifs aux priorités et aux contextes locaux", "Copier exactement le plan d’un seul pays", "Ignorer les besoins locaux", "Déplacer les écoles sur la Lune"], "answer": 0, "explain": "La localisation aide les communautés à adapter les objectifs mondiaux à leur propre situation.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Qu’est-ce que la redevabilité dans la politique éducative ?", "options": ["Éviter toute responsabilité pour les résultats de l’école", "Tenir les responsables comptables des résultats et des dépenses", "Cacher les résultats au public et à la presse", "Accuser uniquement les élèves de chaque échec en classe"], "answer": 1, "explain": "La redevabilité signifie que les responsables rendent compte de l’usage des ressources éducatives.", "src": "UNESCO"}, {"ch": 0, "q": "Qu’est-ce que l’implication de multiples parties prenantes dans l’éducation ?", "options": ["Associer uniquement les responsables de l’État à chaque décision", "Associer uniquement les entreprises privées et leur personnel", "Associer l’État, les familles, les enseignants et les communautés", "N’associer personne d’autre que les élèves aux décisions prises"], "answer": 2, "explain": "Les approches multipartenaires réunissent plusieurs groupes pour planifier et suivre l’éducation.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Qu’est-ce qu’un plan sectoriel de l’éducation ?", "options": ["Un plan uniquement pour les terrains de sport et les cours de récréation de chaque commune", "Un emploi du temps pour une école d’un district pendant un trimestre", "Une liste des dates de vacances pour tout le pays chaque année", "Un plan qui fixe les priorités et les actions pour l’éducation"], "answer": 3, "explain": "Les plans sectoriels guident la manière dont les gouvernements investissent et agissent dans l’éducation.", "src": "UNESCO"}, {"ch": 1, "q": "Qu’est-ce qu’une enquête sur les enfants non scolarisés ?", "options": ["Une enquête qui repère les enfants qui ne sont pas scolarisés", "Une enquête sur les bus scolaires des grands axes de la ville", "Une enquête sur les vacances des enseignants dans tout le pays", "Une enquête sur les uniformes scolaires portés dans chaque ville chaque année"], "answer": 0, "explain": "Les enquêtes sur les enfants non scolarisés aident les gouvernements à localiser ceux qui doivent être inscrits.", "src": "UNESCO"}, {"ch": 1, "q": "Pourquoi l’accès universel demande-t-il plus que la construction d’écoles ?", "options": ["Construire des écoles suffit toujours à lui seul pour tous", "Le coût, la distance, la discrimination et la qualité comptent aussi", "L’accès dépend uniquement de la météo de chaque saison", "L’accès n’est jamais un problème pour aucune famille dans aucune région"], "answer": 1, "explain": "L’accès dépend de nombreux facteurs, et pas seulement du nombre de bâtiments scolaires.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Qu’est-ce que la scolarisation à l’âge adapté ?", "options": ["Des enfants inscrits dans n’importe quel niveau, quel que soit leur âge", "Des enfants qui ne sont jamais inscrits", "Des enfants inscrits dans le niveau correspondant à leur âge", "Des enfants inscrits uniquement à l’université"], "answer": 2, "explain": "La scolarisation à l’âge adapté aide les enfants à apprendre à un niveau approprié.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Qu’est-ce qu’un apprenant en retard d’âge ?", "options": ["Un enseignant trop âgé pour enseigner dans une classe aujourd’hui", "Un apprenant qui a terminé son niveau en avance et a quitté l’école", "Un apprenant dont la date de naissance n’est enregistrée dans aucun dossier", "Un apprenant plus âgé que l’âge normal de son niveau"], "answer": 3, "explain": "Les apprenants en retard d’âge ont souvent besoin de programmes flexibles pour rattraper leur retard.", "src": "UNESCO"}, {"ch": 1, "q": "Qu’est-ce que l’apprentissage à distance pendant la fermeture des écoles ?", "options": ["Apprendre à distance grâce à la technologie ou à des supports", "Apprendre uniquement dans la même salle que l’enseignant chaque jour", "Apprendre uniquement en silence, sans parler du tout", "Apprendre uniquement la nuit, lorsque les écoles sont fermées"], "answer": 0, "explain": "L’apprentissage à distance permet de poursuivre l’éducation lorsque les écoles ne peuvent pas ouvrir.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Pourquoi la fermeture des écoles nuit-elle aux apprentissages ?", "options": ["Elle n’a aucun effet", "Les enfants perdent du temps et risquent de prendre du retard", "Elle améliore toujours les apprentissages", "Elle ne touche que les enseignants"], "answer": 1, "explain": "Les fermetures prolongées peuvent entraîner une perte d’apprentissages, surtout chez les enfants défavorisés.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Qu’est-ce que l’inclusion numérique pour les apprenants ?", "options": ["Éviter toute technologie dans la vie quotidienne et dans toutes les tâches d’études", "Utiliser uniquement du papier et des crayons pour tous les cours chaque jour", "L’accès aux appareils, à la connexion et aux compétences pour les utiliser", "Posséder une voiture et la conduire à l’école avec des amis chaque jour"], "answer": 2, "explain": "L’inclusion numérique signifie que chacun peut accéder aux outils d’apprentissage numériques et les utiliser.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Pourquoi certains apprenants ont-ils du mal à étudier à la maison ?", "options": ["Ils préfèrent s’ennuyer", "Le foyer est toujours idéal", "Ils ne veulent pas apprendre", "Pas d’espace calme, d’appareils ni de soutien à la maison"], "answer": 3, "explain": "Les conditions à la maison influencent la façon dont les apprenants peuvent étudier à distance.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "Que signifie la continuité entre les niveaux ?", "options": ["Passer d’un niveau au suivant sans quitter l’école", "Redoubler le même niveau sans jamais passer au suivant", "Quitter l’école définitivement sans jamais revenir en classe", "Changer d’école dans un autre pays chaque année"], "answer": 0, "explain": "La continuité signifie que les apprenants progressent régulièrement d’un niveau à l’autre.", "src": "UNESCO"}, {"ch": 2, "q": "Qu’est-ce qu’une politique de prévention du décrochage ?", "options": ["Des mesures qui exclusent les apprenants", "Des mesures qui maintiennent à l’école les apprenants exposés au risque", "Des mesures qui ferment les écoles", "Des mesures qui ignorent les absences"], "answer": 1, "explain": "Les politiques de prévention du décrochage misent sur un soutien précoce aux apprenants à risque.", "src": "UNESCO"}, {"ch": 2, "q": "Que révèle un écart d’achèvement entre filles et garçons ?", "options": ["Quel groupe est en moyenne plus grand dans chaque école chaque année", "Quel groupe lit plus vite pendant chaque cours", "Si un groupe a moins de chances de terminer l’école", "Quel groupe aime beaucoup plus le sport que les autres"], "answer": 2, "explain": "Les écarts d’achèvement révèlent des inégalités qui appellent des politiques ciblées.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 2, "q": "Qu’est-ce qu’un programme de réinsertion pour anciens apprenants ?", "options": ["Un programme qui envoie des apprenants travailler à l’étranger", "Un programme qui met fin à la scolarité", "Un programme réservé aux enseignants", "Un programme qui aide d’anciens apprenants à reprendre le chemin de l’école"], "answer": 3, "explain": "Les programmes de réinsertion aident les apprenants à reprendre leur formation.", "src": "UNESCO"}, {"ch": 2, "q": "Que fait une bonne politique de transition pour les apprenants qui changent de système ?", "options": ["Elle rend les passages entre écoles ou niveaux plus fluides", "Elle rend les passages beaucoup plus difficiles pour chaque apprenant", "Elle arrête tous les passages entre écoles et niveaux", "Elle supprime les examens à la fin de chaque année scolaire"], "answer": 0, "explain": "Une bonne politique de transition réduit le risque de décrochage entre les niveaux.", "src": "UNESCO"}, {"ch": 2, "q": "Qu’est-ce que l’orientation précoce dans les écoles ?", "options": ["Suivre les enfants uniquement par GPS", "Répartir les apprenants dans des filières distinctes dès un jeune âge", "Enseigner la même chose à tous les enfants, à tous les âges", "Relever la météo"], "answer": 1, "explain": "L’orientation précoce peut limiter les opportunités futures et accroître les inégalités.", "src": "UNESCO"}, {"ch": 2, "q": "Pourquoi le regroupement par niveau pose-t-il problème pour l’équité ?", "options": ["Il aide toujours les apprenants les plus faibles", "Il n’a aucun effet sur l’équité", "Il peut enfermer les apprenants défavorisés dans des filières moins ambitieuses", "Il facilite les apprentissages pour tous"], "answer": 2, "explain": "Le regroupement précoce peut renforcer le désavantage s’il n’est pas souple.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "Que signifie la formule « finir ne suffit pas » ?", "options": ["Finir l’école est le seul objectif", "Les apprentissages n’ont pas d’importance", "Les écoles devraient fermer plus tôt", "Il faut aussi garantir la qualité des apprentissages"], "answer": 3, "explain": "Achever l’école est important, mais les apprenants doivent aussi bien apprendre.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Qu’est-ce que la valeur ajoutée dans la mesure des apprentissages ?", "options": ["Le progrès qu’une école apporte au-delà de ce que les apprenants avaient au départ", "L’argent qu’une école ajoute à son budget annuel chaque année", "Le poids de tous les livres rangés dans les étagères de l’école", "Le nombre d’enseignants recrutés par une école chaque année"], "answer": 0, "explain": "La valeur ajoutée mesure dans quelle mesure une école aide les apprenants à progresser.", "src": "UNESCO"}, {"ch": 3, "q": "Comment appelle-t-on l’écart d’apprentissage lié au revenu familial ?", "options": ["Un écart climatique", "Un écart d’apprentissage socio-économique", "Un écart sportif", "Un écart de chaussures"], "answer": 1, "explain": "Les écarts d’apprentissage liés au revenu des familles traduisent des chances inégales.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Pourquoi les pays comparent-ils leurs résultats d’apprentissage à des références ?", "options": ["Pour éviter d’enseigner", "Pour classer les enseignants selon leur taille", "Pour comparer les progrès et fixer des objectifs réalistes", "Pour punir les apprenants"], "answer": 2, "explain": "L’étalonnage aide les pays à comparer leurs résultats et à apprendre les uns des autres.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Que favorise l’apprentissage dans la langue maternelle ?", "options": ["Uniquement l’écriture en anglais", "Uniquement le chant", "Aucun apprentissage", "La compréhension et la lecture initiale"], "answer": 3, "explain": "L’enseignement dans la langue maternelle aide les apprenants à comprendre et à construire les bases de la lecture.", "src": "UNESCO, International Mother Language Day"}, {"ch": 3, "q": "Qu’est-ce que l’alignement entre programme et évaluation ?", "options": ["Des épreuves qui mesurent ce que le programme enseigne", "Des épreuves qui ne correspondent jamais aux cours", "Des épreuves qui portent sur des thèmes non enseignés", "Des épreuves qui ne sont jamais corrigées"], "answer": 0, "explain": "Un bon alignement garantit que les épreuves mesurent les apprentissages visés par le programme.", "src": "UNESCO"}, {"ch": 3, "q": "Qu’est-ce que l’analyse des apprentissages (learning analytics) ?", "options": ["Compter le nombre de bureaux", "Utiliser les données sur les apprentissages pour améliorer l’enseignement", "Deviner la météo", "Vendre des données à des entreprises"], "answer": 1, "explain": "L’analyse des apprentissages utilise les données pour comprendre les apprentissages et guider le soutien.", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "Qu’est-ce que la métacognition ?", "options": ["Ne penser qu’au sport", "Oublier toutes ses pensées", "Réfléchir à sa propre façon de penser", "Ne penser que dans une seule langue"], "answer": 2, "explain": "La métacognition aide les apprenants à planifier, suivre et améliorer leurs apprentissages.", "src": "UNESCO"}, {"ch": 3, "q": "Qu’est-ce que l’apprentissage en profondeur ?", "options": ["Apprendre le plus profondément possible dans une piscine", "Mémoriser sans comprendre", "Apprendre uniquement dans des pièces obscures", "Comprendre les idées assez bien pour les appliquer"], "answer": 3, "explain": "L’apprentissage en profondeur va au-delà de la mémorisation pour comprendre et appliquer les idées.", "src": "UNESCO"}, {"ch": 4, "q": "Qu’est-ce que l’employabilité dans l’éducation ?", "options": ["Les compétences qui aident à trouver et à garder un emploi", "Être incapable de travailler dans n’importe quel métier", "Posséder une entreprise sans jamais y travailler", "Éviter tout type d’emploi toute sa vie"], "answer": 0, "explain": "L’employabilité combine compétences, savoirs et attitudes qui favorisent le travail.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Qu’est-ce que la pertinence de l’éducation pour le marché du travail ?", "options": ["Des apprentissages qui ignorent complètement l’emploi", "Des apprentissages qui correspondent aux compétences dont l’économie a besoin", "Des apprentissages réservés aux artistes", "Des apprentissages qui ne changent jamais"], "answer": 1, "explain": "Une éducation pertinente prépare les apprenants aux emplois qui existent ou émergent.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Qu’est-ce qu’un apprentissage (alternance) ?", "options": ["Un type d’examen scolaire passé à la fin de chaque année", "Des vacances pour les enseignants prises au milieu de chaque trimestre", "Apprendre un métier en travaillant sous la conduite d’une personne expérimentée", "Un type d’uniforme scolaire porté à chaque cours, chaque jour"], "answer": 2, "explain": "L’apprentissage associe formation en situation de travail et enseignement formel.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Qu’est-ce que la compétence numérique pour les enseignants et les apprenants ?", "options": ["Éviter toute technologie", "Utiliser uniquement du papier", "Casser les ordinateurs", "Utiliser les outils numériques de façon sûre et efficace"], "answer": 3, "explain": "La compétence numérique aide à utiliser la technologie pour apprendre, travailler et communiquer.", "src": "UNESCO"}, {"ch": 4, "q": "Qu’est-ce que la littératie en intelligence artificielle ?", "options": ["Comprendre ce que l’IA peut et ne peut pas faire", "Croire que l’IA a toujours raison", "Refuser de s’informer sur l’IA", "Penser que l’IA remplace toute réflexion"], "answer": 0, "explain": "La littératie en IA aide les apprenants à utiliser l’IA de façon responsable et à questionner ses résultats.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Que vise une politique d’apprentissage tout au long de la vie ?", "options": ["Mettre fin à tout apprentissage dès la fin des études", "Créer des occasions d’apprendre à chaque étape de la vie", "Limiter tout apprentissage aux seuls jeunes de la ville", "Arrêter tous les programmes d’éducation des adultes du pays"], "answer": 1, "explain": "Les politiques d’apprentissage tout au long de la vie soutiennent l’apprentissage de l’enfance jusqu’au grand âge.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Qu’est-ce que la reconnaissance des compétences acquises de façon informelle ?", "options": ["Ignorer toutes les compétences acquises au travail pendant des années", "Ne compter que les notes des examens écrits de l’école chaque année", "Accorder une validation officielle aux compétences acquises en dehors de l’école", "Retirer les certificats que les personnes ont déjà obtenus au travail"], "answer": 2, "explain": "La reconnaissance aide les personnes à valoriser les compétences acquises au travail et dans la vie associative.", "src": "UNESCO"}, {"ch": 4, "q": "Qu’est-ce que l’innovation dans l’éducation ?", "options": ["Garder les anciennes méthodes pour toujours", "Recopier d’anciens manuels", "Stopper toutes les idées nouvelles", "De nouvelles idées qui améliorent les apprentissages"], "answer": 3, "explain": "L’innovation en éducation introduit des approches nouvelles qui améliorent les apprentissages.", "src": "UNESCO"}, {"ch": 5, "q": "Qu’est-ce que la budgétisation sensible au genre dans l’éducation ?", "options": ["Des budgets qui tiennent compte des besoins des filles et des garçons", "Des budgets qui ignorent complètement le genre dans chaque décision", "Des budgets uniquement pour les garçons de chaque école du district", "Des budgets uniquement pour les enseignants, leurs salaires et leurs vacances"], "answer": 0, "explain": "La budgétisation sensible au genre répartit l’argent pour répondre à des besoins différents.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Qu’est-ce que le maintien des filles dans le secondaire ?", "options": ["Tenir les filles à l’écart de l’école", "Garder les filles inscrites jusqu’à la fin de leur cursus", "Garder les filles dans une seule classe", "Garder les filles à la maison"], "answer": 1, "explain": "Le maintien des filles signifie qu’elles restent à l’école jusqu’à l’achèvement de leur cursus.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Que fait la protection sociale pour les familles pauvres ?", "options": ["Elle éloigne les enfants de leur famille et de leur foyer", "Elle ajoute de nouveaux frais de scolarité pour chaque famille pauvre de la région", "Elle aide les familles à faire face aux chocs et à garder les enfants à l’école", "Elle supprime chaque jour la restauration scolaire gratuite pour les enfants pauvres"], "answer": 2, "explain": "La protection sociale peut aider les familles à garder les enfants à l’école dans les périodes difficiles.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Qu’est-ce que la pauvreté des enfants ?", "options": ["Avoir trop de jouets", "Être trop grand", "Être trop malin", "Vivre dans la pauvreté pendant l’enfance"], "answer": 3, "explain": "La pauvreté des enfants limite l’accès à l’alimentation, à la santé, au logement et à l’apprentissage.", "src": "UNESCO"}, {"ch": 5, "q": "Qu’est-ce que la ségrégation ethnique dans les écoles ?", "options": ["Des apprenants de groupes ethniques différents sont séparés", "Tous les apprenants partagent une même cour de récréation", "Tous les apprenants parlent une même langue", "Tous les apprenants portent le même uniforme"], "answer": 0, "explain": "La ségrégation sépare les apprenants et limite les apprentissages et la compréhension partagés.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "Pourquoi les politiques doivent-elles atteindre les communautés nomades et mobiles ?", "options": ["Elles n’ont jamais besoin d’une école et n’en veulent pas", "Elles restent souvent sans scolarisation faute d’options souples", "Elles sont toujours riches et n’ont aucun besoin scolaire", "Elles préfèrent n’avoir aucune école de toute leur vie"], "answer": 1, "explain": "Les communautés mobiles ont besoin d’une scolarisation souple pour accéder à l’éducation.", "src": "UNESCO"}, {"ch": 5, "q": "Qu’est-ce qu’un quota d’action positive dans l’éducation ?", "options": ["Un quota qui interdit l’accès aux groupes défavorisés", "Un quota uniquement pour les enseignants", "Une part de places réservée à des groupes défavorisés", "Un quota uniquement pour le sport"], "answer": 2, "explain": "Les quotas peuvent aider les apprenants défavorisés à accéder à des places qu’ils auraient manquées.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Que signifie l’accès égal pour les filles dans les zones de conflit ?", "options": ["La fermeture de toutes les écoles pour filles", "Éloigner les filles de chez elles", "Ignorer les besoins des filles", "Des trajets et des écoles sûrs et protégés"], "answer": 3, "explain": "Les espaces protégés et les trajets sûrs aident les filles à continuer d’apprendre en situation de conflit.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 6, "q": "Quelle est une cause courante de la désertion enseignante ?", "options": ["Des bas salaires, de mauvaises conditions et l’absence d’évolution de carrière", "Trop de promotions et une évolution de carrière rapide pour tous", "Une grande sécurité de l’emploi et des contrats de long terme pour tous les personnels", "De longues vacances et des horaires courts pour chaque enseignant"], "answer": 0, "explain": "Les enseignants partent lorsque le salaire, les conditions et les perspectives de carrière sont faibles.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce que l’assurance qualité des enseignants ?", "options": ["Des dispositifs qui suppriment tous les enseignants", "Des dispositifs qui vérifient que l’enseignement respecte des normes fixées", "Des dispositifs qui fixent les vacances des enseignants", "Des dispositifs qui ignorent les élèves"], "answer": 1, "explain": "L’assurance qualité aide à maintenir l’enseignement à un niveau élevé.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce que l’évaluation des enseignants ?", "options": ["Un test de vitesse de course des enseignants sur la piste de l’école", "Un classement des enseignants selon leur taille dans la salle des professeurs", "Un bilan du travail d’un enseignant pour soutenir son amélioration", "Un contrôle des projets de vacances des enseignants pour tout l’été"], "answer": 2, "explain": "L’évaluation aide les enseignants à réfléchir et à progresser, lorsqu’elle est menée équitablement.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce que le programme de formation des enseignants ?", "options": ["Un emploi du temps scolaire pour les enfants", "Une liste d’uniformes scolaires", "Un menu pour les repas scolaires", "Les disciplines et les compétences enseignées aux futurs enseignants"], "answer": 3, "explain": "Les programmes de formation des enseignants les préparent aux disciplines et à la pédagogie.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Pourquoi les enseignants ont-ils besoin d’une formation à l’évaluation ?", "options": ["Pour juger les apprentissages avec justesse et les soutenir", "Pour éviter de noter", "Pour arrêter les tests", "Pour noter sans preuves"], "answer": 0, "explain": "La formation à l’évaluation aide les enseignants à s’appuyer sur des preuves pour soutenir les apprenants.", "src": "UNESCO GEM Report 2026"}, {"ch": 6, "q": "Qu’est-ce que l’agentivité des enseignants ?", "options": ["Des enseignants qui obéissent à tous les ordres sans réfléchir", "La capacité des enseignants à façonner leur propre pratique", "Des enseignants qui ne préparent jamais leurs cours", "Des enseignants qui travaillent uniquement la nuit"], "answer": 1, "explain": "L’agentivité des enseignants signifie qu’ils peuvent prendre des décisions qui améliorent les apprentissages.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce qu’une communauté professionnelle d’apprentissage pour les enseignants ?", "options": ["Un groupe qui rivalise pour obtenir le plus de vacances", "Un club qui vend uniquement du matériel pédagogique", "Des enseignants qui apprennent ensemble pour améliorer leur pratique", "Un groupe d’élèves qui enseignent"], "answer": 2, "explain": "Les communautés d’apprentissage aident les enseignants à partager leurs idées et à progresser ensemble.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce que le sentiment de mission d’un enseignant influence-t-il ?", "options": ["Uniquement le prix de la craie", "Uniquement le coût des bâtiments scolaires", "Rien d’important", "La motivation et l’engagement envers les apprenants"], "answer": 3, "explain": "La mission et l’engagement influencent la manière dont les enseignants s’investissent auprès des apprenants.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "Qu’est-ce qu’un partenariat public-privé dans l’éducation ?", "options": ["Une coopération entre les pouvoirs publics et des prestataires privés", "Des entreprises privées qui dirigent toutes les écoles par la loi", "Des gouvernements qui abandonnent toutes leurs responsabilités", "Des écoles qui paient les gouvernements"], "answer": 0, "explain": "Les partenariats peuvent élargir l’offre mais doivent être encadrés pour garantir qualité et équité.", "src": "UNESCO"}, {"ch": 7, "q": "Qu’est-ce que la régulation des écoles privées ?", "options": ["Interdire par défaut toutes les écoles privées dans la loi nationale", "Des règles qui garantissent que les écoles privées respectent des normes de qualité et de sécurité", "Laisser les écoles privées rédiger et fixer librement leurs propres règles", "Ignorer complètement les écoles privées et ne jamais les contrôler"], "answer": 1, "explain": "La régulation protège les apprenants des écoles privées.", "src": "UNESCO"}, {"ch": 7, "q": "Qu’est-ce que la marge budgétaire pour l’éducation ?", "options": ["L’espace pour construire des voitures et des camions au centre-ville", "L’espace dans les couloirs de l’école pour de nouveaux casiers et bancs", "La latitude du budget d’un gouvernement pour augmenter les dépenses", "L’espace pour des colonies de vacances à la campagne chaque été"], "answer": 2, "explain": "La marge budgétaire est la souplesse dont dispose un gouvernement pour financer l’éducation.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "Qu’est-ce que la dépense fiscale en faveur de l’éducation ?", "options": ["L’argent dépensé pour les examens scolaires, la correction et l’impression chaque année", "L’argent dépensé pour les vacances et les congés des enseignants chaque année", "L’argent dépensé pour le matériel sportif et les jeux scolaires chaque trimestre", "Des allègements fiscaux qui réduisent les recettes publiques destinées à l’éducation"], "answer": 3, "explain": "Les dépenses fiscales sont des allègements qui peuvent réduire les fonds disponibles pour l’éducation.", "src": "UNESCO"}, {"ch": 7, "q": "Qu’est-ce que l’efficacité-coût dans l’éducation ?", "options": ["Obtenir des progrès d’apprentissage au coût le plus bas", "Dépenser le plus possible", "Dépenser uniquement dans les bâtiments", "Éviter toute dépense"], "answer": 0, "explain": "Les programmes efficients obtiennent davantage d’apprentissages pour chaque unité d’argent dépensée.", "src": "UNESCO"}, {"ch": 7, "q": "Qu’est-ce qu’une exonération des frais de scolarité ?", "options": ["Des frais pour une inscription tardive dans l’école pour les nouvelles familles", "Une dispense de frais de scolarité pour les familles qui ne peuvent pas les payer", "Une prime versée aux enseignants pour un bon travail chaque saison", "Un tarif pour l’usage du bus scolaire pendant tout le trimestre"], "answer": 1, "explain": "Les exonérations de frais aident les familles pauvres à garder leurs enfants à l’école.", "src": "UNESCO"}, {"ch": 7, "q": "Qu’est-ce que la crédibilité budgétaire dans l’éducation ?", "options": ["L’argent n’est jamais dépensé pour les écoles pendant toute l’année", "Les budgets sont élaborés en secret par quelques personnes chaque année", "Les fonds prévus pour l’éducation sont réellement dépensés pour les écoles", "Les budgets changent à chaque heure sans raison claire"], "answer": 2, "explain": "La crédibilité budgétaire signifie que les fonds prévus pour l’éducation sont effectivement délivrés.", "src": "UNESCO"}, {"ch": 7, "q": "Quel rôle les associations de parents d’élèves peuvent-elles jouer dans le financement scolaire ?", "options": ["Payer seules tous les salaires des enseignants", "Remplacer entièrement le financement public", "Fermer l’école", "Collecter des fonds ou un soutien pour répondre aux besoins de l’école"], "answer": 3, "explain": "Les associations de parents peuvent aider les écoles, sans toutefois remplacer le financement public.", "src": "UNESCO"}, {"ch": 8, "q": "Quelle convention de 2006 concerne les personnes handicapées ?", "options": ["La Convention des Nations unies relative aux droits des personnes handicapées", "La Convention de Genève sur le commerce international et les tarifs", "L’Accord de Tokyo sur le sport et la formation des athlètes", "La Convention de Lima sur l’agriculture, l’alimentation et l’usage des terres"], "answer": 0, "explain": "La CDPH a été adoptée en 2006 et inclut le droit à l’éducation.", "src": "UN CRPD (2006), Article 24"}, {"ch": 8, "q": "En quelle année la CDPH a-t-elle été adoptée ?", "options": ["1994", "2006", "1989", "2015"], "answer": 1, "explain": "La CDPH de l’ONU a été adoptée en 2006.", "src": "UN CRPD (2006), Article 24"}, {"ch": 8, "q": "Que dit l’article 29 de la Convention relative aux droits de l’enfant sur l’éducation ?", "options": ["L’éducation doit être coûteuse", "L’éducation doit être réservée aux garçons", "L’éducation doit développer la personnalité et les talents de chaque enfant", "L’éducation doit être interdite aux enfants handicapés"], "answer": 2, "explain": "L’article 29 fixe les buts de l’éducation, dont le respect des droits et de la culture.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 8, "q": "Quel est le sigle courant de l’Éducation pour tous ?", "options": ["ELT", "EAT", "EFR", "EPT"], "answer": 3, "explain": "EPT est le sigle courant de l’Éducation pour tous.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "Que disait la Déclaration d’Incheon de 2015 sur l’apprentissage tout au long de la vie ?", "options": ["Il doit faire partie de l’éducation à tous les âges", "Il doit s’arrêter à 14 ans", "Il doit être interdit", "Il ne doit concerner que les enseignants"], "answer": 0, "explain": "La Déclaration d’Incheon a promu les possibilités d’apprentissage tout au long de la vie pour tous.", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "Quel organisme publie les données mondiales sur l’éducation ?", "options": ["L’Association mondiale de football", "L’Institut de statistique de l’UNESCO", "Le Conseil international de l’hôtellerie", "Le Fonds mondial pour la musique"], "answer": 1, "explain": "L’Institut de statistique de l’UNESCO publie les données mondiales sur l’éducation.", "src": "UNESCO GEM Report 2026"}, {"ch": 8, "q": "Quel est le lien entre les OMD et les ODD ?", "options": ["Les ODD n’ont rien remplacé", "Les ODD ont annulé tous les objectifs", "Les ODD s’appuient sur les enseignements des OMD", "Les OMD sont toujours en vigueur"], "answer": 2, "explain": "Les ODD se sont construits sur les OMD et ont élargi le programme.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "Dans quel but le Partenariat mondial pour l’éducation a-t-il été créé ?", "options": ["Vendre des manuels scolaires dans le monde entier", "Organiser des événements sportifs", "Financer des voyages dans l’espace", "Soutenir l’éducation dans les pays à revenu faible"], "answer": 3, "explain": "Le Partenariat mondial pour l’éducation aide les pays à revenu faible à améliorer les apprentissages.", "src": "UNESCO GEM Report 2026"}, {"ch": 8, "q": "Que disait la Déclaration universelle des droits de l’homme sur les parents et l’éducation ?", "options": ["Les parents ont un droit prioritaire de choisir l’éducation de leurs enfants", "Les parents n’ont aucun rôle dans la scolarité de leurs enfants", "Les parents doivent choisir uniquement le sport et les jeux pour leurs enfants", "Les parents doivent payer toutes les écoles de leur commune"], "answer": 0, "explain": "L’article 26 affirme que les parents ont un droit prioritaire de choisir le type d’éducation de leurs enfants.", "src": "UN General Assembly (1948)"}, {"ch": 9, "q": "Qu’est-ce que l’éducation et l’accueil de la petite enfance (EAPE) ?", "options": ["Des formations pour adultes réservées aux personnes qui travaillent", "Des services d’apprentissage et d’accueil pour les jeunes enfants avant l’école primaire", "Des formations d’enseignants pour les nouveaux maîtres du pays", "Des examens du secondaire et des évaluations finales pour tous les élèves"], "answer": 1, "explain": "L’EAPE regroupe les services qui soutiennent le développement et les apprentissages des jeunes enfants.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "Qu’est-ce qu’une approche multisectorielle de la petite enfance ?", "options": ["Seule l’éducation, isolée dans chaque école et chaque classe", "Seule la santé, isolée dans chaque dispensaire et hôpital local", "La santé, la nutrition, l’éducation et la protection travaillant ensemble", "Seul le sport, isolé dans la cour et sur le terrain"], "answer": 2, "explain": "Les approches multisectorielles répondent aux besoins des enfants à travers tous les services.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Qu’est-ce que le taux d’encadrement enfants-adulte ?", "options": ["Le nombre de jouets par enfant", "Le nombre de fenêtres dans une pièce", "Le nombre de personnels en vacances", "Le nombre d’enfants dont chaque adulte s’occupe"], "answer": 3, "explain": "Des taux d’encadrement plus faibles permettent davantage d’attention et d’interaction avec chaque enfant.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Pourquoi les jeunes enfants ont-ils besoin de référents stables ?", "options": ["Des relations stables soutiennent le développement affectif et cognitif", "La stabilité n’est pas du tout importante pour les jeunes enfants", "Les enfants préfèrent de nombreux inconnus à leur famille proche", "Les référents devraient changer chaque jour pour la variété"], "answer": 0, "explain": "Des référents stables et constants aident les enfants à se sentir en sécurité et à apprendre.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Qu’est-ce que le soutien précoce aux enfants handicapés ?", "options": ["Attendre l’école pour commencer", "Une aide précoce pour développer les compétences et le développement", "Tenir les enfants à l’écart des autres", "Ignorer les besoins de développement"], "answer": 1, "explain": "L’intervention précoce aide les enfants handicapés à développer leurs compétences plus tôt.", "src": "UN CRPD (2006), Article 24"}, {"ch": 9, "q": "Qu’est-ce que le dépistage du développement ?", "options": ["Des tests pour choisir les chaussures scolaires de chaque élève", "Des examens que les enseignants passent en fin d’année", "Des contrôles rapides qui repèrent les enfants pouvant avoir besoin d’un soutien", "Un contrôle des projets de vacances de l’école locale chaque année"], "answer": 2, "explain": "Le dépistage aide à repérer les enfants qui peuvent avoir besoin d’une évaluation ou d’une aide complémentaire.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Qu’est-ce qu’une expérience négative de l’enfance (ACE) ?", "options": ["Un voyage de vacances heureux en famille chaque été", "Un prix scolaire pour un bon travail et des efforts chaque trimestre", "Un type d’examen passé par les élèves du primaire chaque année", "Un événement stressant ou nuisible pendant l’enfance qui peut affecter le développement"], "answer": 3, "explain": "Les ACE peuvent affecter la santé et les apprentissages, ce qui rend le soutien précoce essentiel.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "Qu’est-ce qu’une stratégie nationale d’alphabétisation ?", "options": ["Un plan pour améliorer l’alphabétisation dans tout le pays", "Un plan pour vendre des journaux", "Un plan pour fermer des bibliothèques", "Un plan pour une seule école"], "answer": 0, "explain": "Les stratégies nationales d’alphabétisation fixent des objectifs et des actions pour améliorer la lecture et l’écriture.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Qu’est-ce que la littératie à l’ère numérique ?", "options": ["Éviter tous les écrans et appareils numériques dans chaque classe", "Lire, écrire et comprendre l’information sous forme numérique", "Ne lire que des livres papier et rien d’autre, à aucun moment", "Écrire uniquement au crayon sur papier dans toutes les matières"], "answer": 1, "explain": "La littératie numérique étend la lecture et l’écriture aux environnements en ligne.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Qu’est-ce qu’une enquête sur la littératie des adultes ?", "options": ["Une enquête sur les vacances et les projets de voyage des adultes chaque année", "Une enquête sur les voitures des adultes et leurs propriétaires dans chaque ville", "Une enquête qui mesure la lecture et le calcul chez les adultes", "Une enquête sur les sports et les habitudes de forme des adultes dans chaque ville"], "answer": 2, "explain": "Les enquêtes sur la littératie des adultes mesurent les compétences pour guider la politique.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Pourquoi les bibliothèques sont-elles importantes pour la littératie des adultes ?", "options": ["Elles sont réservées aux enfants et aux jeunes élèves de chaque ville", "Elles vendent des livres sans jamais en prêter à personne", "Elles sont fermées à tous les adultes à toute heure de la journée", "Elles donnent un accès gratuit aux livres et un soutien à l’apprentissage"], "answer": 3, "explain": "Les bibliothèques soutiennent les adultes qui veulent lire, apprendre et développer leurs compétences.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "Qu’est-ce que la diversité linguistique dans la littératie ?", "options": ["La variété des langues utilisées dans une communauté", "N’utiliser qu’une seule langue partout", "Interdire les langues locales", "N’enseigner que la langue des signes"], "answer": 0, "explain": "La diversité linguistique compte, car les apprenants lisent et apprennent dans de nombreuses langues.", "src": "UNESCO, International Mother Language Day"}, {"ch": 10, "q": "Qu’est-ce que l’engagement des apprenants dans la lecture ?", "options": ["La vitesse à laquelle les apprenants marchent", "Le plaisir que les apprenants prennent à lire et le choix qu’ils font de lire", "La force de la voix des apprenants", "Le nombre de livres vendus"], "answer": 1, "explain": "L’engagement dans la lecture montre la motivation des apprenants à lire.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "Qu’est-ce qu’un programme passerelle de littératie ?", "options": ["Un programme qui construit de vrais ponts au-dessus des rivières et des routes", "Un programme qui ferme chaque année les bibliothèques de la ville", "Un programme qui aide les apprenants à passer de la lecture de base à une lecture plus avancée", "Un programme uniquement sportif et ludique, sans lecture du tout"], "answer": 2, "explain": "Les programmes passerelles aident les apprenants à progresser au-delà de la lecture de base.", "src": "UNESCO, International Literacy Day"}, {"ch": 11, "q": "Qu’est-ce qu’un système éducatif inclusif ?", "options": ["Un système où les apprenants sont séparés selon leur handicap", "Un système sans enseignants", "Un système sans règles", "Un système où tous les apprenants sont intégrés à l’enseignement ordinaire"], "answer": 3, "explain": "Un système inclusif accueille les apprenants et adapte l’enseignement ordinaire à leurs besoins.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Qu’est-ce que la non-discrimination dans l’éducation ?", "options": ["Traiter les apprenants équitablement, quels que soient leur handicap, leur genre ou leur origine", "Traiter les apprenants différemment selon leur groupe dans chaque école", "Refuser l’accès à l’école à tout un groupe d’apprenants", "Facturer des frais supplémentaires à certains apprenants selon leur origine"], "answer": 0, "explain": "La non-discrimination est un principe fondamental de l’éducation inclusive.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Quel est le principe de représentation de la conception universelle de l’apprentissage ?", "options": ["Ne présenter qu’un seul format", "Présenter l’information sous plusieurs formats", "Cacher l’information aux apprenants", "Tout présenter en silence"], "answer": 1, "explain": "Les moyens de représentation multiples aident les apprenants à accéder au contenu de différentes manières.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Pourquoi les apprenants handicapés doivent-ils avoir leur mot à dire dans les décisions ?", "options": ["Ils ne doivent jamais être consultés", "Seuls les adultes peuvent décider", "Ils connaissent mieux leurs propres besoins", "Les décisions doivent être prises sans eux"], "answer": 2, "explain": "Les apprenants handicapés doivent être consultés sur les décisions qui les concernent.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Qu’est-ce que la participation des apprenants aux décisions de l’école ?", "options": ["Les apprenants restent silencieux", "Les apprenants prennent toutes les décisions seuls", "Les apprenants ne participent jamais aux réunions", "Les apprenants prennent part aux décisions qui les concernent"], "answer": 3, "explain": "La participation des apprenants développe la responsabilité et respecte leurs droits.", "src": "UN Convention on the Rights of the Child (1989), Article 12"}, {"ch": 11, "q": "Qu’est-ce que le climat scolaire ?", "options": ["L’ambiance de l’école pour les apprenants et le personnel", "La seule température à l’intérieur de l’école", "La quantité de soleil dans l’école", "Le nombre de bus scolaires"], "answer": 0, "explain": "Le climat scolaire détermine si les apprenants se sentent en sécurité, respectés et motivés.", "src": "UNESCO GEM Report 2026"}, {"ch": 11, "q": "Qu’est-ce qu’une politique contre le harcèlement ?", "options": ["Des règles qui encouragent le harcèlement entre élèves dans chaque école", "Des règles et des actions pour stopper le harcèlement et protéger les apprenants", "Des politiques qui ignorent complètement le harcèlement dans chaque école", "Des politiques qui sanctionnent les victimes de harcèlement chaque trimestre"], "answer": 1, "explain": "Les politiques contre le harcèlement protègent les apprenants et favorisent un environnement d’apprentissage sûr.", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "Pourquoi l’éducation inclusive est-elle bonne pour la société ?", "options": ["Elle crée de la division", "Elle réduit les apprentissages de tous", "Elle construit l’équité et la cohésion sociale", "Elle n’est utile qu’à quelques-uns"], "answer": 2, "explain": "L’éducation inclusive construit la cohésion sociale et l’équité pour tous.", "src": "UN CRPD (2006), Article 24"}], "12": [{"ch": 0, "q": "Quel est le principal objet du Cadre d’action Éducation 2030 ?", "options": ["Un guide pour aider les pays à mettre en œuvre l’ODD 4", "Un règlement sportif pour les tournois scolaires", "Une loi bancaire pour la banque nationale", "Un code vestimentaire scolaire pour tous les uniformes"], "answer": 0, "explain": "Il fournit des orientations pour mettre en œuvre l’ODD 4 dans les pays.", "src": "Incheon Framework for Action (2015)"}, {"ch": 0, "q": "Qu’est-ce que le cadre mondial d’indicateurs des ODD ?", "options": ["Un calendrier des jours fériés pour chaque école de l’année", "Un ensemble d’indicateurs convenus pour mesurer les progrès", "Une liste de livres interdits pour chaque bibliothèque scolaire", "Une carte indiquant où se trouvent tous les bâtiments scolaires"], "answer": 1, "explain": "Le cadre mondial fournit des indicateurs communs pour suivre les progrès des ODD.", "src": "UN SDG Report 2026"}, {"ch": 0, "q": "Que montrent les niveaux de classement des indicateurs des ODD ?", "options": ["La taille de chaque élève au début de l’année", "Le nombre d’écoles construites par un pays au fil du temps", "Le degré de solidité de la méthodologie de chaque indicateur", "La somme d’argent qu’une école collecte lors d’événements chaque année"], "answer": 2, "explain": "Les niveaux montrent la maturité méthodologique et la disponibilité des données des indicateurs.", "src": "UN SDG Report 2026"}, {"ch": 0, "q": "Pourquoi les indicateurs de l’ODD 4 sont-ils ventilés par niveau de richesse ?", "options": ["Pour classer les familles selon la taille de chaque membre", "Pour choisir les uniformes scolaires", "Pour fixer les dates de vacances", "Pour révéler les écarts entre élèves riches et pauvres"], "answer": 3, "explain": "La ventilation par richesse montre si les progrès atteignent les élèves les plus pauvres.", "src": "UNESCO GEM Report 2026"}, {"ch": 0, "q": "Que mesure le suivi du financement de l’ODD 4 ?", "options": ["Le montant investi et sa destination", "Le nombre d’arbres plantés", "Le nombre de clubs sportifs existants", "Le nombre de livres imprimés"], "answer": 0, "explain": "Le suivi du financement montre les niveaux d’investissement et s’ils atteignent les groupes prioritaires.", "src": "Incheon Framework for Action (2015)"}, {"ch": 0, "q": "Qu’est-ce que l’évaluation des politiques en éducation ?", "options": ["Choisir de nouvelles couleurs officielles pour la façade de l’école", "Juger si les politiques atteignent leurs objectifs", "Compter les fenêtres de la façade de tous les bâtiments scolaires", "Écrire des poèmes sur les vacances d’été de chaque année"], "answer": 1, "explain": "L’évaluation aide à décider si les politiques doivent continuer, changer ou s’arrêter.", "src": "UNESCO"}, {"ch": 0, "q": "Qu’est-ce qu’une politique fondée sur des données probantes ?", "options": ["Une politique élaborée sans aucune donnée ni preuve", "Une politique faite à l’aveugle, sans aucune base", "Une politique éclairée par la recherche et les données", "Une politique copiée depuis les films et la télévision"], "answer": 2, "explain": "Une politique fondée sur des preuves s’appuie sur la recherche pour orienter les décisions.", "src": "UNESCO"}, {"ch": 0, "q": "Pourquoi les gouvernements ont-ils besoin de systèmes de données éducatives ?", "options": ["Pour éviter de prendre des décisions sur l’éducation chaque année", "Pour cacher des informations au public et à la presse", "Pour remplacer les enseignants par des systèmes automatiques", "Pour planifier, suivre et améliorer l’éducation"], "answer": 3, "explain": "Les systèmes de données soutiennent la planification, le suivi et la reddition de comptes.", "src": "UNESCO GEM Report 2026"}, {"ch": 0, "q": "Que signifie le fait que l’ODD 4 présente des synergies avec d’autres objectifs ?", "options": ["Les progrès en éducation favorisent les progrès dans d’autres domaines", "L’éducation bloque tous les autres objectifs", "L’éducation n’a aucun lien avec les autres objectifs", "Les autres objectifs n’affectent que le sport"], "answer": 0, "explain": "L’éducation soutient les objectifs de santé, d’égalité de genre, d’emploi et de climat.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Qu’est-ce que la non-scolarisation ?", "options": ["Être inscrit sans assister aux cours", "Être en âge scolaire sans être inscrit", "Fréquenter l’école uniquement à l’étranger", "Enseigner sans être payé"], "answer": 1, "explain": "La non-scolarisation signifie que des enfants d’âge scolaire ne sont pas inscrits à l’école.", "src": "UNESCO"}, {"ch": 1, "q": "Qu’est-ce que l’accès effectif à l’éducation ?", "options": ["Un accès seulement sur le papier", "Un accès sans aucun enseignant", "Un accès qui mène aussi à un véritable apprentissage", "Un accès qui ne dure qu’une seule journée"], "answer": 2, "explain": "L’accès effectif signifie que les enfants fréquentent l’école et apprennent, pas seulement qu’ils sont inscrits.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Qu’est-ce qu’un parcours de rattrapage pour les enfants dont la scolarité a été interrompue ?", "options": ["Un parcours qui permet de quitter l’école sans formalités", "Un parcours pour sauter des classes sans rien apprendre", "Un parcours qui ferme des écoles et éloigne les enfants", "Un parcours qui les aide à rattraper leur retard et à reprendre"], "answer": 3, "explain": "Les parcours de rattrapage aident les enfants ayant perdu une scolarité à reprendre leur éducation.", "src": "UNESCO"}, {"ch": 1, "q": "Qu’exige le droit à l’éducation des États ?", "options": ["Rendre l’éducation disponible, accessible, acceptable et adaptable", "Offrir l’éducation seulement aux familles riches du pays", "Offrir l’éducation seulement dans les grandes villes du pays", "Rendre l’éducation entièrement facultative pour chaque famille"], "answer": 0, "explain": "Les quatre A décrivent les obligations fondamentales du droit à l’éducation.", "src": "UN Special Rapporteur on the Right to Education"}, {"ch": 1, "q": "Que signifie la disponibilité dans le droit à l’éducation ?", "options": ["Les écoles n’ouvrent jamais pour aucun élève pendant l’année", "Il existe un nombre suffisant d’écoles et de programmes fonctionnels", "Les écoles n’ouvrent que les week-ends et les jours fériés", "Les écoles ne servent qu’aux enseignants certains jours"], "answer": 1, "explain": "La disponibilité signifie qu’il existe assez d’institutions et de programmes en fonctionnement.", "src": "UN Special Rapporteur on the Right to Education"}, {"ch": 1, "q": "Que signifie l’acceptabilité dans le droit à l’éducation ?", "options": ["Une éducation toujours ennuyeuse pour les élèves", "Une éducation tenue secrète auprès des familles", "Une éducation de bonne qualité et culturellement appropriée", "Une éducation dispensée dans une seule langue et rien d’autre"], "answer": 2, "explain": "L’acceptabilité signifie que l’éducation est pertinente, sûre et de bonne qualité.", "src": "UN Special Rapporteur on the Right to Education"}, {"ch": 1, "q": "Que signifie l’adaptabilité dans le droit à l’éducation ?", "options": ["Une éducation qui ne change jamais avec les besoins de l’époque", "Une éducation qui ignore les besoins des élèves et des familles", "Une éducation qui reste figée pour toujours dans toutes les écoles", "Une éducation qui s’adapte aux besoins des élèves et de la société"], "answer": 3, "explain": "L’adaptabilité signifie que l’éducation répond à l’évolution des besoins.", "src": "UN Special Rapporteur on the Right to Education"}, {"ch": 1, "q": "Pourquoi les dépenses directes d’éducation sont-elles préoccupantes ?", "options": ["Les familles paient directement, ce qui peut éloigner les enfants de l’école", "Les familles ne paient jamais rien du tout", "Les dépenses directes aident toujours les écoles et tous les élèves", "Elles n’affectent que les enseignants et leur salaire mensuel"], "answer": 0, "explain": "Des coûts directs élevés peuvent empêcher les familles pauvres d’envoyer leurs enfants à l’école.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Qu’est-ce qu’une réponse éducative humanitaire ?", "options": ["Une éducation dispensée uniquement en temps de paix et de stabilité", "Un soutien à l’éducation lors d’urgences et de crises", "Une réponse qui ferme directement les écoles touchées", "Une réponse qui se limite au seul domaine du sport scolaire"], "answer": 1, "explain": "Les réponses éducatives humanitaires maintiennent l’apprentissage pendant les crises.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "Qu’est-ce qu’un parcours d’apprentissage du secondaire vers le supérieur ?", "options": ["Un chemin pour quitter l’éducation pour toujours sans revenir", "Un chemin réservé aux adultes ayant déjà quitté l’école", "Un chemin du secondaire vers les études supérieures", "Un chemin vers un club sportif pour chaque élève après l’école"], "answer": 2, "explain": "Les parcours relient l’enseignement secondaire aux études et à la formation supérieures.", "src": "UNESCO"}, {"ch": 2, "q": "Qu’est-ce que l’enseignement supérieur ?", "options": ["L’enseignement avant la maternelle pour les tout-petits", "L’enseignement réservé aux enseignants en formation", "L’enseignement réservé au sport et à l’entraînement en club", "L’enseignement après le secondaire, comme à l’université"], "answer": 3, "explain": "L’enseignement supérieur comprend les universités, les écoles supérieures et la formation technique avancée.", "src": "UNESCO"}, {"ch": 2, "q": "Qu’est-ce que l’équité de l’achèvement des études ?", "options": ["Des taux d’achèvement similaires entre les groupes", "Des taux d’achèvement qui favorisent seulement les riches", "Des taux d’achèvement qui ne sont jamais mesurés", "Des taux d’achèvement toujours égaux à zéro"], "answer": 0, "explain": "L’équité de l’achèvement signifie que les groupes terminent l’école à des taux similaires.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "Qui sont les jeunes en décrochage précoce de l’éducation et de la formation ?", "options": ["Des jeunes qui quittent l’école plus tôt pour des vacances", "Des jeunes qui partent sans achever le secondaire", "Des enseignants qui partent plus tôt", "Des élèves qui terminent en premier"], "answer": 1, "explain": "Les décrocheurs précoces sont des jeunes qui quittent sans diplôme du secondaire.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Qu’est-ce qu’un programme professionnel au niveau du secondaire supérieur ?", "options": ["Un cours de cuisine et de pâtisserie enseigné seulement à la maison", "Une licence universitaire en histoire, droit et politique", "Une formation qui donne des compétences pratiques et des diplômes", "Un camp de vacances pour jeunes enfants pendant l’été"], "answer": 2, "explain": "Les programmes professionnels du secondaire supérieur donnent des compétences pratiques et des diplômes.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Pourquoi est-il important de terminer l’école pour la vie future ?", "options": ["Cela n’a aucun effet plus tard dans la vie", "Cela n’affecte que les vacances", "Cela n’affecte que le sport et les compétitions", "Cela influence fortement la santé, l’emploi et les revenus"], "answer": 3, "explain": "Terminer l’école est lié à une meilleure santé, à l’emploi et au bien-être.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "Qu’est-ce que l’achèvement tout au long de la vie ?", "options": ["Achever son apprentissage à n’importe quel âge", "Achever son apprentissage seulement avant dix ans", "Arrêter d’apprendre après l’école", "Apprendre seulement pour les enseignants"], "answer": 0, "explain": "L’achèvement tout au long de la vie signifie que chacun peut finir son apprentissage à tout âge.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Qu’est-ce que l’inversion du décrochage ?", "options": ["Des élèves qui quittent l’école encore plus vite", "Des élèves qui reviennent à l’éducation après l’avoir quittée", "Des élèves qui reculent seulement lors des examens", "Des élèves qui réduisent les frais de scolarité chaque année"], "answer": 1, "explain": "L’inversion du décrochage signifie que les élèves reviennent et achèvent leur éducation.", "src": "UNESCO"}, {"ch": 3, "q": "Quel est l’objectif des compétences fondamentales pour les pays ?", "options": ["Que les enfants apprennent seulement la musique et le chant tout au long du primaire", "Que les enfants n’apprennent jamais à lire à l’école primaire", "Que la plupart des enfants maîtrisent la lecture et le calcul de base en fin de primaire", "Que les enfants sèchent l’école et restent chez eux pendant le primaire"], "answer": 2, "explain": "Beaucoup de pays visent à ce que les enfants acquièrent les bases tôt au primaire.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Que signifie la qualité de l’apprentissage ?", "options": ["Un apprentissage seulement rapide et précipité à chaque cours", "Un apprentissage seulement long et épuisant pour chaque élève", "Un apprentissage qui évite tous les examens et tests pour chaque élève", "Un apprentissage pertinent, efficace et équitable"], "answer": 3, "explain": "La qualité de l’apprentissage répond aux besoins des élèves et mène à de vrais progrès.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Qu’est-ce que la pertinence des programmes ?", "options": ["Relier l’apprentissage à la vie des élèves et au travail futur", "Enseigner des choses qui ne sont jamais utilisées dans la réalité", "Ignorer totalement la vie et les centres d’intérêt des élèves", "Enseigner uniquement dans des langues mortes sans aucune application"], "answer": 0, "explain": "Les programmes pertinents relient les cours à la vie réelle et aux besoins futurs.", "src": "UNESCO"}, {"ch": 3, "q": "Qu’est-ce qu’une politique éducative fondée sur les résultats ?", "options": ["Fixer des objectifs selon la taille de l’école", "Fixer des objectifs selon ce que les élèves savent faire", "Fixer des objectifs selon la taille des enseignants", "Fixer des objectifs selon la durée des vacances"], "answer": 1, "explain": "La politique fondée sur les résultats se concentre sur les compétences et les acquis des élèves.", "src": "UNESCO"}, {"ch": 3, "q": "Qu’est-ce que le translanguaging en classe ?", "options": ["Interdire toutes les langues sauf une à l’école pour chaque élève", "Utiliser uniquement la langue des signes dans chaque cours de la journée", "Utiliser toutes les langues de l’élève pour soutenir l’apprentissage", "Enseigner en silence sans parler dans aucun cours"], "answer": 2, "explain": "Le translanguaging utilise tout le répertoire linguistique de l’élève pour l’aider à apprendre.", "src": "UNESCO, International Mother Language Day"}, {"ch": 3, "q": "Qu’est-ce que la charge cognitive ?", "options": ["Le poids d’un cartable scolaire", "Le nombre de pages d’un livre", "La quantité de lumière du jour dans une pièce", "La quantité d’effort mental qu’exige une tâche"], "answer": 3, "explain": "La charge cognitive compte pour la manière dont les élèves traitent et retiennent l’information.", "src": "Harvard Center on the Developing Child"}, {"ch": 3, "q": "Qu’est-ce que la pratique espacée ?", "options": ["Répartir les séances d’apprentissage dans le temps pour améliorer la mémoire", "Tout bachoter la veille au soir de l’examen", "Ne plus jamais revoir la même matière à aucun moment", "Ne pratiquer que pendant les longues vacances scolaires"], "answer": 0, "explain": "La pratique espacée aide à mieux retenir l’information dans la durée.", "src": "UNESCO"}, {"ch": 3, "q": "Qu’est-ce que la pratique de la récupération ?", "options": ["Recopier ses notes encore et encore sans jamais se rappeler", "Rappeler l’information de mémoire pour renforcer l’apprentissage", "Lire seulement le titre du chapitre sans rien d’autre", "Ignorer complètement ce qui a été enseigné en cours"], "answer": 1, "explain": "La pratique de la récupération renforce la mémoire en rappelant ce qui a été appris.", "src": "UNESCO"}, {"ch": 3, "q": "Qu’est-ce que le biais d’évaluation ?", "options": ["Des épreuves toujours parfaitement équitables pour tous les élèves", "Des épreuves qui ne mesurent jamais réellement ce que les élèves ont appris", "Des épreuves qui favorisent injustement certains groupes par rapport à d’autres", "Des épreuves qui servent seulement à mesurer la taille des élèves"], "answer": 2, "explain": "Le biais d’évaluation peut désavantager des élèves pour des raisons sans rapport avec leurs capacités.", "src": "UNESCO GEM Report 2026"}, {"ch": 4, "q": "Que sont les compétences transversales ?", "options": ["Des compétences propres à une seule matière scolaire", "Des compétences pour apprendre à mieux dormir chaque nuit", "Des compétences servant seulement à traverser la rue en sécurité", "Des compétences utiles dans de nombreuses matières et métiers"], "answer": 3, "explain": "Les compétences transversales, comme la communication et le travail d’équipe, s’appliquent partout.", "src": "UNESCO"}, {"ch": 4, "q": "Qu’est-ce que la pédagogie numérique ?", "options": ["Des méthodes d’enseignement qui utilisent bien la technologie", "Un enseignement qui se passe totalement de toute technologie", "Un enseignement réalisé seulement avec des machines en panne", "Un enseignement qui se déroule dans un silence absolu"], "answer": 0, "explain": "La pédagogie numérique utilise la technologie pour soutenir l’apprentissage, pas seulement pour remplacer le papier.", "src": "UNESCO"}, {"ch": 4, "q": "Qu’est-ce que la confidentialité des données dans la technologie éducative ?", "options": ["Partager les données des élèves avec des inconnus", "Protéger les informations personnelles des élèves", "Vendre les données des élèves", "Ignorer les règles de confidentialité"], "answer": 1, "explain": "La confidentialité des données protège les élèves contre le mauvais usage de leurs informations personnelles.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Qu’est-ce que le perfectionnement des compétences (upskilling) ?", "options": ["Perdre des compétences déjà acquises en travaillant au quotidien", "Apprendre seulement pour les enfants du primaire chaque année scolaire complète", "Acquérir de nouvelles compétences pour suivre l’évolution du travail", "Arrêter toute formation dès qu’on commence un nouvel emploi"], "answer": 2, "explain": "Le perfectionnement aide les travailleurs à s’adapter aux nouvelles technologies et aux nouveaux emplois.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Qu’est-ce que la reconversion professionnelle (reskilling) ?", "options": ["Oublier toutes ses compétences et connaissances passées", "Apprendre seulement des sports et des jeux pour le plaisir", "Arrêter complètement de travailler et rester chez soi pour toujours", "Acquérir de nouvelles compétences pour changer de type de travail"], "answer": 3, "explain": "La reconversion prépare les personnes à de nouveaux rôles quand les anciens emplois évoluent.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Qu’est-ce que la formation aux emplois verts ?", "options": ["Préparer les travailleurs à des emplois qui protègent l’environnement", "Former à des emplois qui nuisent à la nature et à l’environnement", "Former uniquement à la peinture des murs et façades des bâtiments", "Former exclusivement à la pratique d’un sport scolaire particulier"], "answer": 0, "explain": "La formation aux emplois verts prépare les personnes à un travail durable.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Qu’est-ce que la compétence mondiale ?", "options": ["Ignorer complètement les autres pays et leurs habitants", "Comprendre le monde et les autres cultures et s’y engager", "Ne connaître que l’histoire d’un seul pays et rien d’autre", "Refuser de voyager ou de rencontrer des personnes d’autres pays"], "answer": 1, "explain": "La compétence mondiale aide les élèves à comprendre les enjeux globaux et à communiquer entre cultures.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Qu’est-ce que l’apprentissage socio-émotionnel (ASE) ?", "options": ["Apprendre à éviter tous les sentiments et émotions dans chaque situation", "Apprendre seulement les maths et rien d’autre à l’école chaque jour", "Apprendre à gérer ses émotions et à bien se relier aux autres", "Apprendre à garder le silence dans chaque situation sociale"], "answer": 2, "explain": "L’ASE développe la conscience de soi, l’empathie et les compétences relationnelles.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "Que sont les normes de genre ?", "options": ["Des règles sur ce que les enfants mangent à la cantine de chaque école", "Des mesures de la taille de chaque bâtiment scolaire dans toute la ville", "Des règles sur les vacances réservées uniquement aux enseignants et au personnel", "Les attentes partagées sur la manière dont filles et garçons doivent se comporter"], "answer": 3, "explain": "Les normes de genre façonnent les rôles et les possibilités des filles et des garçons.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Quel est le lien entre le maintien des filles à l’école et le mariage des enfants ?", "options": ["C’est l’un des moyens les plus efficaces de retarder le mariage des enfants", "Cela pousse les filles à se marier très jeunes chaque année", "Cela n’a aucun lien avec le mariage à aucun âge dans aucune communauté", "Cela ferme les écoles pour filles de la communauté chaque trimestre"], "answer": 0, "explain": "Maintenir les filles à l’école est l’un des moyens les plus efficaces de retarder le mariage des enfants.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Quel est l’impact de la grossesse à l’adolescence sur la scolarité ?", "options": ["Elle améliore toujours la scolarité", "Elle peut interrompre la scolarité des filles", "Elle n’a aucun lien avec l’école", "Elle n’affecte que les garçons de même âge"], "answer": 1, "explain": "La grossesse peut interrompre la scolarité, d’où l’importance des politiques de réintégration et de soutien.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Qu’est-ce que l’assainissement inclusif dans les écoles ?", "options": ["Des toilettes réservées aux enseignants et au personnel de l’école", "Aucune toilette ni installation de lavage pour aucun élève", "Des toilettes et des installations de lavage qui répondent aux besoins de tous", "Des toilettes toujours fermées aux élèves pendant la journée"], "answer": 2, "explain": "L’assainissement inclusif comprend des installations pour les filles et pour les élèves en situation de handicap.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Au-delà de l’argent, qu’inclut la pauvreté des élèves ?", "options": ["Avoir trop de livres à lire à la maison chaque soir", "Avoir trop d’amis avec qui jouer après l’école", "Avoir trop de temps libre pour jouer chaque jour après l’école", "Le manque de nourriture, de transport, de matériel et d’espace pour étudier"], "answer": 3, "explain": "La pauvreté des élèves inclut le manque de nourriture, de transport, de matériel et d’espace calme pour étudier.", "src": "UNESCO"}, {"ch": 5, "q": "Qu’est-ce que les désavantages multiples ?", "options": ["Faire face à plusieurs obstacles à la fois", "Ne rencontrer aucun obstacle", "Ne rencontrer qu’un seul petit obstacle", "Bénéficier d’un soutien excessif"], "answer": 0, "explain": "Les désavantages multiples signifient que plusieurs obstacles se combinent et exigent des réponses conjuguées.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Que signifie l’inclusion des réfugiés dans les systèmes nationaux ?", "options": ["Séparer définitivement les élèves réfugiés des autres élèves", "Intégrer les élèves réfugiés au système national", "Refuser les élèves réfugiés", "Enseigner aux réfugiés uniquement en ligne"], "answer": 1, "explain": "L’inclusion des réfugiés dans les systèmes nationaux leur permet d’accéder à l’éducation et à des diplômes reconnus.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "Qu’est-ce que l’éducation nomade ?", "options": ["Une scolarisation toujours dans un même bâtiment", "Une scolarisation réservée aux enfants des villes", "Une scolarisation conçue pour les communautés mobiles", "Une scolarisation sans enseignants"], "answer": 2, "explain": "L’éducation nomade adapte l’enseignement et les horaires aux familles mobiles.", "src": "UNESCO"}, {"ch": 5, "q": "Que mesure un indice d’équité en éducation ?", "options": ["La hauteur des bâtiments scolaires de chaque quartier", "Le nombre de sonneries retentissant pendant les récréations", "La durée des vacances des enseignants de chaque région", "La comparaison de l’accès ou des résultats entre groupes"], "answer": 3, "explain": "Les indices d’équité résument la répartition équitable de l’éducation.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "Que signifie l’équilibre femmes-hommes parmi les enseignants ?", "options": ["Un nombre équilibré de femmes et d’hommes parmi les enseignants", "Seuls les hommes sont autorisés à enseigner dans les écoles d’ici", "Seules les femmes sont autorisées à enseigner dans les écoles d’ici", "Aucun enseignant n’est nécessaire dans les écoles d’ici"], "answer": 0, "explain": "L’équilibre femmes-hommes peut influencer les modèles et la culture de l’école.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 6, "q": "Qu’est-ce que l’analyse de l’offre et de la demande d’enseignants ?", "options": ["Comparer les couleurs et les vêtements préférés des enseignants chaque année", "Comparer le nombre d’enseignants nécessaires avec le nombre disponible", "Compter les vacances et les jours de congé pris par les enseignants chaque année", "Comparer la taille des enseignants dans la salle des professeurs chaque année"], "answer": 1, "explain": "L’analyse de l’offre et de la demande aide les gouvernements à planifier le recrutement.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce que la réforme de la formation des enseignants ?", "options": ["Supprimer toute formation initiale et continue des enseignants", "Mettre définitivement fin à la carrière de tous les enseignants", "Modifier la manière dont les enseignants sont formés", "Fermer seulement quelques écoles normales et laisser le reste ouvert"], "answer": 2, "explain": "La réforme de la formation des enseignants met à jour la préparation pour correspondre aux classes actuelles.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce que le développement du leadership scolaire ?", "options": ["Former les dirigeants pour ne jamais enseigner dans les classes qu’ils visitent", "Former les dirigeants uniquement au sport et aux jeux de l’école", "Former les dirigeants pour fermer les écoles plus tôt chaque trimestre", "Former les chefs d’établissement pour guider l’enseignement et l’apprentissage"], "answer": 3, "explain": "Développer le leadership améliore la qualité de l’école.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’inclut la progression de carrière des enseignants ?", "options": ["Des étapes claires pour développer ses compétences et ses responsabilités", "Aucune étape permettant aux enseignants de progresser dans leur carrière", "Seulement des vacances et de longues pauses chaque année pour les enseignants", "Seulement des baisses de salaire et moins de personnel chaque trimestre"], "answer": 0, "explain": "Une progression claire aide les enseignants à évoluer et à rester dans la profession.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce que la relation enseignant-élève ?", "options": ["Une relation sans aucun contact", "Un lien positif qui soutient l’apprentissage", "Une simple affaire commerciale", "Une rivalité qui freine l’apprentissage"], "answer": 1, "explain": "Des relations solides aident les élèves à se sentir en sécurité et motivés.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Qu’est-ce que le temps de travail des enseignants ?", "options": ["Seulement le nombre total de minutes que dure une journée d’école complète", "Le temps passé à profiter de vacances et de congés payés chaque année", "Le temps total consacré à l’enseignement et aux tâches liées", "Le temps passé chaque matin à voyager dans le bus scolaire"], "answer": 2, "explain": "Le temps de travail comprend la préparation, la correction et les autres tâches hors cours.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Pourquoi certains enseignants ont-ils besoin d’un soutien supplémentaire dans les zones de crise ?", "options": ["Ils ne rencontrent aucune difficulté particulière dans leur travail", "Ils n’ont jamais besoin d’aucun soutien dans leur pratique", "Ils ont beaucoup trop de vacances et de jours de congé", "Ils font face à des conditions dangereuses et à des traumatismes"], "answer": 3, "explain": "Les enseignants en crise peuvent avoir besoin de formation et d’un soutien pour leur bien-être.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "Qu’est-ce que la dépense d’éducation par élève ?", "options": ["La dépense moyenne consacrée à chaque élève", "Le nombre total de livres disponibles dans chaque école primaire", "Le coût total d’organisation d’un seul examen national", "Le coût d’une ligne de bus scolaire sur une année complète"], "answer": 0, "explain": "La dépense par élève permet de comparer les ressources entre les systèmes.", "src": "UNESCO"}, {"ch": 7, "q": "Pourquoi le partage des coûts peut-il poser problème pour l’accès ?", "options": ["Il réduit toujours les coûts supportés par les familles de la communauté", "Il peut faire peser les coûts sur des familles qui ne peuvent pas les payer", "Il n’a aucun impact sur l’accès à l’école pour les élèves", "Il supprime complètement tous les frais que paient les familles"], "answer": 1, "explain": "Le partage des coûts peut créer des obstacles pour les familles pauvres s’il n’est pas bien géré.", "src": "UNESCO"}, {"ch": 7, "q": "Qu’est-ce que l’allègement de la dette pour l’éducation ?", "options": ["Augmenter la dette publique pour financer uniquement le sport scolaire", "Fermer immédiatement toutes les écoles publiques du pays", "Réduire les remboursements de dette pour que l’argent aille aux écoles", "Obliger les enseignants à rembourser les dettes de l’administration"], "answer": 2, "explain": "L’allègement de la dette peut libérer des fonds pour l’éducation.", "src": "UNESCO GEM Report 2026"}, {"ch": 7, "q": "Qu’est-ce que le financement innovant pour l’éducation ?", "options": ["Payer les enseignants uniquement en or et en pierres précieuses", "Vendre seulement le mobilier scolaire usagé chaque année scolaire", "Fermer systématiquement des écoles pour réaliser des économies", "De nouvelles façons de lever des fonds pour l’éducation"], "answer": 3, "explain": "Le financement innovant comprend de nouveaux mécanismes pour mobiliser des fonds.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "Qu’est-ce qu’un plan de financement de l’éducation ?", "options": ["Un plan qui montre comment l’éducation sera financée dans la durée", "Un plan réservé aux seules vacances scolaires, sans cours", "Un plan pour acheter des voitures et des camionnettes pour le personnel", "Un plan sans aucun chiffre, coût ou date"], "answer": 0, "explain": "Un plan de financement relie les objectifs éducatifs à l’argent nécessaire pour les atteindre.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "Qu’est-ce que la décentralisation budgétaire en éducation ?", "options": ["Transférer chaque année tout l’argent de l’éducation vers la capitale du pays", "Donner aux collectivités locales plus de contrôle sur les fonds de l’éducation", "Interdire aux collectivités locales de prendre la moindre décision", "Fermer les écoles locales une à une jusqu’à ce qu’il n’en reste aucune"], "answer": 1, "explain": "La décentralisation peut améliorer la réactivité locale, mais elle exige des garanties d’équité.", "src": "UNESCO"}, {"ch": 7, "q": "Qu’est-ce qu’une dotation de péréquation ?", "options": ["De l’argent qui enrichit encore davantage les zones riches chaque année", "De l’argent seulement pour les vacances et les congés des enseignants", "Des fonds supplémentaires qui aident les zones pauvres à rattraper les zones riches", "De l’argent pour fermer des écoles dans les zones pauvres chaque année"], "answer": 2, "explain": "Les dotations de péréquation réduisent les écarts entre régions.", "src": "UNESCO"}, {"ch": 7, "q": "Qu’est-ce qu’une clause de caducité dans le financement de l’éducation ?", "options": ["Une clause qui traite du coucher du soleil et des couleurs du ciel", "Une règle qui organise les soirées dansantes au sein des écoles", "Une règle qui double automatiquement le financement chaque jour", "Une règle qui met fin au financement après un délai, sauf renouvellement"], "answer": 3, "explain": "Les clauses de caducité mettent fin aux programmes sauf s’ils sont réexaminés et renouvelés.", "src": "UNESCO"}, {"ch": 7, "q": "Qu’est-ce que les recettes publiques pour l’éducation ?", "options": ["L’argent que l’État perçoit par l’impôt et d’autres sources", "L’argent des billets de sport vendus au stade national chaque année", "L’argent des frais de scolarité payés seulement par les familles, sans impôt", "L’argent gagné uniquement grâce au tourisme et aux voyages chaque année"], "answer": 0, "explain": "Les recettes publiques sont la principale base du financement public de l’éducation.", "src": "UNESCO"}, {"ch": 8, "q": "Que promouvait la Déclaration de Salamanque ?", "options": ["Des écoles réservées aux enfants séparés des autres", "Des écoles inclusives pour tous les enfants", "Des écoles réservées aux seuls adultes", "Des écoles réservées aux seuls enseignants"], "answer": 1, "explain": "La Déclaration de Salamanque promouvait l’inclusion des enfants ayant des besoins particuliers.", "src": "UN CRPD (2006), Article 24"}, {"ch": 8, "q": "En quelle année la Déclaration universelle des droits de l’homme a-t-elle été adoptée ?", "options": ["1989", "1990", "1948", "2015"], "answer": 2, "explain": "La DUDH a été adoptée par l’Assemblée générale de l’ONU en 1948.", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "Quelle convention énonce les droits de l’enfant, dont l’éducation ?", "options": ["Le Traité sur le commerce", "La Charte sportive de Genève", "Le Code maritime de Tokyo", "La Convention relative aux droits de l’enfant"], "answer": 3, "explain": "La CDE, adoptée en 1989, énonce les droits de l’enfant, dont le droit à l’éducation.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 8, "q": "À quoi s’étaient engagés les objectifs de Dakar pour la petite enfance ?", "options": ["Étendre et améliorer l’accueil et l’éducation de la petite enfance", "Fermer les services de petite enfance dans tout le pays", "Ignorer complètement les jeunes enfants et leurs familles", "Interdire les écoles maternelles dans chaque village et chaque ville"], "answer": 0, "explain": "Les objectifs de Dakar comprenaient l’extension et l’amélioration de l’accueil et de l’éducation de la petite enfance.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "Que visait la Déclaration d’Incheon pour 2030 ?", "options": ["Seulement l’enseignement supérieur pour les meilleurs élèves de chaque année", "Une éducation inclusive, équitable, de qualité et un apprentissage tout au long de la vie", "Seulement du sport et des jeux dans chaque école du pays", "Seulement des écoles d’été dans chaque région pendant les mois d’été"], "answer": 1, "explain": "La Déclaration d’Incheon a fixé cet objectif pour 2030.", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "Pourquoi les ODD de 2015 sont-ils allés plus loin que les OMD ?", "options": ["Ils ne concernent que les pays pauvres du monde et personne d’autre", "Ils ne couvrent que l’éducation et rien d’autre dans le monde", "Ils sont universels et couvrent des enjeux plus larges comme le climat et les inégalités", "Ils ont mis fin à toute aide aux pays les plus pauvres du monde"], "answer": 2, "explain": "Les ODD s’appliquent à tous les pays et couvrent davantage d’enjeux que les OMD.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "Quel est l’objectif de l’éducation en vue du développement durable (EDD) ?", "options": ["Enseigner uniquement les lois environnementales", "Fermer les cours de sciences", "Arrêter d’étudier les thèmes environnementaux", "Préparer les élèves à agir pour un avenir durable"], "answer": 3, "explain": "L’EDD aide les élèves à comprendre le développement durable et à passer à l’action.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "Que fait le Rapporteur spécial de l’ONU sur le droit à l’éducation ?", "options": ["Il rend compte du droit à l’éducation dans le monde", "Il dirige une école et supervise son personnel enseignant au quotidien", "Il arbitre des matchs de football dans les ligues professionnelles", "Il gère une banque et supervise ses opérations financières"], "answer": 0, "explain": "Le Rapporteur spécial de l’ONU rend compte du droit à l’éducation dans le monde.", "src": "UN Special Rapporteur on the Right to Education"}, {"ch": 9, "q": "Qu’est-ce qui façonne principalement le développement du cerveau pendant les premières années ?", "options": ["La couleur et le type des jouets disponibles dans la classe", "Les expériences vécues et les relations", "Le nombre total de bus scolaires qui circulent dans la ville", "Le prix des uniformes scolaires achetés chaque année en ville"], "answer": 1, "explain": "Les relations et les expériences façonnent le développement du cerveau dans la petite enfance.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Pourquoi les politiques de la petite enfance ont-elles besoin d’une coordination intersectorielle ?", "options": ["Les enfants n’ont besoin que d’éducation en classe pour bien apprendre", "Les enfants n’ont besoin que de soins de santé pour s’épanouir", "Les besoins de l’enfant touchent la santé, la nutrition et l’apprentissage", "Les enfants n’ont besoin d’aucun service ni d’aucune famille"], "answer": 2, "explain": "La coordination aide à répondre aux besoins des enfants dans les différents services.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Qu’est-ce qu’un indice de développement de la petite enfance ?", "options": ["Une mesure de l’état et de la taille de tous les bâtiments scolaires", "Un décompte des animaux de compagnie que possèdent les enseignants", "Une liste de tous les jours fériés nationaux et locaux de l’année", "Une mesure de la préparation des enfants dans des domaines clés"], "answer": 3, "explain": "Les indices de développement suivent la préparation des enfants dans plusieurs domaines.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Qu’est-ce que les interactions riches en langage dans la petite enfance ?", "options": ["Une conversation qui enrichit le vocabulaire et la compréhension", "Un jeu silencieux avec des jouets, sans parler dans la pièce", "Des cris constants adressés aux enfants toute la journée à la maison", "Regarder seulement la télévision pendant des heures chaque jour"], "answer": 0, "explain": "Les interactions riches en langage favorisent la lecture et l’apprentissage ultérieurs.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Qu’est-ce que le repérage précoce et l’orientation ?", "options": ["Ignorer les enfants qui ont besoin d’aide à l’école et à la maison", "Repérer les enfants qui ont besoin d’aide et les relier aux services", "Étiqueter les enfants de façon permanente avec une étiquette rigide", "Renvoyer les enfants chez eux dès qu’ils montrent un besoin d’aide"], "answer": 1, "explain": "Les dispositifs d’orientation relient les enfants au bon soutien dès le plus jeune âge.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Qu’est-ce que le soutien aux familles dans la petite enfance ?", "options": ["Éloigner les enfants de leur famille et de leur domicile", "Interdire les visites des familles à l’école toute l’année", "Une aide pour que les familles s’occupent et éduquent les jeunes enfants", "Ignorer complètement les familles dans chaque décision scolaire"], "answer": 2, "explain": "Le soutien aux familles renforce l’apprentissage à la maison et le bien-être.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Comment la santé de l’enfant est-elle liée à l’apprentissage ?", "options": ["La santé n’a aucun lien avec l’apprentissage dans aucune école", "Les enfants malades apprennent plus vite que les enfants en bonne santé", "La santé n’importe que lorsque la journée d’école est définitivement terminée", "Une bonne santé favorise l’assiduité, l’attention et le développement"], "answer": 3, "explain": "La santé de l’enfant est étroitement liée aux résultats d’apprentissage.", "src": "UN 2030 Agenda (2015)"}, {"ch": 10, "q": "Qu’est-ce que la littératie tout au long de la vie ?", "options": ["Continuer à développer ses compétences de lecture et d’écriture toute sa vie", "Lire seulement pendant l’enfance, puis plus jamais ensuite", "Lire seulement à l’école, jamais à la maison ni ailleurs", "Lire seulement pour le travail et rien d’autre pendant toute sa vie"], "answer": 0, "explain": "La littératie tout au long de la vie signifie continuer à lire et à écrire au fil de la vie.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Que sont les compétences de lecture pour s’informer ?", "options": ["Lire uniquement de la fiction, surtout des romans et des contes", "Repérer et utiliser des faits dans les textes", "Lire uniquement de la poésie et des textes littéraires", "Lire sans but précis, par simple habitude"], "answer": 1, "explain": "La lecture pour s’informer aide à trouver des faits pour prendre des décisions.", "src": "UNESCO"}, {"ch": 10, "q": "Qu’est-ce que la lisibilité d’un texte ?", "options": ["Le poids et le volume qu’un livre occupe dans un sac à dos", "Le nombre exact de pages et de chapitres que contient un livre", "La facilité avec laquelle un texte se lit et se comprend", "Le prix qu’il faut payer en librairie pour acheter un livre neuf"], "answer": 2, "explain": "La lisibilité dépend de la langue, de la longueur des phrases et du vocabulaire.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "Qu’est-ce que l’écart de genre en littératie ?", "options": ["Des différences de taille moyenne entre filles et garçons", "Des différences de pointure entre filles et garçons", "Des différences de couleurs préférées entre filles et garçons", "Des différences de compétences en lecture entre filles et garçons"], "answer": 3, "explain": "Les écarts de genre en littératie varient selon les pays et exigent des réponses ciblées.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 10, "q": "Qu’est-ce que l’accès aux supports imprimés dans les contextes peu dotés ?", "options": ["L’accès à des supports imprimés pour lire", "Interdire complètement toute impression de documents", "Imprimer uniquement de la monnaie pour l’État", "Imprimer seulement des cartes détaillées de la surface de la Lune"], "answer": 0, "explain": "L’accès aux supports imprimés aide les élèves des contextes peu dotés à s’exercer à la lecture.", "src": "UNESCO"}, {"ch": 10, "q": "Qu’est-ce qu’une politique de littératie en langue maternelle ?", "options": ["Une politique qui interdit les langues maternelles dans toutes les écoles du pays", "Une politique qui enseigne la lecture initiale dans la langue parlée par les enfants", "Une politique qui enseigne seulement l’anglais dans toutes les classes de chaque école", "Une politique qui enseigne seulement la langue des signes dans toutes les classes dès six ans"], "answer": 1, "explain": "La littératie en langue maternelle favorise la lecture initiale et l’identité.", "src": "UNESCO, International Mother Language Day"}, {"ch": 10, "q": "Qu’est-ce que la littératie pour le développement ?", "options": ["Une littératie sans aucun but dans la vie quotidienne ou au travail", "Une littératie réservée aux touristes qui visitent le pays chaque année", "Utiliser la littératie pour améliorer la santé, l’emploi et la vie communautaire", "Une littératie qui s’arrête quand chaque enfant atteint dix ans"], "answer": 2, "explain": "La littératie soutient le développement dans les domaines de la santé, du travail et de la vie civique.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Qu’est-ce qu’un programme de lecture plaisir ?", "options": ["Un programme qui interdit les livres d’histoires pour enfants", "Un programme qui évalue seulement l’orthographe", "Un programme qui arrête la lecture à l’âge de dix ans", "Un programme qui encourage les enfants à lire pour le plaisir"], "answer": 3, "explain": "La lecture plaisir crée la motivation et les habitudes qui soutiennent la littératie tout au long de la vie.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 11, "q": "Que signifie l’inclusion comme principe des droits humains en éducation ?", "options": ["Chaque élève a sa place et participe", "Certains élèves sont mis à part", "Les élèves sont séparés selon leurs capacités", "Les élèves sont exclus par conception"], "answer": 0, "explain": "L’inclusion est un principe des droits humains qui garantit l’appartenance et la participation.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Qu’est-ce que la formation inclusive des enseignants ?", "options": ["Former les enseignants à enseigner seulement aux meilleurs élèves", "Former les enseignants à enseigner à tous les élèves", "Former les enseignants à éviter les élèves handicapés", "Former les enseignants uniquement au sport"], "answer": 1, "explain": "La formation inclusive prépare les enseignants à des classes diversifiées.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Que signifie le soutien individualisé dans une école inclusive ?", "options": ["Un soutien réservé à l’établissement dans son ensemble et non aux élèves", "Un soutien uniquement pour les meilleurs élèves de chaque niveau scolaire", "Une aide adaptée aux besoins propres de chaque élève", "Absolument aucun soutien pour aucun élève, à aucun moment de l’année"], "answer": 2, "explain": "Le soutien individualisé adapte l’aide à chaque élève.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Qu’est-ce que l’inclusion du handicap dans les programmes ?", "options": ["Exclure le handicap de tous les cours dispensés en classe", "Enseigner le handicap comme une punition pour les élèves indisciplinés", "Enseigner le handicap seulement en cours d’éducation physique chaque semaine", "Intégrer le handicap dans l’apprentissage de la diversité"], "answer": 3, "explain": "L’inclusion du handicap dans les programmes favorise le respect et la compréhension.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Qu’est-ce que l’évaluation participative pour l’inclusion ?", "options": ["Associer les élèves au jugement de leurs propres progrès", "Évaluer les élèves en secret sans jamais le leur dire ni les informer", "Ignorer complètement l’avis des élèves sur la qualité de leur travail", "Évaluer les élèves seulement selon leur taille et leur apparence"], "answer": 0, "explain": "L’évaluation participative développe la conscience de soi et l’inclusion.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Qu’est-ce que le recrutement inclusif des enseignants ?", "options": ["Recruter seulement dans un seul groupe", "Recruter des enseignants issus de groupes divers", "Refuser toutes les candidatures", "Recruter uniquement selon les liens familiaux"], "answer": 1, "explain": "Le recrutement inclusif aide les écoles à refléter les communautés qu’elles servent.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 11, "q": "Que sont les données inclusives sur le handicap ?", "options": ["Des données qui cachent complètement le handicap au public", "Des données sur le handicap seulement dans le sport et les jeux chaque saison", "Des données qui incluent les personnes handicapées et leurs besoins", "Des données qui ne sont jamais recueillies dans aucune école ou district"], "answer": 2, "explain": "Les données inclusives aident les politiques à répondre aux besoins liés au handicap.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Pourquoi le droit à l’éducation est-il appelé un droit multiplicateur ?", "options": ["Parce qu’il multiplie le prix des livres scolaires", "Parce qu’il double les frais de scolarité", "Parce qu’il ne concerne que les enseignants", "Parce qu’il permet d’accéder à d’autres droits"], "answer": 3, "explain": "L’éducation permet d’accéder à la santé, au travail, à la participation politique et à d’autres droits.", "src": "UN Special Rapporteur on the Right to Education"}]};
